// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {FloatMath} from "../math/FloatMath.sol";
import {ElementaryMath} from "../math/ElementaryMath.sol";

/// @notice U = k*(1+cos(n*phi-phase)); phi uses the documented oriented normals.
/// @dev Unwrapped coordinates; n=1..6, phase in [-2*pi,2*pi]. Collinear bonds reject.
contract PeriodicTorsionKernel {
    error InvalidDependencies();
    error InvalidParameter();
    error NonFiniteInput();
    error SingularGeometry();
    FloatMath public immutable numericalMath;
    ElementaryMath public immutable elementaryMath;
    bytes32 public constant KERNEL_ID = keccak256("ORVIA.PeriodicTorsionKernel.v0.3");
    struct Input { bytes16[3] a; bytes16[3] b; bytes16[3] c; bytes16[3] d; uint32 n; bytes16 k; bytes16 phase; }
    struct Work {
        bytes16[3] b1; bytes16[3] b2; bytes16[3] b3; bytes16[3] n1; bytes16[3] n2;
        bytes16[3] hat; bytes16[3] cross; bytes16[3] gn1; bytes16[3] gn2; bytes16[3] gh;
        bytes16[3] gb1; bytes16[3] gb2; bytes16[3] gb3;
        bytes16 length; bytes16 x; bytes16 y; bytes16 denom; bytes16 gx; bytes16 gy; bytes16 derivative;
    }
    struct Result { bytes16 energy; bytes16[3] a; bytes16[3] b; bytes16[3] c; bytes16[3] d; }
    bytes16 private constant ONE = 0x3fff0000000000000000000000000000;

    constructor(address math_, address elementary_) {
        if (math_.code.length == 0 || elementary_.code.length == 0 ||
            address(ElementaryMath(elementary_).numericalMath()) != math_) revert InvalidDependencies();
        numericalMath = FloatMath(math_); elementaryMath = ElementaryMath(elementary_);
    }

    function evaluate(bytes16[3] calldata a, bytes16[3] calldata b, bytes16[3] calldata c, bytes16[3] calldata d,
        uint32 periodicity, bytes16 k, bytes16 phase) external view
        returns (bytes16 energy, bytes16[3] memory forceA, bytes16[3] memory forceB, bytes16[3] memory forceC, bytes16[3] memory forceD)
    {
        Input memory input;
        input.a=a; input.b=b; input.c=c; input.d=d; input.n=periodicity; input.k=k; input.phase=phase;
        Result memory r = _evaluate(input);
        return (r.energy,r.a,r.b,r.c,r.d);
    }

    function _evaluate(Input memory p) private view returns (Result memory r) {
        FloatMath m = numericalMath;
        if (!m.isFinite(p.k) || !m.isFinite(p.phase)) revert NonFiniteInput();
        if (p.n == 0 || p.n > 6 || m.isNegative(p.k) || m.compare(m.abs(p.phase), elementaryMath.TWO_PI()) > 0) revert InvalidParameter();
        for (uint256 i; i < 3; ++i) {
            if (!m.isFinite(p.a[i]) || !m.isFinite(p.b[i]) || !m.isFinite(p.c[i]) || !m.isFinite(p.d[i])) revert NonFiniteInput();
        }
        Work memory w;
        w.b1=_sub(p.b,p.a); w.b2=_sub(p.c,p.b); w.b3=_sub(p.d,p.c);
        w.n1=_cross(w.b1,w.b2); w.n2=_cross(w.b2,w.b3);
        w.length=_dot(w.b2,w.b2);
        if (m.isZero(w.length) || m.isZero(_dot(w.n1,w.n1)) || m.isZero(_dot(w.n2,w.n2))) revert SingularGeometry();
        w.length=m.sqrt(w.length); w.hat=_scale(w.b2,m.div(ONE,w.length));
        if (m.isZero(p.k)) return r;
        w.cross=_cross(w.n1,w.n2); w.x=_dot(w.n1,w.n2); w.y=_dot(w.hat,w.cross);
        bytes16 phi=elementaryMath.atan2(w.y,w.x);
        (bytes16 sine,bytes16 cosine)=elementaryMath.sinCos(m.sub(m.mul(m.fromUInt(p.n),phi),p.phase));
        r.energy=m.mul(p.k,m.add(ONE,cosine));
        w.derivative=m.neg(m.mul(m.mul(p.k,m.fromUInt(p.n)),sine));
        w.denom=m.add(m.mul(w.x,w.x),m.mul(w.y,w.y));
        if (m.isZero(w.denom)) revert SingularGeometry();
        w.gx=m.div(m.neg(w.y),w.denom); w.gy=m.div(w.x,w.denom);
        w.gn1=_add(_scale(w.n2,w.gx),_scale(_cross(w.n2,w.hat),w.gy));
        w.gn2=_add(_scale(w.n1,w.gx),_scale(_cross(w.hat,w.n1),w.gy));
        w.gh=_scale(w.cross,w.gy);
        w.gb1=_cross(w.b2,w.gn1);
        w.gb2=_add(_add(_cross(w.gn1,w.b1),_cross(w.b3,w.gn2)),
            _scale(_sub(w.gh,_scale(w.hat,_dot(w.hat,w.gh))),m.div(ONE,w.length)));
        w.gb3=_cross(w.gn2,w.b2);
        // Reverse chain rule through b1=b-a, b2=c-b and b3=d-c; force=-gradient(U).
        r.a=_scale(w.gb1,w.derivative);
        r.b=_scale(_sub(w.gb2,w.gb1),w.derivative);
        r.c=_scale(_sub(w.gb3,w.gb2),w.derivative);
        r.d=_scale(w.gb3,m.neg(w.derivative));
    }
    function _dot(bytes16[3] memory a, bytes16[3] memory b) private view returns(bytes16 s) {
        for(uint256 i;i<3;++i) s=numericalMath.add(s,numericalMath.mul(a[i],b[i]));
    }
    function _cross(bytes16[3] memory a, bytes16[3] memory b) private view returns(bytes16[3] memory c) {
        for(uint256 i;i<3;++i) c[i]=numericalMath.sub(numericalMath.mul(a[(i+1)%3],b[(i+2)%3]),numericalMath.mul(a[(i+2)%3],b[(i+1)%3]));
    }
    function _add(bytes16[3] memory a, bytes16[3] memory b) private view returns(bytes16[3] memory c) {
        for(uint256 i;i<3;++i)c[i]=numericalMath.add(a[i],b[i]);
    }
    function _sub(bytes16[3] memory a, bytes16[3] memory b) private view returns(bytes16[3] memory c) {
        for(uint256 i;i<3;++i)c[i]=numericalMath.sub(a[i],b[i]);
    }
    function _scale(bytes16[3] memory a, bytes16 k) private view returns(bytes16[3] memory c) {
        for(uint256 i;i<3;++i)c[i]=numericalMath.mul(a[i],k);
    }
}

contracts/kernels/LennardJonesKernel.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {FloatMath} from "../math/FloatMath.sol";

/// @notice One unswitched Lennard-Jones pair, U = 4*epsilon*((sigma/r)^12-(sigma/r)^6).
/// @dev Uses the supplied pair parameters and unwrapped displacement. There is
///      no cutoff, mixing rule, exclusion, periodic image or tail correction.
contract LennardJonesKernel {
    error InvalidMathContract();
    error NonFiniteInput();
    error NonPositiveSigma();
    error NegativeEpsilon();
    error ZeroSeparation();

    FloatMath public immutable numericalMath;
    bytes32 public constant KERNEL_ID = keccak256("ORVIA.LennardJonesKernel.v0.2");

    constructor(address numericalMath_) {
        if (numericalMath_.code.length == 0) revert InvalidMathContract();
        numericalMath = FloatMath(numericalMath_);
    }

    function evaluate(bytes16[3] calldata a, bytes16[3] calldata b, bytes16 sigma, bytes16 epsilon)
        external
        view
        returns (bytes16 energy, bytes16[3] memory forceOnA)
    {
        FloatMath m = numericalMath;
        if (!m.isFinite(sigma) || !m.isFinite(epsilon)) revert NonFiniteInput();
        if (m.isNegative(sigma) || m.isZero(sigma)) revert NonPositiveSigma();
        if (m.isNegative(epsilon)) revert NegativeEpsilon();

        bytes16[3] memory displacement;
        bytes16 rSquared;
        for (uint256 axis; axis < 3; ++axis) {
            if (!m.isFinite(a[axis]) || !m.isFinite(b[axis])) revert NonFiniteInput();
            displacement[axis] = m.sub(b[axis], a[axis]);
            rSquared = m.add(rSquared, m.mul(displacement[axis], displacement[axis]));
        }
        if (m.isZero(rSquared)) revert ZeroSeparation();
        // Zero strength still requires valid, nonsingular geometry.
        if (m.isZero(epsilon)) return (energy, forceOnA);

        bytes16 ratioSquared = m.div(m.mul(sigma, sigma), rSquared);
        bytes16 ratioSixth = m.mul(m.mul(ratioSquared, ratioSquared), ratioSquared);
        bytes16 ratioTwelfth = m.mul(ratioSixth, ratioSixth);
        // The constants 2, 4 and 24 have exact binary128 representations.
        bytes16 fourEpsilon = m.mul(bytes16(0x40010000000000000000000000000000), epsilon);
        energy = m.mul(fourEpsilon, m.sub(ratioTwelfth, ratioSixth));
        bytes16 radialNumerator = m.mul(
            m.mul(bytes16(0x40038000000000000000000000000000), epsilon),
            m.sub(ratioSixth, m.mul(bytes16(0x40000000000000000000000000000000), ratioTwelfth))
        );
        // For d = b-a, F_A = (dU/dr)*d/r. F_B is the negative of F_A.
        bytes16 scale = m.div(radialNumerator, rSquared);
        for (uint256 axis; axis < 3; ++axis) {
            forceOnA[axis] = m.mul(scale, displacement[axis]);
        }
    }
}

contracts/kernels/SoftcoreLennardJonesKe.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
import {FloatMath} from "../math/FloatMath.sol";

/// @notice Two-endpoint softcore LJ energy, force and lambda derivative.
/// @dev Unswitched pair primitive. It is not a complete hybrid force field.
contract SoftcoreLennardJonesKernel {
    error InvalidInput();
    error SingularEndpoint();
    FloatMath public immutable numericalMath;
    bytes32 public constant KERNEL_ID = keccak256("ORVIA.SoftcoreLennardJonesKernel.v1");
    bytes16 private constant ONE = 0x3fff0000000000000000000000000000;
    struct Endpoint { bytes16 sigma; bytes16 epsilon; }
    struct Configuration { Endpoint a; Endpoint b; bytes16 lambda; bytes16 alpha; }
    struct Terms { bytes16 energy; bytes16 derivative; bytes16 lambdaDerivative; }
    struct Combined { bytes16 energy; bytes16 derivative; bytes16 lambdaDerivative; }

    constructor(address math_) {
        if (math_.code.length == 0) revert InvalidInput();
        numericalMath = FloatMath(math_);
    }

    /// @dev d=B-A; rho_A=r^6+alpha*sigma_A^6*lambda^2,
    ///      rho_B=r^6+alpha*sigma_B^6*(1-lambda)^2.
    function evaluate(bytes16[3] calldata d, Configuration calldata c)
        external view returns (bytes16 energy, bytes16[3] memory forceA, bytes16 derivativeLambda)
    {
        FloatMath m = numericalMath;
        _nonnegative(c.lambda); _positive(c.alpha);
        if (m.compare(c.lambda, ONE) > 0) revert InvalidInput();
        _positive(c.a.sigma); _nonnegative(c.a.epsilon); _positive(c.b.sigma); _nonnegative(c.b.epsilon);
        bytes16 r2;
        for (uint256 axis; axis < 3; ++axis) {
            _finite(d[axis]); r2 = m.add(r2, m.mul(d[axis], d[axis]));
        }
        bytes16 r4 = m.mul(r2,r2);
        Combined memory result = _combine(c,m.mul(r4,r2));
        energy = result.energy;
        derivativeLambda = result.lambdaDerivative;
        bytes16 coefficient = m.mul(m.mul(m.fromUInt(6),r4),result.derivative);
        for (uint256 axis; axis < 3; ++axis) forceA[axis] = m.mul(coefficient,d[axis]);
    }

    function _combine(Configuration memory c, bytes16 r6) private view returns(Combined memory result) {
        FloatMath m = numericalMath;
        bytes16 complement = m.sub(ONE,c.lambda);
        Terms memory ta = _endpoint(c.a,r6,c.lambda,c.alpha);
        Terms memory tb = _endpoint(c.b,r6,complement,c.alpha);
        result.energy = m.add(m.mul(complement,ta.energy),m.mul(c.lambda,tb.energy));
        result.derivative = m.add(m.mul(complement,ta.derivative),m.mul(c.lambda,tb.derivative));
        result.lambdaDerivative = m.sub(tb.energy,ta.energy);
        result.lambdaDerivative = m.add(result.lambdaDerivative,m.mul(complement,ta.lambdaDerivative));
        result.lambdaDerivative = m.sub(result.lambdaDerivative,m.mul(c.lambda,tb.lambdaDerivative));
    }

    function _endpoint(Endpoint memory p, bytes16 r6, bytes16 softening, bytes16 alpha)
        private view returns (Terms memory t)
    {
        FloatMath m = numericalMath;
        if (m.isZero(p.epsilon)) return t;
        bytes16 s6;
        {
            bytes16 s2 = m.mul(p.sigma,p.sigma);
            s6 = m.mul(s2,s2);
            s6 = m.mul(s6,s2);
        }
        _positive(s6);
        bytes16 alphaS6 = m.mul(alpha,s6);
        bytes16 rho = m.mul(softening,softening);
        rho = m.mul(alphaS6,rho);
        rho = m.add(r6,rho);
        if (m.isZero(rho)) revert SingularEndpoint();
        bytes16 ratio = m.div(s6,rho);
        bytes16 fourEpsilon = m.mul(m.fromUInt(4),p.epsilon);
        t.energy = m.mul(ratio,ratio);
        t.derivative = m.mul(m.fromUInt(2),t.energy);
        t.derivative = m.sub(ratio,t.derivative);
        t.derivative = m.mul(fourEpsilon,t.derivative);
        t.derivative = m.div(t.derivative,rho);
        t.energy = m.sub(t.energy,ratio);
        t.energy = m.mul(fourEpsilon,t.energy);
        t.lambdaDerivative = m.mul(alphaS6,softening);
        t.lambdaDerivative = m.mul(m.fromUInt(2),t.lambdaDerivative);
        t.lambdaDerivative = m.mul(t.derivative,t.lambdaDerivative);
    }

    function _finite(bytes16 x) private view { if (!numericalMath.isFinite(x)) revert InvalidInput(); }
    function _nonnegative(bytes16 x) private view { _finite(x); if(numericalMath.compare(x,bytes16(0))<0) revert InvalidInput(); }
    function _positive(bytes16 x) private view { _finite(x); if(numericalMath.compare(x,bytes16(0))<=0) revert InvalidInput(); }
}

