// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {EwaldKernelBase} from "./EwaldKernelBase.sol";
import {FloatMath} from "../math/FloatMath.sol";

/// @notice Tin-foil Ewald self, neutralizing-background and pair-exception terms.
contract EwaldCorrections is EwaldKernelBase {
    bytes32 public constant KERNEL_ID =
        keccak256("ORVIA.EwaldCorrections.v0.5");
    bytes16 private constant HALF = 0x3ffe0000000000000000000000000000;
    struct ExceptionParameters {
        bytes16 original;
        bytes16 desired;
        bytes16 prefactor;
        bytes16 alpha;
    }

    constructor(
        address math_,
        address scalar_
    ) EwaldKernelBase(math_, scalar_) {}

    function selfEnergy(
        bytes16 charge,
        bytes16 alpha,
        bytes16 prefactor
    ) external view returns (bytes16) {
        _finite(charge);
        _positive(alpha);
        _nonnegative(prefactor);
        FloatMath m = numericalMath;
        bytes16 result = m.mul(charge, charge);
        result = m.mul(result, INV_SQRT_PI);
        result = m.mul(result, alpha);
        result = m.neg(m.mul(result, prefactor));
        _finite(result);
        return result;
    }

    /// @notice Uniform neutralizing plasma: -K*pi*Q^2/(2*alpha^2*V).
    /// @dev Zero coordinate force at fixed volume; pressure derivatives are not returned.
    function backgroundEnergy(
        bytes16 totalCharge,
        bytes16[3] calldata box,
        bytes16 alpha,
        bytes16 prefactor
    ) external view returns (bytes16) {
        _finite(totalCharge);
        _positive(alpha);
        _nonnegative(prefactor);
        FloatMath m = numericalMath;
        bytes16 denominator = m.mul(alpha, alpha);
        denominator = m.mul(denominator, _volume(box));
        denominator = m.mul(TWO, denominator);
        bytes16 numerator = m.mul(totalCharge, totalCharge);
        numerator = m.mul(numerator, PI);
        numerator = m.mul(numerator, prefactor);
        bytes16 result = m.neg(m.div(numerator, denominator));
        _finite(result);
        return result;
    }

    /// @notice K*(desiredQ-originalQ*erf(alpha*r))/r, replacing an omitted real pair.
    /// @dev Reciprocal factors retain original atomic charges. Caller must omit this
    ///      pair's screened real term, then add this term once with no cutoff.
    function exception(
        bytes16[3] calldata displacement,
        bytes16 originalChargeProduct,
        bytes16 desiredChargeProduct,
        bytes16 prefactor,
        bytes16 alpha
    ) external view returns (bytes16 energy, bytes16[3] memory forceOnA) {
        return
            _exception(
                displacement,
                ExceptionParameters(
                    originalChargeProduct,
                    desiredChargeProduct,
                    prefactor,
                    alpha
                )
            );
    }

    function _exception(
        bytes16[3] memory displacement,
        ExceptionParameters memory p
    ) private view returns (bytes16 energy, bytes16[3] memory forceOnA) {
        _finite(p.original);
        _finite(p.desired);
        _nonnegative(p.prefactor);
        _positive(p.alpha);
        FloatMath m = numericalMath;
        bytes16 r2 = _normSquared(displacement);
        if (m.isZero(r2)) {
            for (uint256 axis; axis < 3; ++axis)
                if (!m.isZero(displacement[axis])) revert OutsideDomain();
            if (!m.isZero(p.desired)) revert ZeroSeparation();
            energy = m.mul(TWO, m.mul(p.alpha, INV_SQRT_PI));
            energy = m.mul(energy, p.original);
            energy = m.neg(m.mul(energy, p.prefactor));
            _finite(energy);
            return (energy, forceOnA);
        }
        bytes16 r = m.sqrt(r2);
        bytes16 x = m.mul(p.alpha, r);
        if (m.compare(x, SIXTEEN) > 0) revert OutsideDomain();
        bytes16 erfX = scalarMath.erf(x);
        energy = m.mul(p.original, erfX);
        energy = m.div(m.sub(p.desired, energy), r);
        energy = m.mul(p.prefactor, energy);
        bytes16 scale = m.mul(
            p.original,
            _gaussianForceScale(x, r, r2, p.alpha, erfX)
        );
        bytes16 direct = m.mul(r2, r);
        direct = m.div(p.desired, direct);
        scale = m.sub(scale, direct);
        scale = m.mul(p.prefactor, scale);
        _finite(energy);
        for (uint256 axis; axis < 3; ++axis) {
            forceOnA[axis] = m.mul(scale, displacement[axis]);
            _finite(forceOnA[axis]);
        }
    }

    /// @dev Stable (erf(x)-2*x*exp(-x*x)/sqrt(pi))/r^3 at small x.
    function _gaussianForceScale(
        bytes16 x,
        bytes16 r,
        bytes16 r2,
        bytes16 alpha,
        bytes16 erfX
    ) private view returns (bytes16) {
        FloatMath m = numericalMath;
        if (m.compare(x, HALF) <= 0) {
            bytes16 negativeSquared = m.neg(m.mul(x, x));
            bytes16 term = ONE;
            bytes16 sum = m.div(ONE, m.fromUInt(3));
            for (uint256 n = 1; n < 24; ++n) {
                term = m.div(m.mul(term, negativeSquared), m.fromUInt(n));
                sum = m.add(sum, m.div(term, m.fromUInt(2 * n + 3)));
            }
            bytes16 factor = m.mul(alpha, alpha);
            factor = m.mul(factor, alpha);
            factor = m.mul(factor, m.mul(FOUR, INV_SQRT_PI));
            return m.mul(factor, sum);
        }
        bytes16 gaussian = scalarMath.exp(m.neg(m.mul(x, x)));
        bytes16 numerator = m.mul(INV_SQRT_PI, gaussian);
        numerator = m.mul(numerator, x);
        numerator = m.mul(TWO, numerator);
        numerator = m.sub(erfX, numerator);
        return m.div(numerator, m.mul(r2, r));
    }
}

contracts/core/PeriodicCellIndex.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {ExperimentRegistry} from "./ExperimentRegistry.sol";
import {FloatMath} from "../math/FloatMath.sol";
import {OrthorhombicGeometry} from "../kernels/OrthorhombicGeometry.sol";
import {ABDKMathQuad} from "../math/vendor/ABDKMathQuad.sol";

interface ICellSnapshotWords {
    function writer() external view returns (address);
    function readWord(bytes32 namespace, uint256 index) external view returns (bytes32);
    function namespaceInfo(bytes32 namespace) external view returns (uint32 capacity, bool isSealed);
    function snapshotInfo(bytes32 namespace) external view returns (
        bytes32 source, uint64 epoch, uint32 capacity, bytes32 writeDigest, bytes32 commitment
    );
}

/// @notice Bounded on-chain periodic cell membership from an authenticated snapshot.
/// @dev Candidate generation only. No force evaluator uses this index yet. Cell
///      members retain ascending global atom order; callers must merge neighboring
///      lists in canonical order and retain the original exact pair cutoff test.
contract PeriodicCellIndex {
    error Unauthorized();
    error InvalidInput();
    error UnsupportedDomain();
    error DependencyChanged();
    error WrongStage();
    error InvalidCursor();

    uint256 public constant MAX_BUILD_WORK = 32;
    uint256 public constant MAX_QUERY_ATOMS = 128;
    uint256 public constant MAX_AXIS_CELLS = 64;
    bytes32 public constant POLICY_ID = keccak256("ORVIA.PeriodicCellIndex.v1.GuardedBinary128.Fixed64");
    bytes16 private constant TWO = 0x40000000000000000000000000000000;
    bytes16 private constant MIN_BOX = 0x3fdf0000000000000000000000000000; // 2^-32
    bytes16 private constant MAX_BOX = 0x401f0000000000000000000000000000; // 2^32
    bytes16 private constant MIN_CUTOFF = 0x3fbf0000000000000000000000000000; // 2^-64
    bytes16 private constant MAX_COORDINATE_RATIO = 0x401d0000000000000000000000000000; // 2^30
    bytes16 private constant GRID_GUARD = 0x3fff0000000100000000000000000000; // 1+2^-32

    address public immutable owner;
    ExperimentRegistry public immutable registry;
    FloatMath public immutable numericalMath;
    OrthorhombicGeometry public immutable geometry;
    bytes32 public immutable registryCodeHash;
    bytes32 public immutable mathCodeHash;
    bytes32 public immutable geometryCodeHash;
    uint256 public nextIndex = 1;

    enum Stage { Missing, Building, Ready }
    struct Input {
        bytes32 protocol;
        address sourcePage;
        bytes32 sourceNamespace;
        uint32 atoms;
        uint32 positionOffset;
        uint32 positionStride;
        bytes16[3] box;
        bytes16 cutoff;
    }
    struct Index {
        Input input;
        Stage stage;
        uint32 builtAtoms;
        uint8[3] dimensions;
        uint32 totalCells;
        bytes32 snapshotCommitment;
        bytes32 sourceCodeHash;
        address sourceWriter;
        bytes32 sourceWriterCodeHash;
        bytes32 manifestHash;
        bytes32 commitment;
    }
    struct Cell { uint32 head; uint32 tail; }
    mapping(uint256 => Index) private _indices;
    mapping(uint256 => mapping(uint32 => Cell)) private _cells;
    mapping(uint256 => mapping(uint32 => uint32)) private _atomCells;
    mapping(uint256 => mapping(uint32 => uint32)) private _next;

    event IndexRegistered(uint256 indexed id, bytes32 indexed snapshotCommitment, bytes32 commitment);
    event IndexAdvanced(uint256 indexed id, uint32 builtAtoms, bool complete);

    constructor(address owner_, address registry_, address math_, address geometry_) {
        if (owner_ == address(0) || registry_.code.length == 0 || geometry_.code.length == 0
            || math_.codehash != keccak256(type(FloatMath).runtimeCode)) revert InvalidInput();
        if (address(OrthorhombicGeometry(geometry_).numericalMath()) != math_
            || OrthorhombicGeometry(geometry_).GEOMETRY_ID() != keccak256("ORVIA.OrthorhombicGeometry.v0.4")) revert InvalidInput();
        owner = owner_; registry = ExperimentRegistry(registry_); numericalMath = FloatMath(math_);
        geometry = OrthorhombicGeometry(geometry_);
        registryCodeHash = registry_.codehash; mathCodeHash = math_.codehash; geometryCodeHash = geometry_.codehash;
    }

    function registerIndex(Input calldata input) external returns (uint256 id) {
        if (msg.sender != owner) revert Unauthorized();
        if (input.atoms == 0 || input.positionStride < 3 || input.sourcePage.code.length == 0) revert InvalidInput();
        _dependencies(input.protocol);
        geometry.validateBox(input.box, input.cutoff);
        if (numericalMath.compare(input.cutoff, MIN_CUTOFF) < 0) revert UnsupportedDomain();
        (uint32 capacity, bool isSealed) = ICellSnapshotWords(input.sourcePage).namespaceInfo(input.sourceNamespace);
        (,,,,bytes32 snapshot) = ICellSnapshotWords(input.sourcePage).snapshotInfo(input.sourceNamespace);
        if (!isSealed || snapshot == bytes32(0) || uint256(input.positionOffset)
            + uint256(input.atoms - 1) * input.positionStride + 3 > capacity) revert InvalidInput();
        address sourceWriter = ICellSnapshotWords(input.sourcePage).writer();
        registry.assertModule(input.protocol, input.sourcePage, input.sourcePage.codehash);
        registry.assertModule(input.protocol, sourceWriter, sourceWriter.codehash);
        id = nextIndex++; Index storage index = _indices[id];
        index.input = input; index.stage = Stage.Building;
        index.snapshotCommitment = snapshot; index.sourceCodeHash = input.sourcePage.codehash;
        index.sourceWriter = sourceWriter; index.sourceWriterCodeHash = sourceWriter.codehash;
        index.manifestHash = registry.assertProtocol(input.protocol);
        bytes16 guardedCutoff = numericalMath.mul(input.cutoff, GRID_GUARD);
        uint32 total = 1;
        for (uint256 axis; axis < 3; ++axis) {
            if (numericalMath.compare(input.box[axis], MIN_BOX) < 0
                || numericalMath.compare(input.box[axis], MAX_BOX) > 0) revert UnsupportedDomain();
            bytes16 ratio = numericalMath.div(input.box[axis], guardedCutoff);
            uint256 cells = numericalMath.compare(ratio, numericalMath.fromUInt(MAX_AXIS_CELLS)) >= 0
                ? MAX_AXIS_CELLS : ABDKMathQuad.toUInt(ratio);
            if (cells == 0) revert UnsupportedDomain();
            index.dimensions[axis] = uint8(cells); total *= uint32(cells);
        }
        index.totalCells = total;
        index.commitment = keccak256(abi.encode(POLICY_ID, block.chainid, address(this), id, input,
            index.dimensions, index.manifestHash, snapshot, index.sourceCodeHash, sourceWriter,
            index.sourceWriterCodeHash, registryCodeHash, mathCodeHash, geometryCodeHash));
        emit IndexRegistered(id, snapshot, index.commitment);
    }

    function advanceBuild(uint256 id, uint256 work) external returns (uint256 processed, bool complete) {
        if (work == 0 || work > MAX_BUILD_WORK) revert InvalidInput();
        Index storage index = _get(id); _assertIndex(index);
        if (index.stage == Stage.Ready) return (0, true);
        while (processed < work && index.builtAtoms < index.input.atoms) {
            uint32 atom = index.builtAtoms;
            uint32 cell = _cellOf(index, _position(index, atom));
            Cell storage entry = _cells[id][cell]; uint32 pointer = atom + 1;
            if (entry.tail == 0) entry.head = pointer;
            else _next[id][entry.tail - 1] = pointer;
            entry.tail = pointer; _atomCells[id][atom] = cell;
            ++index.builtAtoms; ++processed;
        }
        complete = index.builtAtoms == index.input.atoms;
        if (complete) index.stage = Stage.Ready;
        emit IndexAdvanced(id, index.builtAtoms, complete);
    }

    /// @notice Derive and deduplicate the <=27 neighboring cells on chain.
    /// @dev Heads are atom+1 pointers; zero means an empty list. This does not
    ///      filter self/coincident atoms, exclusions or distance-to-cutoff.
    function neighboringCells(uint256 id, uint32 atom) external view returns (
        uint32[27] memory cellIds, uint32[27] memory heads, uint8 count
    ) {
        Index storage index = _ready(id); if (atom >= index.input.atoms) revert InvalidInput();
        uint32 cell = _atomCells[id][atom];
        for (uint256 choice; choice < 27; ++choice) {
            uint32 neighbor = _neighbor(cell, index.dimensions, choice);
            bool seen;
            for (uint256 i; i < count; ++i) if (cellIds[i] == neighbor) { seen = true; break; }
            if (!seen) { cellIds[count] = neighbor; heads[count] = _cells[id][neighbor].head; ++count; }
        }
    }

    function _neighbor(uint32 cell, uint8[3] memory dimensions, uint256 choice) private pure returns (uint32) {
        uint256 nx = dimensions[0]; uint256 ny = dimensions[1]; uint256 nz = dimensions[2];
        uint256 x = cell % nx; uint256 y = (cell / nx) % ny; uint256 z = cell / (nx * ny);
        return uint32((x + nx + choice % 3 - 1) % nx
            + nx * (((y + ny + (choice / 3) % 3 - 1) % ny) + ny * ((z + nz + choice / 9 - 1) % nz)));
    }

    /// @notice Read <=128 ascending atom IDs from one cell, with bounded work.
    /// @dev cursor=0 starts at the head. Returned next=0 means complete; stop then.
    ///      A nonzero cursor must be a real atom+1 member of this exact cell/index.
    function cellAtoms(uint256 id, uint32 cell, uint32 cursor, uint256 count) external view returns (
        uint32[] memory atoms, uint32 next, bool complete
    ) {
        Index storage index = _ready(id);
        if (cell >= index.totalCells || count == 0 || count > MAX_QUERY_ATOMS) revert InvalidInput();
        uint32 pointer = cursor == 0 ? _cells[id][cell].head : cursor;
        if (pointer > index.input.atoms || (pointer != 0 && _atomCells[id][pointer - 1] != cell)) revert InvalidCursor();
        atoms = new uint32[](count); uint256 used;
        while (pointer != 0 && used < count) {
            atoms[used++] = pointer - 1; pointer = _next[id][pointer - 1];
        }
        assembly { mstore(atoms, used) }
        return (atoms, pointer, pointer == 0);
    }

    function atomCell(uint256 id, uint32 atom) external view returns (uint32) {
        Index storage index = _ready(id); if (atom >= index.input.atoms) revert InvalidInput();
        return _atomCells[id][atom];
    }
    /// @notice The next atom+1 pointer in this atom's sorted cell list, or zero.
    function nextAtom(uint256 id, uint32 atom) external view returns (uint32) {
        Index storage index = _ready(id); if (atom >= index.input.atoms) revert InvalidInput();
        return _next[id][atom];
    }
    function indexInfo(uint256 id) external view returns (
        Stage stage, uint32 builtAtoms, uint8[3] memory dimensions, uint32 totalCells,
        bytes32 snapshotCommitment, bytes32 commitment, Input memory input
    ) {
        Index storage index = _get(id);
        return (index.stage, index.builtAtoms, index.dimensions, index.totalCells,
            index.snapshotCommitment, index.commitment, index.input);
    }

    function _cellOf(Index storage index, bytes16[3] memory position) private view returns (uint32) {
        FloatMath m = numericalMath;
        for (uint256 axis; axis < 3; ++axis) {
            if (m.compare(m.div(m.abs(position[axis]), index.input.box[axis]), MAX_COORDINATE_RATIO) > 0) revert UnsupportedDomain();
        }
        bytes16[3] memory zero;
        bytes16[3] memory periodic = geometry.displacement(zero, position, index.input.box);
        uint32 cell; uint32 multiplier = 1;
        for (uint256 axis; axis < 3; ++axis) {
            cell += _bin(periodic[axis], index.input.box[axis], index.dimensions[axis]) * multiplier;
            multiplier *= index.dimensions[axis];
        }
        return cell;
    }
    function _bin(bytes16 periodic, bytes16 length, uint8 cells) private view returns (uint32) {
        FloatMath m = numericalMath;
        bytes16 wrapped = m.add(periodic, m.div(length, TWO));
        if (m.compare(wrapped, bytes16(0)) < 0) revert UnsupportedDomain();
        if (m.compare(wrapped, length) >= 0) wrapped = bytes16(0);
        bytes16 scaled = m.mul(wrapped, m.fromUInt(cells));
        uint256 coordinate = ABDKMathQuad.toUInt(m.div(scaled, length));
        // A final rounding at the periodic upper boundary is the same cell
        // as zero; the documented conservative margin covers this binning.
        if (coordinate == cells) coordinate = 0;
        if (coordinate >= cells) revert UnsupportedDomain();
        return uint32(coordinate);
    }
    function _position(Index storage index, uint32 atom) private view returns (bytes16[3] memory position) {
        uint256 start = uint256(index.input.positionOffset) + uint256(atom) * index.input.positionStride;
        for (uint256 axis; axis < 3; ++axis) {
            bytes32 word = ICellSnapshotWords(index.input.sourcePage).readWord(index.input.sourceNamespace, start + axis);
            if (uint256(word) >> 128 != 0) revert InvalidInput();
            bytes16 value = bytes16(uint128(uint256(word)));
            if (!numericalMath.isFinite(value)) revert InvalidInput();
            position[axis] = value;
        }
    }
    function _dependencies(bytes32 protocol) private view {
        if (address(registry).codehash != registryCodeHash || address(numericalMath).codehash != mathCodeHash
            || address(geometry).codehash != geometryCodeHash) revert DependencyChanged();
        registry.assertModule(protocol, address(this), address(this).codehash);
        registry.assertModule(protocol, address(numericalMath), mathCodeHash);
        registry.assertModule(protocol, address(geometry), geometryCodeHash);
    }
    function _assertIndex(Index storage index) private view {
        _dependencies(index.input.protocol);
        if (registry.assertProtocol(index.input.protocol) != index.manifestHash
            || index.input.sourcePage.codehash != index.sourceCodeHash
            || index.sourceWriter.codehash != index.sourceWriterCodeHash) revert DependencyChanged();
        registry.assertModule(index.input.protocol, index.input.sourcePage, index.sourceCodeHash);
        registry.assertModule(index.input.protocol, index.sourceWriter, index.sourceWriterCodeHash);
        (,,,,bytes32 snapshot) = ICellSnapshotWords(index.input.sourcePage).snapshotInfo(index.input.sourceNamespace);
        if (snapshot != index.snapshotCommitment) revert DependencyChanged();
    }
    function _get(uint256 id) private view returns (Index storage index) {
        index = _indices[id]; if (index.stage == Stage.Missing) revert InvalidInput();
    }
    function _ready(uint256 id) private view returns (Index storage index) {
        index = _get(id); _assertIndex(index); if (index.stage != Stage.Ready) revert WrongStage();
    }
}

contracts/core/OrderedNeighborPairs.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {PeriodicCellIndex} from "./PeriodicCellIndex.sol";

/// @notice Canonical i<j traversal of an authenticated periodic cell index.
/// @dev Only the immutable consumer can pull pairs. Its force operation and this
///      cursor update must share a transaction, so a failure rolls both back.
///      This module is not connected to AlchemicalHamiltonianEvaluator yet.
contract OrderedNeighborPairs {
    error Unauthorized();
    error InvalidInput();
    error DependencyChanged();

    uint256 public constant MAX_WORK = 32;
    bytes32 public constant POLICY_ID = keccak256("ORVIA.OrderedNeighborPairs.v1.Packed27Heads");
    address public immutable owner;
    bytes32 public immutable ownerCodeHash;
    PeriodicCellIndex public immutable cellIndex;
    bytes32 public immutable cellIndexCodeHash;
    uint256 public nextTraversal = 1;

    struct Traversal {
        uint256 index;
        bytes32 indexCommitment;
        bytes32 commitment;
        uint32 atoms;
        uint32 row;
        uint8 headCount;
        bool initialized;
        bool complete;
        uint64 visited;
        uint64 emitted;
        uint256[4] heads;
    }
    mapping(uint256 => Traversal) private _traversals;
    event TraversalRegistered(uint256 indexed traversal, uint256 indexed index, bytes32 commitment);
    event TraversalAdvanced(uint256 indexed traversal, uint256 processed, uint32 row, bool complete);

    constructor(address owner_, address cellIndex_) {
        if (owner_.code.length == 0 || cellIndex_.code.length == 0) revert InvalidInput();
        if (PeriodicCellIndex(cellIndex_).POLICY_ID()
            != keccak256("ORVIA.PeriodicCellIndex.v1.GuardedBinary128.Fixed64")) revert InvalidInput();
        owner = owner_; ownerCodeHash = owner_.codehash;
        cellIndex = PeriodicCellIndex(cellIndex_); cellIndexCodeHash = cellIndex_.codehash;
    }

    modifier onlyOwner() {
        if (msg.sender != owner || owner.codehash != ownerCodeHash) revert Unauthorized();
        _;
    }

    function registerTraversal(uint256 index) external onlyOwner returns (uint256 id) {
        _dependencies();
        (PeriodicCellIndex.Stage stage,,,,,bytes32 indexCommitment,PeriodicCellIndex.Input memory input) = cellIndex.indexInfo(index);
        if (stage != PeriodicCellIndex.Stage.Ready) revert InvalidInput();
        cellIndex.atomCell(index, 0); // Recheck source, snapshot and complete protocol identity.
        id = nextTraversal++; Traversal storage traversal = _traversals[id];
        traversal.index = index; traversal.atoms = input.atoms; traversal.indexCommitment = indexCommitment;
        traversal.commitment = keccak256(abi.encode(POLICY_ID,block.chainid,address(this),id,
            owner,ownerCodeHash,address(cellIndex),cellIndexCodeHash,index,indexCommitment,input.atoms));
        emit TraversalRegistered(id,index,traversal.commitment);
    }

    /// @notice Consume bounded setup/pop/skip work and return at most one pair.
    /// @dev No externally supplied cursor or pair can change coverage. Zero useful
    ///      pairs is a valid page, but every nonterminal call consumes work.
    function advance(uint256 id, uint256 work) external onlyOwner returns (
        uint256 processed, bool found, uint32 a, uint32 b, bool complete
    ) {
        if (work == 0 || work > MAX_WORK) revert InvalidInput();
        _dependencies(); Traversal storage traversal = _get(id);
        cellIndex.atomCell(traversal.index, 0); // Required even after terminal completion.
        if (traversal.complete) return (0,false,0,0,true);
        while (processed < work && !traversal.complete) {
            ++processed;
            if (!traversal.initialized) { _beginRow(traversal); continue; }
            (uint32 pointer,uint256 position) = _minimum(traversal);
            if (pointer == 0) {
                ++traversal.row; traversal.initialized = false;
                if (traversal.row == traversal.atoms) traversal.complete = true;
                continue;
            }
            uint32 atom = pointer - 1;
            _setHead(traversal,position,cellIndex.nextAtom(traversal.index,atom));
            ++traversal.visited;
            if (atom > traversal.row) {
                ++traversal.emitted;
                emit TraversalAdvanced(id,processed,traversal.row,false);
                return (processed,true,traversal.row,atom,false);
            }
        }
        complete = traversal.complete;
        emit TraversalAdvanced(id,processed,traversal.row,complete);
    }

    function traversalInfo(uint256 id) external view returns (
        uint256 index, bytes32 indexCommitment, bytes32 commitment, uint32 atoms, uint32 row,
        bool complete, uint64 visited, uint64 emitted
    ) {
        Traversal storage traversal = _get(id);
        return (traversal.index,traversal.indexCommitment,traversal.commitment,traversal.atoms,
            traversal.row,traversal.complete,traversal.visited,traversal.emitted);
    }

    function _beginRow(Traversal storage traversal) private {
        (,uint32[27] memory heads,uint8 count) = cellIndex.neighboringCells(traversal.index,traversal.row);
        uint256[4] memory packed;
        for (uint256 i; i < count; ++i) packed[i / 8] |= uint256(heads[i]) << ((i % 8) * 32);
        traversal.heads = packed; traversal.headCount = count; traversal.initialized = true;
    }
    function _minimum(Traversal storage traversal) private view returns (uint32 pointer,uint256 position) {
        for (uint256 i; i < traversal.headCount; ++i) {
            uint32 head = uint32(traversal.heads[i / 8] >> ((i % 8) * 32));
            if (head != 0 && (pointer == 0 || head < pointer)) { pointer = head; position = i; }
        }
    }
    function _setHead(Traversal storage traversal,uint256 position,uint32 next) private {
        uint256 shift = (position % 8) * 32;
        uint256 mask = uint256(type(uint32).max) << shift;
        uint256 slot = position / 8;
        traversal.heads[slot] = (traversal.heads[slot] & ~mask) | (uint256(next) << shift);
    }
    function _dependencies() private view {
        if (address(cellIndex).codehash != cellIndexCodeHash) revert DependencyChanged();
    }
    function _get(uint256 id) private view returns (Traversal storage traversal) {
        traversal = _traversals[id]; if (traversal.commitment == bytes32(0)) revert InvalidInput();
    }
}

contracts/core/MolecularSimulationPipeli.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {AlchemicalTopologyCatalog} from "./AlchemicalTopologyCatalog.sol";
import {AlchemicalHamiltonianEvaluator,IProductionWordState} from "./AlchemicalHamiltonianEvaluator.sol";
import {ExperimentRegistry} from "./ExperimentRegistry.sol";
import {FloatMath} from "../math/FloatMath.sol";
import {LangevinBAOABKernel} from "../kernels/LangevinBAOABKernel.sol";
import {CounterRandom} from "../kernels/CounterRandom.sol";
import {ReducedPotentialCollector} from "../analysis/ReducedPotentialCollector.sol";
import {TimeSeriesDiagnostics} from "../analysis/TimeSeriesDiagnostics.sol";
import {MBARFreeEnergyEstimator} from "../analysis/MBARFreeEnergyEstimator.sol";
import {IMolecularCampaignSource} from "../interfaces/IMolecularCampaignSource.sol";
import {FullModelConstraintCatalog} from "./FullModelConstraintCatalog.sol";
import {FullModelConstraintSolver} from "./FullModelConstraintSolver.sol";

/// @notice Authenticated NVT dynamics -> frozen cross-state energies -> analysis.
/// @dev One supported unconstrained, fixed-box hybrid Hamiltonian is used for
///      both sampled forces and every cross-state energy. No EOA supplies a
///      force/energy/sample, and partial positions never become committed state.
///      Full molecular preparation, ensemble validation and campaign feasibility
///      remain scientific requirements; this contract cannot certify them.
contract MolecularSimulationPipeline {
    error Unauthorized(); error InvalidInput(); error WrongStage(); error DependencyChanged(); error NotConfigured();
    enum Stage { Missing, Loading, InitialEvaluation, InitialForces, Ready, Drift, StepEvaluation, StepForces, CrossStart, CrossEvaluation, Record, Complete, HandedOff, Copying, ConstrainedOps, Projection, ProjectionImport, ConstraintFailed }
    enum ConstraintPhase { Missing, InitialVelocity, Kick, DriftOne, DriftVelocityOne, Thermostat, DriftTwo, DriftVelocityTwo, FinalVelocity }
    struct ConstraintPolicy { bytes32 setId;bytes16 positionTolerance;bytes16 velocityTolerance;uint32 maxSweeps; }
    bytes32 public constant CONSTRAINED_METHOD = keccak256("ORVIA.gBAOAB.OneRattlePerHalfDrift.v1");
    enum AnalysisStage { Collecting, FlushRaw, Chronology, Selecting, Selected, Analyzing }
    struct Modules { address registry; address topology; address math; address integrator; address random; }
    struct Policy {
        bytes32 protocol; bytes32 topology; bytes32 leg; bytes32 seed; bytes32 stream;
        uint32 replica; bytes16 dt; bytes16 friction; bytes16 kT;
        uint64 equilibrationSteps; uint64 stride; uint32 samplesPerState;
        uint16 maxLag; uint32 minimumChronologySamples;
        bytes16 mbarTolerance; bytes16 overlapThreshold; bytes16 minimumESS; bytes16 normalizationTolerance;
        uint32 maxMbarIterations;
    }
    struct Campaign {
        Policy policy; bytes32 commitment; bytes32 topologyCommitment; uint8 states; uint8 completedWindows;
        AnalysisStage analysisStage; uint32 flushCursor; uint8 selectionState; uint32 selectionOrdinal;
        uint32 selectedExpected; uint32 selectedCount; uint256 analysisId;
        uint32[16] thinning; uint256[16] activeRuns; uint32[16] windowSamples;
        ConstraintPolicy constraints;bytes32 constraintSetCommitment;
    }
    struct Run {
        bytes32 campaign; uint8 state; Stage stage; uint32 cursor; uint64 step; uint256 parent;
        bytes32 commitment; bytes32 workingNamespace; bytes32 committedSnapshot; bytes32 sourceSnapshot;
        uint64 snapshotSerial; uint256 evaluation; uint256 sampledEvaluation; bytes32 sampledEvaluationCommitment; uint8 crossState; bytes16 energy;
        bytes16[16] sampleEnergies; bytes32 evaluationDigest; uint256[] evaluationHistory;
        ConstraintPhase constraintPhase;bytes32 projectionId;bytes32 projectionTrial;bytes32 substepSnapshot;
        bytes32 constraintTranscript;uint64 projectionSerial;
    }
    struct Sample {
        bytes32 snapshot; bytes32 snapshotCommitment; bytes32 runCommitment; bytes32 evaluationDigest;
        uint64 step; uint256 run; bytes16[16] energies;
        bytes32 constraintTranscript;
    }
    address public immutable owner;
    Modules public modules; bytes32[5] public moduleHashes; bytes32 public immutable coreConfigurationHash;
    IProductionWordState public statePage; AlchemicalHamiltonianEvaluator public hamiltonian;
    ReducedPotentialCollector public collector; TimeSeriesDiagnostics public chronology; MBARFreeEnergyEstimator public estimator;
    bytes32[5] public boundHashes;
    FullModelConstraintSolver public constraintSolver;FullModelConstraintCatalog public constraintCatalog;
    bytes32 public constraintSolverHash;bytes32 public constraintCatalogHash;
    uint256 public campaignCount;
    uint256 public nextRun = 1; uint256 public constant MAX_WORK = 8;
    mapping(bytes32 => Campaign) private campaigns;
    mapping(uint256 => Run) private runs;
    mapping(bytes32 => mapping(uint32 => Sample)) private samples;
    event CampaignCreated(bytes32 indexed id, bytes32 commitment);
    event WindowStarted(bytes32 indexed campaign,uint8 state,uint256 run,bytes32 commitment);
    event CheckpointCommitted(uint256 indexed run,uint64 step,bytes32 snapshot,bytes32 snapshotCommitment);
    event WindowContinued(uint256 indexed parent,uint256 indexed child,bytes32 checkpoint);
    event MolecularSampleRecorded(bytes32 indexed campaign,uint32 sample,uint8 state,uint64 step,bytes32 snapshot,bytes32 evaluationDigest);
    event ConstraintProblemStarted(uint256 indexed run,bytes32 indexed problem,ConstraintPhase phase);
    event ConstraintRunFailed(uint256 indexed run,bytes32 indexed problem,bytes4 reason);

    constructor(address owner_,Modules memory m) {
        if(owner_==address(0))revert InvalidInput();owner=owner_;modules=m;address[5] memory addresses=_addresses(m);
        for(uint256 i;i<5;++i){if(addresses[i].code.length==0)revert InvalidInput();moduleHashes[i]=addresses[i].codehash;}
        if(address(AlchemicalTopologyCatalog(m.topology).numericalMath())!=m.math
            ||address(LangevinBAOABKernel(m.integrator).numericalMath())!=m.math
            ||address(CounterRandom(m.random).numericalMath())!=m.math
            ||address(LangevinBAOABKernel(m.integrator).scalarMath())!=address(CounterRandom(m.random).scalarMath()))revert InvalidInput();
        coreConfigurationHash=keccak256(abi.encode(m,moduleHashes));
    }
    function bind(address page,address evaluator,address evaluatorOutput,address collector_,address chronology_,address estimator_)external{
        if(msg.sender!=owner)revert Unauthorized();if(address(statePage)!=address(0))revert WrongStage();
        address[5] memory addresses=[page,evaluator,collector_,chronology_,estimator_];for(uint256 i;i<5;++i)if(addresses[i].code.length==0)revert InvalidInput();
        if(IProductionWordState(page).writer()!=address(this)||AlchemicalHamiltonianEvaluator(evaluator).owner()!=address(this)
            ||ReducedPotentialCollector(collector_).writer()!=address(this)||TimeSeriesDiagnostics(chronology_).writer()!=address(this)
            ||address(ReducedPotentialCollector(collector_).numericalMath())!=modules.math
            ||address(TimeSeriesDiagnostics(chronology_).numericalMath())!=modules.math
            ||address(MBARFreeEnergyEstimator(estimator_).collector())!=collector_)revert InvalidInput();
        AlchemicalHamiltonianEvaluator.Modules memory hm=AlchemicalHamiltonianEvaluator(evaluator).moduleConfiguration();
        if(hm.topology!=modules.topology||hm.math!=modules.math)revert InvalidInput();
        AlchemicalHamiltonianEvaluator(evaluator).bindOutputPage(evaluatorOutput);
        statePage=IProductionWordState(page);hamiltonian=AlchemicalHamiltonianEvaluator(evaluator);
        collector=ReducedPotentialCollector(collector_);chronology=TimeSeriesDiagnostics(chronology_);estimator=MBARFreeEnergyEstimator(estimator_);
        for(uint256 i;i<5;++i)boundHashes[i]=addresses[i].codehash;
    }
    /// @notice Freeze the spatial acceleration identity before any campaign exists.
    function bindSpatial(address index,address pairs)external{
        if(msg.sender!=owner)revert Unauthorized();
        if(address(hamiltonian)==address(0))revert NotConfigured();
        if(campaignCount!=0)revert WrongStage();
        hamiltonian.bindSpatial(index,pairs);
    }
    function _spatialConfiguration()private view returns(bytes32){
        return keccak256(abi.encode(hamiltonian.SPATIAL_POLICY_ID(),address(hamiltonian.spatialIndex()),
            hamiltonian.spatialIndexCodeHash(),address(hamiltonian.spatialPairs()),hamiltonian.spatialPairsCodeHash()));
    }
    function bindConstraints(address solver)external{
        if(msg.sender!=owner)revert Unauthorized();
        if(address(constraintSolver)!=address(0)||solver.code.length==0)revert WrongStage();
        FullModelConstraintSolver s=FullModelConstraintSolver(solver);
        FullModelConstraintCatalog catalog=s.catalog();
        if(s.writer()!=address(this)||address(s.numericalMath())!=modules.math
            ||address(catalog.topology())!=modules.topology||catalog.owner()!=owner)revert InvalidInput();
        constraintSolver=s;constraintCatalog=catalog;constraintSolverHash=solver.codehash;
        constraintCatalogHash=address(catalog).codehash;
    }
    function createCampaign(bytes32 id,Policy calldata policy)external{
        ConstraintPolicy memory none;_createCampaign(id,policy,none);
    }
    function createConstrainedCampaign(bytes32 id,Policy calldata policy,ConstraintPolicy calldata constraints)external{
        if(constraints.setId==bytes32(0))revert InvalidInput();_createCampaign(id,policy,constraints);
    }
    function _createCampaign(bytes32 id,Policy calldata policy,ConstraintPolicy memory constraints)private{
        if(msg.sender!=owner)revert Unauthorized();bytes32 manifest=_dependencies(policy.protocol);
        if(id==bytes32(0)||campaigns[id].commitment!=bytes32(0)||policy.leg==bytes32(0)||policy.seed==bytes32(0)||policy.stream==bytes32(0)
            ||policy.replica>0x00ffffff||policy.samplesPerState<4||policy.minimumChronologySamples<4||policy.minimumChronologySamples>policy.samplesPerState
            ||policy.maxLag==0||policy.maxLag%2!=1||policy.maxLag>255||policy.maxLag>=policy.samplesPerState||policy.stride==0||policy.maxMbarIterations==0||policy.maxMbarIterations>10000)revert InvalidInput();
        _positive(policy.dt);_positive(policy.kT);_nonnegative(policy.friction);
        LangevinBAOABKernel(modules.integrator).coefficients(FloatMath(modules.math).fromUInt(1),policy.dt,policy.friction,policy.kT);
        uint8 states=AlchemicalTopologyCatalog(modules.topology).stateCount(policy.topology);
        if(uint256(states)*policy.samplesPerState>collector.MAX_SAMPLES()
            ||uint256(policy.equilibrationSteps)+uint256(policy.stride)*policy.samplesPerState>type(uint64).max)revert InvalidInput();
        Campaign storage c=campaigns[id];c.policy=policy;c.states=states;c.topologyCommitment=AlchemicalTopologyCatalog(modules.topology).assertTopology(policy.topology);
        c.commitment=keccak256(abi.encode(bytes32("ORVIA-MOLECULAR-CAMPAIGN-v1"),block.chainid,address(this),id,manifest,coreConfigurationHash,boundHashes,policy,c.topologyCommitment));
        c.commitment=keccak256(abi.encode(c.commitment,bytes32("ORVIA-SPATIAL-CONFIG-v1"),_spatialConfiguration()));
        if(constraints.setId!=bytes32(0)){
            _constraintDependencies(policy.protocol);
            _positive(constraints.positionTolerance);_positive(constraints.velocityTolerance);
            if(FloatMath(modules.math).compare(constraints.positionTolerance,FloatMath(modules.math).fromUInt(1))>=0
                ||constraints.maxSweeps==0||constraints.maxSweeps>constraintSolver.MAX_SWEEPS())revert InvalidInput();
            c.constraintSetCommitment=constraintCatalog.assertSet(constraints.setId);
            if(constraintCatalog.info(constraints.setId).topologyId!=policy.topology)revert InvalidInput();
            c.constraints=constraints;
            c.commitment=keccak256(abi.encode(c.commitment,CONSTRAINED_METHOD,constraints,c.constraintSetCommitment,
                address(constraintSolver),constraintSolverHash,address(constraintCatalog),constraintCatalogHash));
        }
        collector.createSeries(_rawSeries(id),_collectionPolicy(c,uint32(states)*policy.samplesPerState));
        ++campaignCount;
        emit CampaignCreated(id,c.commitment);
    }
    function startWindow(bytes32 campaign,uint8 state)external returns(uint256 id){
        // Only the owner chooses when sampling starts, so third parties cannot
        // invalidate repeat preregistration by front-running campaign setup.
        // Once started, every computational advance remains permissionless.
        if(msg.sender!=owner)revert Unauthorized();
        Campaign storage c=_campaign(campaign);_dependencies(c.policy.protocol);
        if(c.analysisStage!=AnalysisStage.Collecting||state>=c.states||c.activeRuns[state]!=0)revert InvalidInput();
        id=_newRun(campaign,state,0);c.activeRuns[state]=id;
        TimeSeriesDiagnostics.Configuration memory tc;
        tc.protocolHash=c.policy.protocol;tc.runHash=c.commitment;tc.replicaHash=keccak256(abi.encode(c.policy.seed,c.policy.stream,c.policy.replica,state));
        tc.observableHash=keccak256("ORVIA.Molecular.SampledPotentialEnergy.v1");tc.state=state;tc.expectedSamples=c.policy.samplesPerState;
        tc.firstStep=c.policy.equilibrationSteps+c.policy.stride;tc.stride=c.policy.stride;tc.maxLag=c.policy.maxLag;tc.minimumSamples=c.policy.minimumChronologySamples;
        chronology.createSeries(_chronologySeries(campaign,state),tc);
    }
    function continueWindow(uint256 parent)external returns(uint256 child){
        if(msg.sender!=owner)revert Unauthorized();Run storage previous=_run(parent);Campaign storage c=_campaign(previous.campaign);_dependencies(c.policy.protocol);
        if(previous.stage!=Stage.Ready||c.activeRuns[previous.state]!=parent)revert WrongStage();
        child=_newRun(previous.campaign,previous.state,parent);Run storage r=runs[child];
        r.step=previous.step;r.sourceSnapshot=previous.committedSnapshot;r.committedSnapshot=previous.committedSnapshot;r.energy=previous.energy;
        r.constraintTranscript=previous.constraintTranscript;
        r.stage=Stage.Copying;previous.stage=Stage.HandedOff;c.activeRuns[previous.state]=child;
        emit WindowContinued(parent,child,previous.committedSnapshot);
    }
    function advance(uint256 id,uint256 work)external returns(uint256 processed,bool complete){
        if(work==0||work>MAX_WORK)revert InvalidInput();Run storage r=_run(id);Campaign storage c=_campaign(r.campaign);_dependencies(c.policy.protocol);
        if(r.stage==Stage.Complete||r.stage==Stage.HandedOff||r.stage==Stage.ConstraintFailed||c.activeRuns[r.state]!=id)revert WrongStage();
        if(c.constraints.setId!=bytes32(0))_assertConstraints(c);
        AlchemicalTopologyCatalog.Definition memory d=AlchemicalTopologyCatalog(modules.topology).definition(c.policy.topology);
        while(processed<work&&r.stage!=Stage.Complete&&r.stage!=Stage.ConstraintFailed){
            if(r.stage==Stage.InitialEvaluation||r.stage==Stage.StepEvaluation||r.stage==Stage.CrossEvaluation){
                (uint256 used,bool finished)=hamiltonian.advance(r.evaluation,work-processed);processed+=used;
                if(finished)_evaluationFinished(r);
            }else if(r.stage==Stage.Projection){processed+=_advanceProjection(id,r,work-processed);}
            else{_one(id,r,c,d);++processed;}
        }
        complete=r.stage==Stage.Complete;
    }
    function _one(uint256 id,Run storage r,Campaign storage c,AlchemicalTopologyCatalog.Definition memory d)private{
        if(r.stage==Stage.Loading){
            bytes32[] memory words=new bytes32[](9);uint64 atom=r.cursor;
            for(uint64 k;k<3;++k){words[k]=AlchemicalTopologyCatalog(modules.topology).word(d.positions,atom*3+k);words[k+3]=AlchemicalTopologyCatalog(modules.topology).word(d.a.particles,atom*4+k+1);}
            statePage.writeWords(r.workingNamespace,uint256(atom)*9,words);
            if(++r.cursor==d.atoms){r.cursor=0;bytes32 snapshot=_snapshot(r,id,1);
                if(c.constraints.setId!=bytes32(0))_beginProjection(id,r,ConstraintPhase.InitialVelocity,snapshot,snapshot,false);
                else{_beginEvaluation(r,snapshot,r.state);r.stage=Stage.InitialEvaluation;}}
        }else if(r.stage==Stage.Copying){
            bytes32[] memory words=new bytes32[](9);for(uint256 k;k<9;++k)words[k]=statePage.readWord(r.sourceSnapshot,uint256(r.cursor)*9+k);
            statePage.writeWords(r.workingNamespace,uint256(r.cursor)*9,words);
            if(++r.cursor==d.atoms){statePage.writeWord(r.workingNamespace,uint256(d.atoms)*9,_encode(r.energy));r.cursor=0;r.committedSnapshot=_snapshot(r,id,4);r.stage=Stage.Ready;}
        }else if(r.stage==Stage.InitialForces||r.stage==Stage.StepForces){
            _importForce(r,c,d);
            if(++r.cursor==d.atoms){
                r.cursor=0;statePage.writeWord(r.workingNamespace,uint256(d.atoms)*9,_encode(r.energy));
                if(r.stage==Stage.StepForces&&c.constraints.setId!=bytes32(0)){
                    bytes32 snapshot=_snapshot(r,id,10);_beginProjection(id,r,ConstraintPhase.FinalVelocity,snapshot,snapshot,false);
                }else _commitForces(id,r,c,r.stage==Stage.StepForces);
            }
        }else if(r.stage==Stage.Ready){r.cursor=0;
            if(c.constraints.setId!=bytes32(0)){r.constraintPhase=ConstraintPhase.Kick;r.substepSnapshot=r.committedSnapshot;r.stage=Stage.ConstrainedOps;}
            else r.stage=Stage.Drift;
        }else if(r.stage==Stage.Drift){
            _drift(r,c,d);
            if(++r.cursor==d.atoms){r.cursor=0;bytes32 snapshot=_snapshot(r,id,3);_beginEvaluation(r,snapshot,r.state);r.stage=Stage.StepEvaluation;}
        }else if(r.stage==Stage.CrossStart){
            if(r.crossState==c.states)r.stage=Stage.Record;
            else if(r.crossState==r.state){r.sampleEnergies[r.crossState]=r.energy;r.evaluationDigest=keccak256(abi.encode(r.evaluationDigest,r.state,r.sampledEvaluation,r.sampledEvaluationCommitment));++r.crossState;}
            else{_beginEvaluation(r,r.committedSnapshot,r.crossState);r.stage=Stage.CrossEvaluation;}
        }else if(r.stage==Stage.Record){_record(id,r,c);
        }else if(r.stage==Stage.ConstrainedOps){_constrainedOperation(id,r,c,d);
        }else if(r.stage==Stage.ProjectionImport){_importProjection(id,r,c,d);
        }else revert WrongStage();
    }
    function _commitForces(uint256 id,Run storage r,Campaign storage c,bool step)private{
        if(step)++r.step;
        r.committedSnapshot=_snapshot(r,id,2);(,,,,bytes32 sc)=statePage.snapshotInfo(r.committedSnapshot);
        emit CheckpointCommitted(id,r.step,r.committedSnapshot,sc);
        if(r.step>c.policy.equilibrationSteps&&(r.step-c.policy.equilibrationSteps)%c.policy.stride==0){r.crossState=0;r.evaluationDigest=bytes32(0);r.stage=Stage.CrossStart;}
        else r.stage=Stage.Ready;
    }
    function _constrainedOperation(uint256 id,Run storage r,Campaign storage c,AlchemicalTopologyCatalog.Definition memory d)private{
        FloatMath m=FloatMath(modules.math);uint32 atom=r.cursor;ConstraintPhase phase=r.constraintPhase;
        bytes16[3] memory value;
        uint256 offset=3;
        if(phase==ConstraintPhase.Kick){
            value=LangevinBAOABKernel(modules.integrator).finish(_vector(r.substepSnapshot,atom,3),
                _vector(r.substepSnapshot,atom,6),_mass(d,atom),c.policy.dt);
        }else if(phase==ConstraintPhase.DriftOne||phase==ConstraintPhase.DriftTwo){
            value=_vector(r.substepSnapshot,atom,0);bytes16[3] memory velocity=_vector(r.substepSnapshot,atom,3);
            bytes16 h=m.mul(c.policy.dt,0x3ffe0000000000000000000000000000);_positive(h);
            for(uint256 k;k<3;++k)value[k]=m.add(value[k],m.mul(h,velocity[k]));offset=0;
        }else if(phase==ConstraintPhase.Thermostat){
            (bytes16 decay,bytes16 noise)=LangevinBAOABKernel(modules.integrator).coefficients(_mass(d,atom),c.policy.dt,c.policy.friction,c.policy.kT);
            value=_vector(r.substepSnapshot,atom,3);bytes16[3] memory normal=_normal(r,c,atom);
            for(uint256 k;k<3;++k)value[k]=m.add(m.mul(decay,value[k]),m.mul(noise,normal[k]));
        }else revert WrongStage();
        _writeVector(r.workingNamespace,uint256(atom)*9+offset,value);
        if(++r.cursor==d.atoms){
            r.cursor=0;bytes32 trial=_snapshot(r,id,11);
            bool position=phase==ConstraintPhase.DriftOne||phase==ConstraintPhase.DriftTwo;
            _beginProjection(id,r,phase,position?r.substepSnapshot:trial,trial,position);
        }
    }
    function _beginProjection(uint256 id,Run storage r,ConstraintPhase phase,bytes32 anchor,bytes32 trial,bool position)private{
        Campaign storage c=campaigns[r.campaign];ConstraintPolicy storage p=c.constraints;
        r.constraintPhase=phase;r.projectionTrial=trial;
        r.projectionId=keccak256(abi.encode(bytes32("ORVIA-MOLECULAR-PROJECTION-v1"),block.chainid,address(this),id,++r.projectionSerial,phase,r.step));
        bytes32 context=keccak256(abi.encode(CONSTRAINED_METHOD,c.commitment,r.commitment,r.step,phase,r.projectionSerial,c.policy.protocol));
        constraintSolver.registerProblem(r.projectionId,FullModelConstraintSolver.Params(p.setId,
            position?FullModelConstraintSolver.Mode.Position:FullModelConstraintSolver.Mode.Velocity,
            address(statePage),anchor,trial,context,p.positionTolerance,p.velocityTolerance,p.maxSweeps));
        r.cursor=0;r.stage=Stage.Projection;emit ConstraintProblemStarted(id,r.projectionId,phase);
    }
    function _advanceProjection(uint256 id,Run storage r,uint256 work)private returns(uint256 processed){
        FullModelConstraintSolver.Info memory info=constraintSolver.problemInfo(r.projectionId);
        if(info.status==FullModelConstraintSolver.Status.Correcting||info.status==FullModelConstraintSolver.Status.Checking){
            (processed,)=constraintSolver.advance(r.projectionId,work);
            info=constraintSolver.problemInfo(r.projectionId);
        }
        if(info.status==FullModelConstraintSolver.Status.Failed){
            r.stage=Stage.ConstraintFailed;emit ConstraintRunFailed(id,r.projectionId,info.failure);
        }else if(info.status==FullModelConstraintSolver.Status.Converged){
            bytes32 solution=constraintSolver.assertSolution(r.projectionId);
            r.constraintTranscript=keccak256(abi.encode(r.constraintTranscript,r.projectionId,solution));
            r.cursor=0;r.stage=Stage.ProjectionImport;
        }else if(info.status!=FullModelConstraintSolver.Status.Correcting&&info.status!=FullModelConstraintSolver.Status.Checking)revert WrongStage();
    }
    function _importProjection(uint256 id,Run storage r,Campaign storage c,AlchemicalTopologyCatalog.Definition memory d)private{
        uint32 atom=r.cursor;ConstraintPhase phase=r.constraintPhase;
        bytes16[3] memory value=constraintSolver.solutionAt(r.projectionId,atom);
        bool position=phase==ConstraintPhase.DriftOne||phase==ConstraintPhase.DriftTwo;
        if(position){
            FloatMath m=FloatMath(modules.math);bytes16[3] memory trial=_vector(r.projectionTrial,atom,0);
            bytes16[3] memory velocity=_vector(r.projectionTrial,atom,3);
            bytes16 h=m.mul(c.policy.dt,0x3ffe0000000000000000000000000000);_positive(h);
            for(uint256 k;k<3;++k)velocity[k]=m.add(velocity[k],m.div(m.sub(value[k],trial[k]),h));
            _writeVector(r.workingNamespace,uint256(atom)*9+3,velocity);
        }
        _writeVector(r.workingNamespace,uint256(atom)*9+(position?0:3),value);
        if(++r.cursor!=d.atoms)return;r.cursor=0;
        bytes32 snapshot=_snapshot(r,id,12);r.substepSnapshot=snapshot;
        if(phase==ConstraintPhase.InitialVelocity){_beginEvaluation(r,snapshot,r.state);r.stage=Stage.InitialEvaluation;}
        else if(phase==ConstraintPhase.Kick){r.constraintPhase=ConstraintPhase.DriftOne;r.stage=Stage.ConstrainedOps;}
        else if(position){_beginProjection(id,r,phase==ConstraintPhase.DriftOne?ConstraintPhase.DriftVelocityOne:ConstraintPhase.DriftVelocityTwo,snapshot,snapshot,false);}
        else if(phase==ConstraintPhase.DriftVelocityOne){r.constraintPhase=ConstraintPhase.Thermostat;r.stage=Stage.ConstrainedOps;}
        else if(phase==ConstraintPhase.Thermostat){r.constraintPhase=ConstraintPhase.DriftTwo;r.stage=Stage.ConstrainedOps;}
        else if(phase==ConstraintPhase.DriftVelocityTwo){_beginEvaluation(r,snapshot,r.state);r.stage=Stage.StepEvaluation;}
        else if(phase==ConstraintPhase.FinalVelocity){_commitForces(id,r,c,true);}
        else revert WrongStage();
    }
    function _mass(AlchemicalTopologyCatalog.Definition memory d,uint32 atom)private view returns(bytes16){
        return _decode(AlchemicalTopologyCatalog(modules.topology).word(d.a.particles,uint64(atom)*4));
    }
    function _normal(Run storage r,Campaign storage c,uint32 atom)private view returns(bytes16[3] memory normal){
        if(c.policy.friction!=bytes16(0)){
            uint64 draw=uint64(atom)*2;uint32 replica=(c.policy.replica<<8)|r.state;
            (normal[0],normal[1])=CounterRandom(modules.random).normalPair(c.policy.seed,c.policy.stream,replica,r.step,draw);
            (normal[2],)=CounterRandom(modules.random).normalPair(c.policy.seed,c.policy.stream,replica,r.step,draw+1);
        }
    }
    function _writeVector(bytes32 ns,uint256 offset,bytes16[3] memory value)private{
        bytes32[] memory words=new bytes32[](3);for(uint256 k;k<3;++k)words[k]=_encode(value[k]);statePage.writeWords(ns,offset,words);
    }
    function _constraintDependencies(bytes32 protocol)private view{
        if(address(constraintSolver)==address(0)||address(constraintSolver).codehash!=constraintSolverHash
            ||address(constraintCatalog).codehash!=constraintCatalogHash)revert DependencyChanged();
        ExperimentRegistry registry=ExperimentRegistry(modules.registry);
        registry.assertModule(protocol,address(constraintSolver),constraintSolverHash);
        registry.assertModule(protocol,address(constraintCatalog),constraintCatalogHash);
        address kernel=address(constraintSolver.kernel());registry.assertModule(protocol,kernel,kernel.codehash);
    }
    function _assertConstraints(Campaign storage c)private view{
        _constraintDependencies(c.policy.protocol);
        if(constraintCatalog.assertSet(c.constraints.setId)!=c.constraintSetCommitment)revert DependencyChanged();
    }
    function _newRun(bytes32 campaign,uint8 state,uint256 parent)private returns(uint256 id){
        Campaign storage c=campaigns[campaign];AlchemicalTopologyCatalog.Definition memory d=AlchemicalTopologyCatalog(modules.topology).definition(c.policy.topology);
        id=nextRun++;Run storage r=runs[id];r.campaign=campaign;r.state=state;r.parent=parent;r.stage=Stage.Loading;
        r.workingNamespace=keccak256(abi.encode(bytes32("ORVIA-MOLECULAR-WORK-v1"),block.chainid,address(this),id));
        bytes32 lineage=parent==0?bytes32(0):keccak256(abi.encode(runs[parent].commitment,runs[parent].committedSnapshot,runs[parent].step));
        r.commitment=keccak256(abi.encode(bytes32("ORVIA-MOLECULAR-RUN-v1"),block.chainid,address(this),id,c.commitment,state,parent,lineage,r.workingNamespace));
        statePage.createNamespace(r.workingNamespace,d.atoms*9+1);emit WindowStarted(campaign,state,id,r.commitment);
    }
    function _drift(Run storage r,Campaign storage c,AlchemicalTopologyCatalog.Definition memory d)private{
        bytes16[3] memory normal;
        if(c.policy.friction!=bytes16(0)){
            uint64 draw=uint64(r.cursor)*2;uint32 replica=(c.policy.replica<<8)|r.state;
            (normal[0],normal[1])=CounterRandom(modules.random).normalPair(c.policy.seed,c.policy.stream,replica,r.step,draw);
            (normal[2],)=CounterRandom(modules.random).normalPair(c.policy.seed,c.policy.stream,replica,r.step,draw+1);
        }
        bytes16 mass=_decode(AlchemicalTopologyCatalog(modules.topology).word(d.a.particles,uint64(r.cursor)*4));
        (bytes16[3] memory position,bytes16[3] memory velocity)=LangevinBAOABKernel(modules.integrator).begin(
            _vector(r.committedSnapshot,r.cursor,0),_vector(r.committedSnapshot,r.cursor,3),_vector(r.committedSnapshot,r.cursor,6),mass,c.policy.dt,c.policy.friction,c.policy.kT,normal);
        bytes32[] memory words=new bytes32[](9);for(uint256 k;k<3;++k){words[k]=_encode(position[k]);words[k+3]=_encode(velocity[k]);}
        statePage.writeWords(r.workingNamespace,uint256(r.cursor)*9,words);
    }
    function _importForce(Run storage r,Campaign storage c,AlchemicalTopologyCatalog.Definition memory d)private{
        bytes16[3] memory force=hamiltonian.forceAt(r.evaluation,r.cursor);bytes32[] memory words=new bytes32[](6);
        bytes16[3] memory velocity=_vector(r.workingNamespace,r.cursor,3);
        if(r.stage==Stage.StepForces)velocity=LangevinBAOABKernel(modules.integrator).finish(velocity,force,
            _decode(AlchemicalTopologyCatalog(modules.topology).word(d.a.particles,uint64(r.cursor)*4)),c.policy.dt);
        for(uint256 k;k<3;++k){words[k]=_encode(velocity[k]);words[k+3]=_encode(force[k]);}
        statePage.writeWords(r.workingNamespace,uint256(r.cursor)*9+3,words);
    }
    function _beginEvaluation(Run storage r,bytes32 snapshot,uint8 state)private{
        Policy storage p=campaigns[r.campaign].policy;
        r.evaluation=hamiltonian.registerEvaluation(p.protocol,p.topology,state,address(statePage),snapshot,0,9);
        r.evaluationHistory.push(r.evaluation);
    }
    function _evaluationFinished(Run storage r)private{
        (,bytes32 commitment,bytes16 energy)=hamiltonian.result(r.evaluation);
        if(r.stage==Stage.CrossEvaluation){r.sampleEnergies[r.crossState]=energy;r.evaluationDigest=keccak256(abi.encode(r.evaluationDigest,r.crossState,r.evaluation,commitment));++r.crossState;r.stage=Stage.CrossStart;}
        else{r.energy=energy;r.sampledEvaluation=r.evaluation;r.sampledEvaluationCommitment=commitment;r.cursor=0;r.stage=r.stage==Stage.InitialEvaluation?Stage.InitialForces:Stage.StepForces;}
    }
    function _record(uint256 id,Run storage r,Campaign storage c)private{
        uint32 ordinal=c.windowSamples[r.state];if(ordinal>=c.policy.samplesPerState||r.step!=c.policy.equilibrationSteps+uint64(ordinal+1)*c.policy.stride)revert InvalidInput();
        uint32 index=uint32(r.state)*c.policy.samplesPerState+ordinal;Sample storage sample=samples[r.campaign][index];
        if(sample.snapshot!=bytes32(0))revert WrongStage();(,,,,bytes32 sc)=statePage.snapshotInfo(r.committedSnapshot);
        sample.snapshot=r.committedSnapshot;sample.snapshotCommitment=sc;sample.runCommitment=r.commitment;sample.run=id;sample.step=r.step;sample.energies=r.sampleEnergies;
        sample.evaluationDigest=keccak256(abi.encode(r.evaluationDigest,r.state,r.energy,sc));
        if(c.constraints.setId!=bytes32(0)){
            sample.constraintTranscript=r.constraintTranscript;
            sample.evaluationDigest=keccak256(abi.encode(sample.evaluationDigest,CONSTRAINED_METHOD,r.constraintTranscript));
        }
        bytes16[] memory observable=new bytes16[](1);observable[0]=r.energy;chronology.append(_chronologySeries(r.campaign,r.state),r.step,observable);
        ++c.windowSamples[r.state];emit MolecularSampleRecorded(r.campaign,index,r.state,r.step,r.committedSnapshot,sample.evaluationDigest);
        if(c.windowSamples[r.state]==c.policy.samplesPerState){
            chronology.seal(_chronologySeries(r.campaign,r.state));r.stage=Stage.Complete;++c.completedWindows;
            if(c.completedWindows==c.states)c.analysisStage=AnalysisStage.FlushRaw;
        }else r.stage=Stage.Ready;
    }
    /// @notice Materialize a canonical state-major matrix, independent of window interleaving.
    function flushRaw(bytes32 id,uint256 work)external returns(uint256 processed,bool complete){
        Campaign storage c=_campaign(id);_dependencies(c.policy.protocol);if(c.analysisStage!=AnalysisStage.FlushRaw||work==0||work>MAX_WORK)revert WrongStage();
        uint32 count=uint32(c.states)*c.policy.samplesPerState;
        while(processed<work&&c.flushCursor<count){uint32 index=c.flushCursor;uint8 state=uint8(index/c.policy.samplesPerState);_append(id,_rawSeries(id),index,state);++c.flushCursor;++processed;}
        complete=c.flushCursor==count;if(complete){collector.seal(_rawSeries(id));c.analysisStage=AnalysisStage.Chronology;}
    }
    /// @notice Frozen rule: choose every ceil(g)th chronological sample per state.
    /// @dev Correlation estimates are finite-sample model diagnostics, not a proof
    ///      that every slow molecular observable has equilibrated or decorrelated.
    function beginSelection(bytes32 id)external{
        Campaign storage c=_campaign(id);_dependencies(c.policy.protocol);if(c.analysisStage!=AnalysisStage.Chronology)revert WrongStage();
        uint32 total;FloatMath m=FloatMath(modules.math);
        for(uint8 k;k<c.states;++k){
            ( ,bool valid)=chronology.assertCompleted(_chronologySeries(id,k));if(!valid)revert WrongStage();
            TimeSeriesDiagnostics.Summary memory s=chronology.summary(_chronologySeries(id,k));
            if(m.compare(s.effectiveSamples,c.policy.minimumESS)<0)revert WrongStage();
            uint32 thin=_ceil(s.g,c.policy.samplesPerState);uint32 retained=(c.policy.samplesPerState-1)/thin+1;
            if(m.compare(m.fromUInt(retained),c.policy.minimumESS)<0)revert WrongStage();c.thinning[k]=thin;total+=retained;
        }
        c.selectedExpected=total;collector.createSeries(_selectedSeries(id),_collectionPolicy(c,total));c.analysisStage=AnalysisStage.Selecting;
    }
    function advanceSelection(bytes32 id,uint256 work)external returns(uint256 processed,bool complete){
        Campaign storage c=_campaign(id);_dependencies(c.policy.protocol);if(c.analysisStage!=AnalysisStage.Selecting||work==0||work>MAX_WORK)revert WrongStage();
        while(processed<work&&c.selectionState<c.states){
            uint32 ordinal=c.selectionOrdinal*c.thinning[c.selectionState];
            _append(id,_selectedSeries(id),uint32(c.selectionState)*c.policy.samplesPerState+ordinal,c.selectionState);++c.selectedCount;++c.selectionOrdinal;++processed;
            if(uint256(c.selectionOrdinal)*c.thinning[c.selectionState]>=c.policy.samplesPerState){++c.selectionState;c.selectionOrdinal=0;}
        }
        complete=c.selectionState==c.states;if(complete){if(c.selectedCount!=c.selectedExpected)revert InvalidInput();collector.seal(_selectedSeries(id));c.analysisStage=AnalysisStage.Selected;}
    }
    function startAnalysis(bytes32 id)external returns(uint256 analysisId){
        Campaign storage c=_campaign(id);_dependencies(c.policy.protocol);if(c.analysisStage!=AnalysisStage.Selected)revert WrongStage();
        analysisId=estimator.createAnalysis(_selectedSeries(id),c.policy.mbarTolerance,c.policy.maxMbarIterations);c.analysisId=analysisId;c.analysisStage=AnalysisStage.Analyzing;
    }
    function _append(bytes32 id,bytes32 series,uint32 index,uint8 state)private{
        Campaign storage c=campaigns[id];Sample storage sample=samples[id][index];if(sample.snapshot==bytes32(0))revert WrongStage();
        (,,,,bytes32 sc)=statePage.snapshotInfo(sample.snapshot);if(sc!=sample.snapshotCommitment)revert DependencyChanged();
        bytes16[] memory energies=new bytes16[](c.states);for(uint256 k;k<c.states;++k)energies[k]=sample.energies[k];
        collector.appendSample(series,state,sample.step,energies);
    }
    function _collectionPolicy(Campaign storage c,uint32 expected)private view returns(ReducedPotentialCollector.Configuration memory p){
        p.protocolHash=c.policy.protocol;p.runHash=c.commitment;p.leg=c.policy.leg;p.repeatSeed=c.policy.seed;p.stateCount=c.states;p.expectedSamples=expected;p.kT=c.policy.kT;
        p.stride=c.policy.stride;p.equilibrationEnd=c.policy.equilibrationSteps;p.mbarTolerance=c.policy.mbarTolerance;p.overlapThreshold=c.policy.overlapThreshold;p.minimumESS=c.policy.minimumESS;p.normalizationTolerance=c.policy.normalizationTolerance;
    }
    function _snapshot(Run storage r,uint256 id,uint8 kind)private returns(bytes32 snapshot){
        snapshot=keccak256(abi.encode(bytes32("ORVIA-MOLECULAR-SNAPSHOT-v1"),block.chainid,address(this),id,++r.snapshotSerial,kind,r.step));statePage.snapshotNamespace(r.workingNamespace,snapshot);
    }
    function _vector(bytes32 ns,uint32 atom,uint32 offset)private view returns(bytes16[3] memory vector){for(uint256 k;k<3;++k)vector[k]=_decode(statePage.readWord(ns,uint256(atom)*9+offset+k));}
    function _ceil(bytes16 g,uint32 maximum)private view returns(uint32){FloatMath m=FloatMath(modules.math);if(m.compare(g,m.fromUInt(maximum))>0)revert InvalidInput();uint32 low=1;uint32 high=maximum;while(low<high){uint32 mid=low+(high-low)/2;if(m.compare(m.fromUInt(mid),g)<0)low=mid+1;else high=mid;}return low;}
    function campaignInfo(bytes32 id)external view returns(bytes32 commitment,AnalysisStage stage,uint8 states,uint8 completed,uint256 analysisId,uint32 selectedExpected){Campaign storage c=_campaign(id);return(c.commitment,c.analysisStage,c.states,c.completedWindows,c.analysisId,c.selectedExpected);}
    /// @notice Freeze repeat membership before any trajectory can be observed.
    /// @dev The future selected-series identifier is deterministic even though its
    ///      sample count is only known after the registered chronology rule runs.
    function campaignRegistration(bytes32 id)external view returns(IMolecularCampaignSource.Registration memory out){
        Campaign storage c=_campaign(id);_dependencies(c.policy.protocol);
        if(c.analysisStage!=AnalysisStage.Collecting)revert WrongStage();
        for(uint256 k;k<c.states;++k)if(c.activeRuns[k]!=0)revert WrongStage();
        out.commitment=c.commitment;out.selectedSeries=_selectedSeries(id);
        out.config=_collectionPolicy(c,uint32(c.states)*c.policy.samplesPerState);
        Policy storage p=c.policy;
        out.samplingPolicyHash=keccak256(abi.encode(p.dt,p.friction,p.kT,p.equilibrationSteps,p.stride,
            p.samplesPerState,p.maxLag,p.minimumChronologySamples,p.maxMbarIterations));
        out.modelHash=c.topologyCommitment;
        if(c.constraints.setId!=bytes32(0)){
            out.samplingPolicyHash=keccak256(abi.encode(out.samplingPolicyHash,CONSTRAINED_METHOD,
                c.constraints.positionTolerance,c.constraints.velocityTolerance,c.constraints.maxSweeps));
            out.modelHash=keccak256(abi.encode(out.modelHash,c.constraintSetCommitment));
        }
    }
    /// @notice Bind a selected analysis back to its original dynamics campaign.
    function campaignAnalysis(bytes32 id)external view returns(bytes32 commitment,bytes32 series,uint256 analysis){
        Campaign storage c=_campaign(id);_dependencies(c.policy.protocol);
        if(c.analysisStage!=AnalysisStage.Analyzing||c.analysisId==0)revert WrongStage();
        (bytes32 actual,,,)=estimator.assertConverged(c.analysisId);
        series=_selectedSeries(id);if(actual!=series)revert DependencyChanged();
        return(c.commitment,series,c.analysisId);
    }
    function runInfo(uint256 id)external view returns(bytes32 campaign,uint8 state,Stage stage,uint64 step,uint32 cursor,uint256 parent,bytes32 commitment,bytes32 checkpoint){Run storage r=_run(id);return(r.campaign,r.state,r.stage,r.step,r.cursor,r.parent,r.commitment,r.committedSnapshot);}
    function constraintRunInfo(uint256 id)external view returns(ConstraintPhase phase,bytes32 problem,bytes32 transcript){
        Run storage r=_run(id);return(r.constraintPhase,r.projectionId,r.constraintTranscript);
    }
    function stateAt(uint256 id,uint32 atom)external view returns(bytes16[3] memory position,bytes16[3] memory velocity,bytes16[3] memory force){Run storage r=_run(id);if(r.committedSnapshot==bytes32(0)||atom>=AlchemicalTopologyCatalog(modules.topology).definition(campaigns[r.campaign].policy.topology).atoms)revert WrongStage();return(_vector(r.committedSnapshot,atom,0),_vector(r.committedSnapshot,atom,3),_vector(r.committedSnapshot,atom,6));}
    function sampleInfo(bytes32 id,uint32 index)external view returns(bytes32 snapshot,bytes32 snapshotCommitment,bytes32 runCommitment,bytes32 evaluationDigest,uint64 step,uint256 run){Sample storage s=samples[id][index];if(s.snapshot==bytes32(0))revert InvalidInput();return(s.snapshot,s.snapshotCommitment,s.runCommitment,s.evaluationDigest,s.step,s.run);}
    function sampleEnergy(bytes32 id,uint32 sample,uint8 state)external view returns(bytes16){if(state>=_campaign(id).states||samples[id][sample].snapshot==bytes32(0))revert InvalidInput();return samples[id][sample].energies[state];}
    function sampleConstraintTranscript(bytes32 id,uint32 sample)external view returns(bytes32){
        if(samples[id][sample].snapshot==bytes32(0))revert InvalidInput();return samples[id][sample].constraintTranscript;
    }
    function evaluationHistory(uint256 id,uint256 index)external view returns(uint256){return _run(id).evaluationHistory[index];}
    function chronologySeries(bytes32 id,uint8 state)external pure returns(bytes32){return _chronologySeries(id,state);}
    function rawSeries(bytes32 id)external pure returns(bytes32){return _rawSeries(id);}
    function selectedSeries(bytes32 id)external pure returns(bytes32){return _selectedSeries(id);}
    function _rawSeries(bytes32 id)private pure returns(bytes32){return keccak256(abi.encode(bytes32("ORVIA-MOLECULAR-RAW-v1"),id));}
    function _selectedSeries(bytes32 id)private pure returns(bytes32){return keccak256(abi.encode(bytes32("ORVIA-MOLECULAR-SELECTED-v1"),id));}
    function _chronologySeries(bytes32 id,uint8 state)private pure returns(bytes32){return keccak256(abi.encode(bytes32("ORVIA-MOLECULAR-TIME-v1"),id,state));}
    function _dependencies(bytes32 protocol)private view returns(bytes32 manifest){
        if(address(statePage)==address(0))revert NotConfigured();ExperimentRegistry registry=ExperimentRegistry(modules.registry);manifest=registry.assertProtocol(protocol);address[5] memory a=_addresses(modules);
        for(uint256 i;i<5;++i){if(a[i].codehash!=moduleHashes[i])revert DependencyChanged();if(i!=0)registry.assertModule(protocol,a[i],moduleHashes[i]);}
        address[5] memory b=[address(statePage),address(hamiltonian),address(collector),address(chronology),address(estimator)];
        for(uint256 i;i<5;++i){if(b[i].codehash!=boundHashes[i])revert DependencyChanged();registry.assertModule(protocol,b[i],boundHashes[i]);}
        registry.assertModule(protocol,address(this),address(this).codehash);
    }
    function _addresses(Modules memory m)private pure returns(address[5] memory){return[m.registry,m.topology,m.math,m.integrator,m.random];}
    function _campaign(bytes32 id)private view returns(Campaign storage c){c=campaigns[id];if(c.commitment==bytes32(0))revert InvalidInput();if(c.constraints.setId!=bytes32(0))_assertConstraints(c);}
    function _run(uint256 id)private view returns(Run storage r){r=runs[id];if(r.stage==Stage.Missing)revert InvalidInput();}
    function _positive(bytes16 x)private view{if(!FloatMath(modules.math).isFinite(x)||FloatMath(modules.math).compare(x,bytes16(0))<=0)revert InvalidInput();}
    function _nonnegative(bytes16 x)private view{if(!FloatMath(modules.math).isFinite(x)||FloatMath(modules.math).compare(x,bytes16(0))<0)revert InvalidInput();}
    function _decode(bytes32 word)private pure returns(bytes16 value){if(uint256(word)>>128!=0)revert InvalidInput();value=bytes16(uint128(uint256(word)));if(((uint128(value)>>112)&0x7fff)==0x7fff)revert InvalidInput();}
    function _encode(bytes16 value)private pure returns(bytes32){if(((uint128(value)>>112)&0x7fff)==0x7fff)revert InvalidInput();return bytes32(uint256(uint128(value)));}
}

