// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {FloatMath} from "../math/FloatMath.sol";
import {ScalarMath} from "../math/ScalarMath.sol";

/// @notice One-atom BAOAB Langevin update with on-step velocities.
/// @dev The coordinator must supply complete old/new forces and deterministic
///      standard-normal draws. This primitive does not implement constraints.
contract LangevinBAOABKernel {
    error InvalidDependency();
    error InvalidParameter();
    error NonFiniteInput();

    FloatMath public immutable numericalMath;
    ScalarMath public immutable scalarMath;
    bytes32 public constant KERNEL_ID = keccak256("ORVIA.LangevinBAOABKernel.v0.5");
    bytes16 private constant ONE = 0x3fff0000000000000000000000000000;
    bytes16 private constant HALF = 0x3ffe0000000000000000000000000000;
    bytes16 private constant QUARTER = 0x3ffd0000000000000000000000000000;

    struct Update {
        bytes16[3] position;
        bytes16[3] velocity;
        bytes16[3] force;
        bytes16[3] normal;
        bytes16 mass;
        bytes16 dt;
        bytes16 friction;
        bytes16 kT;
    }
    struct Coefficients { bytes16 decay; bytes16 noise; bytes16 halfDt; bytes16 halfKick; }

    constructor(address math_, address scalar_) {
        if (math_.code.length == 0 || scalar_.code.length == 0) revert InvalidDependency();
        if (address(ScalarMath(scalar_).numericalMath()) != math_) revert InvalidDependency();
        numericalMath = FloatMath(math_);
        scalarMath = ScalarMath(scalar_);
    }

    /// @param kT Thermal energy in the same units as the potential (not Kelvin).
    function coefficients(bytes16 mass, bytes16 dt, bytes16 friction, bytes16 kT)
        public view returns (bytes16 decay, bytes16 noiseScale)
    {
        _positive(mass); _positive(dt); _positive(kT); _nonnegative(friction);
        FloatMath m = numericalMath;
        bytes16 z = m.mul(friction, dt);
        decay = scalarMath.exp(m.neg(z)); // Reverts if gamma*dt exceeds 256.
        bytes16 varianceFactor;
        if (m.compare(z, QUARTER) <= 0) {
            varianceFactor = m.neg(scalarMath.expm1(m.mul(m.fromInt(-2), z)));
        } else {
            varianceFactor = m.mul(m.sub(ONE, decay), m.add(ONE, decay));
        }
        noiseScale = m.sqrt(m.mul(m.div(kT, mass), varianceFactor));
    }

    /// @notice B half-kick, A half-drift, O thermostat, A half-drift.
    function begin(
        bytes16[3] calldata position, bytes16[3] calldata velocity, bytes16[3] calldata force,
        bytes16 mass, bytes16 dt, bytes16 friction, bytes16 kT, bytes16[3] calldata normal
    ) external view returns (bytes16[3] memory nextPosition, bytes16[3] memory thermalVelocity) {
        Update memory input;
        input.position = position; input.velocity = velocity; input.force = force; input.normal = normal;
        input.mass = mass; input.dt = dt; input.friction = friction; input.kT = kT;
        return _begin(input);
    }

    function _begin(Update memory input) private view
        returns (bytes16[3] memory nextPosition, bytes16[3] memory thermalVelocity)
    {
        Coefficients memory c;
        (c.decay, c.noise) = coefficients(input.mass, input.dt, input.friction, input.kT);
        FloatMath m = numericalMath;
        c.halfDt = m.mul(HALF, input.dt);
        c.halfKick = m.div(c.halfDt, input.mass);
        for (uint256 axis; axis < 3; ++axis) {
            _finite(input.position[axis]); _finite(input.velocity[axis]); _finite(input.force[axis]); _finite(input.normal[axis]);
            bytes16 halfVelocity = m.add(input.velocity[axis], m.mul(c.halfKick, input.force[axis]));
            thermalVelocity[axis] = m.add(m.mul(c.decay, halfVelocity), m.mul(c.noise, input.normal[axis]));
            nextPosition[axis] = m.add(input.position[axis], m.mul(c.halfDt, m.add(halfVelocity, thermalVelocity[axis])));
        }
    }

    /// @notice Final B half-kick after the complete next-position force pass.
    function finish(bytes16[3] calldata thermalVelocity, bytes16[3] calldata newForce, bytes16 mass, bytes16 dt)
        external view returns (bytes16[3] memory nextVelocity)
    {
        _positive(mass); _positive(dt);
        FloatMath m = numericalMath;
        bytes16 scale = m.div(m.mul(HALF, dt), mass);
        for (uint256 axis; axis < 3; ++axis) {
            _finite(thermalVelocity[axis]); _finite(newForce[axis]);
            nextVelocity[axis] = m.add(thermalVelocity[axis], m.mul(scale, newForce[axis]));
        }
    }

    function _finite(bytes16 value) private view {
        if (!numericalMath.isFinite(value)) revert NonFiniteInput();
    }
    function _positive(bytes16 value) private view {
        _finite(value);
        if (numericalMath.compare(value, bytes16(0)) <= 0) revert InvalidParameter();
    }
    function _nonnegative(bytes16 value) private view {
        _finite(value);
        if (numericalMath.compare(value, bytes16(0)) < 0) revert InvalidParameter();
    }
}

contracts/math/ScalarMath.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {FloatMath} from "./FloatMath.sol";
import {ABDKMathQuad} from "./vendor/ABDKMathQuad.sol";

/// @notice Bounded scalar functions for stochastic dynamics and electrostatics.
/// @dev Pinned binary128-format arithmetic; not a correctly-rounded IEEE claim.
contract ScalarMath {
    error InvalidMathContract();
    error NonFiniteInput();
    error OutsideDomain();

    FloatMath public immutable numericalMath;
    bytes32 public constant IMPLEMENTATION_ID = keccak256("ORVIA.ScalarMath.v0.5.ABDK-and-DLMF7.9.2");
    bytes16 public constant INV_SQRT_PI = 0x3ffe20dd750429b6d11ae3a914fed7fe;
    bytes16 public constant MAX_EXP_ARGUMENT = 0x40070000000000000000000000000000; // 256
    bytes16 public constant MAX_ERF_ARGUMENT = 0x40030000000000000000000000000000; // 16
    bytes16 private constant ONE = 0x3fff0000000000000000000000000000;
    bytes16 private constant TWO = 0x40000000000000000000000000000000;
    bytes16 private constant HALF = 0x3ffe0000000000000000000000000000;

    constructor(address math_) {
        if (math_.code.length == 0) revert InvalidMathContract();
        numericalMath = FloatMath(math_);
    }

    function ln(bytes16 x) public view returns (bytes16) {
        _finite(x);
        FloatMath m = numericalMath;
        if (m.compare(x, bytes16(0)) <= 0) revert OutsideDomain();
        // The upstream logarithm loses relative accuracy arbitrarily close to
        // one. Retain the exact small increment and evaluate its atanh series.
        if (m.compare(x, HALF) >= 0 && m.compare(x, m.add(ONE, HALF)) <= 0) {
            return _log1pSmall(m.sub(x, ONE));
        }
        return _result(ABDKMathQuad.ln(x));
    }

    function exp(bytes16 x) public view returns (bytes16) {
        _expDomain(x);
        return _result(ABDKMathQuad.exp(x));
    }

    /// @notice exp(x)-1 without losing a small nonzero x to subtraction.
    function expm1(bytes16 x) external view returns (bytes16) {
        _expDomain(x);
        FloatMath m = numericalMath;
        if (m.compare(m.abs(x), HALF) > 0) return m.sub(exp(x), ONE);
        bytes16 term = x;
        bytes16 sum = x;
        for (uint256 n = 2; n <= 64; ++n) {
            term = ABDKMathQuad.div(ABDKMathQuad.mul(term, x), ABDKMathQuad.fromUInt(n));
            sum = ABDKMathQuad.add(sum, term);
        }
        return _result(sum);
    }

    /// @notice ln(1+x), x>-1, retaining small positive and negative inputs.
    function log1p(bytes16 x) external view returns (bytes16) {
        _finite(x);
        FloatMath m = numericalMath;
        if (m.compare(x, m.neg(ONE)) <= 0) revert OutsideDomain();
        if (m.compare(m.abs(x), HALF) > 0) return ln(m.add(ONE, x));
        return _log1pSmall(x);
    }

    function _log1pSmall(bytes16 x) private view returns (bytes16) {
        bytes16 t = ABDKMathQuad.div(x, ABDKMathQuad.add(TWO, x));
        bytes16 t2 = ABDKMathQuad.mul(t, t);
        bytes16 term = t;
        bytes16 sum = t;
        for (uint256 n = 1; n < 64; ++n) {
            term = ABDKMathQuad.mul(term, t2);
            sum = ABDKMathQuad.add(sum, ABDKMathQuad.div(term, ABDKMathQuad.fromUInt(2 * n + 1)));
        }
        return _result(ABDKMathQuad.mul(TWO, sum));
    }

    function erf(bytes16 x) external view returns (bytes16) {
        _erfDomain(x);
        FloatMath m = numericalMath;
        bytes16 ax = m.abs(x);
        bytes16 value = m.compare(ax, TWO) <= 0 ? _erfSmall(ax) : m.sub(ONE, _erfcTail(ax));
        return m.isNegative(x) ? m.neg(value) : value;
    }

    function erfc(bytes16 x) external view returns (bytes16) {
        _erfDomain(x);
        FloatMath m = numericalMath;
        bytes16 ax = m.abs(x);
        bytes16 value = m.compare(ax, TWO) < 0 ? m.sub(ONE, _erfSmall(ax)) : _erfcTail(ax);
        return m.isNegative(x) ? m.sub(TWO, value) : value;
    }

    // erf(x)=(2/sqrt(pi))*exp(-x*x)*x*sum[(2*x*x)^n/(3*5*...*(2n+1))].
    // Positive series avoids alternating cancellation for 0<=x<=2.
    function _erfSmall(bytes16 x) private view returns (bytes16) {
        bytes16 z = ABDKMathQuad.mul(x, x);
        bytes16 twiceZ = ABDKMathQuad.mul(TWO, z);
        bytes16 term = x;
        bytes16 sum = x;
        for (uint256 n = 1; n < 64; ++n) {
            term = ABDKMathQuad.div(ABDKMathQuad.mul(term, twiceZ), ABDKMathQuad.fromUInt(2 * n + 1));
            sum = ABDKMathQuad.add(sum, term);
        }
        return ABDKMathQuad.mul(ABDKMathQuad.mul(ABDKMathQuad.mul(TWO, INV_SQRT_PI), exp(ABDKMathQuad.neg(z))), sum);
    }

    // DLMF 7.9.2, evaluated backward with 128 numerator levels.
    // Equivalent gamma continued fraction: b_n=x*x+1/2+2n, a_n=n(n-1/2).
    function _erfcTail(bytes16 x) private view returns (bytes16) {
        bytes16 z = ABDKMathQuad.mul(x, x);
        bytes16 base = ABDKMathQuad.add(z, HALF);
        bytes16 tail;
        for (uint256 n = 128; n > 0; --n) {
            bytes16 numerator = ABDKMathQuad.mul(ABDKMathQuad.fromUInt(n * (2 * n - 1)), HALF);
            bytes16 denominator = ABDKMathQuad.sub(ABDKMathQuad.add(base, ABDKMathQuad.fromUInt(2 * n)), tail);
            tail = ABDKMathQuad.div(numerator, denominator);
        }
        return ABDKMathQuad.div(ABDKMathQuad.mul(ABDKMathQuad.mul(x, exp(ABDKMathQuad.neg(z))), INV_SQRT_PI), ABDKMathQuad.sub(base, tail));
    }

    function _expDomain(bytes16 x) private view {
        _finite(x);
        if (numericalMath.compare(numericalMath.abs(x), MAX_EXP_ARGUMENT) > 0) revert OutsideDomain();
    }
    function _erfDomain(bytes16 x) private view {
        _finite(x);
        if (numericalMath.compare(numericalMath.abs(x), MAX_ERF_ARGUMENT) > 0) revert OutsideDomain();
    }
    function _finite(bytes16 x) private view {
        if (!numericalMath.isFinite(x)) revert NonFiniteInput();
    }
    function _result(bytes16 x) private view returns (bytes16) {
        _finite(x);
        return numericalMath.isZero(x) ? bytes16(0) : x;
    }
}

contracts/kernels/CounterRandom.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {FloatMath} from "../math/FloatMath.sol";
import {ScalarMath} from "../math/ScalarMath.sol";
import {ElementaryMath} from "../math/ElementaryMath.sol";

/// @notice Stateless, reproducible scientific random streams from registered counters.
/// @dev No block entropy, sender, address or mutable draw counter enters the stream.
contract CounterRandom {
    error InvalidDependency();

    FloatMath public immutable numericalMath;
    ScalarMath public immutable scalarMath;
    ElementaryMath public immutable elementaryMath;
    bytes32 public constant DOMAIN = keccak256("ORVIA.CounterRandom.v1");
    bytes32 public constant GENERATOR_ID = keccak256("ORVIA.CounterRandom.v0.5.Keccak112midpoint.BoxMuller");
    bytes16 private constant TWO_TO_MINUS_113 = 0x3f8e0000000000000000000000000000;

    constructor(address math_, address scalar_, address elementary_) {
        if (math_.code.length == 0 || scalar_.code.length == 0 || elementary_.code.length == 0) revert InvalidDependency();
        if (address(ScalarMath(scalar_).numericalMath()) != math_
            || address(ElementaryMath(elementary_).numericalMath()) != math_) revert InvalidDependency();
        numericalMath = FloatMath(math_);
        scalarMath = ScalarMath(scalar_);
        elementaryMath = ElementaryMath(elementary_);
    }

    function word(bytes32 seed, bytes32 experiment, uint32 replica, uint64 step, uint64 draw, uint8 lane)
        public pure returns (bytes32)
    {
        return keccak256(abi.encode(DOMAIN, seed, experiment, replica, step, draw, lane));
    }

    function uniform(bytes32 seed, bytes32 experiment, uint32 replica, uint64 step, uint64 draw)
        external view returns (bytes16)
    {
        return _uniform(word(seed, experiment, replica, step, draw, 0));
    }

    /// @notice Two standard-normal approximations from two independent hash lanes.
    function normalPair(bytes32 seed, bytes32 experiment, uint32 replica, uint64 step, uint64 draw)
        external view returns (bytes16 first, bytes16 second)
    {
        FloatMath m = numericalMath;
        bytes16 u = _uniform(word(seed, experiment, replica, step, draw, 0));
        bytes16 v = _uniform(word(seed, experiment, replica, step, draw, 1));
        bytes16 radius = m.sqrt(m.mul(m.fromInt(-2), scalarMath.ln(u)));
        (bytes16 sine, bytes16 cosine) = elementaryMath.sinCos(m.mul(elementaryMath.TWO_PI(), v));
        first = m.mul(radius, cosine);
        second = m.mul(radius, sine);
    }

    function _uniform(bytes32 bits) private view returns (bytes16) {
        // Odd integer/2^113 is exactly representable, and always strictly in (0,1).
        uint256 midpointNumerator = 2 * (uint256(bits) >> 144) + 1;
        return numericalMath.mul(numericalMath.fromUInt(midpointNumerator), TWO_TO_MINUS_113);
    }
}

contracts/analysis/ReducedPotentialColle.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {FloatMath} from "../math/FloatMath.sol";

/// @notice Immutable-writer collection of complete cross-state energy samples.
/// @dev A trusted simulation writer must supply computed energies. The collector
///      converts them on-chain; it does not certify equilibrium or independence.
contract ReducedPotentialCollector {
    error Unauthorized(); error InvalidInput(); error UnknownSeries(); error Frozen();
    error DependencyChanged();
    address public immutable writer;
    bytes32 public immutable writerCodeHash;
    FloatMath public immutable numericalMath;
    bytes32 public immutable mathCodeHash;
    uint256 public constant MAX_STATES = 16;
    uint256 public constant MAX_SAMPLES = 4096;
    bytes16 private constant MAX_DIFFERENCE = 0x40040000000000000000000000000000; // 32

    struct Configuration {
        bytes32 protocolHash; bytes32 runHash; bytes32 leg; bytes32 repeatSeed;
        uint8 stateCount; uint32 expectedSamples; bytes16 kT;
        uint64 stride; uint64 equilibrationEnd;
        bytes16 mbarTolerance; bytes16 overlapThreshold; bytes16 minimumESS; bytes16 normalizationTolerance;
    }
    struct Series {
        Configuration config; bytes32 digest; uint32 count; bool isSealed;
        uint32[16] stateCounts; uint64[16] lastStep;
        bytes16[] reduced; bytes16[] referenceEnergy; uint8[] sampledStates; uint64[] steps;
    }
    mapping(bytes32 => Series) private _series;
    event SeriesCreated(bytes32 indexed id, bytes32 digest);
    event SampleRecorded(bytes32 indexed id, uint32 sample, uint8 state, uint64 step, bytes32 digest);
    event SeriesSealed(bytes32 indexed id, bytes32 digest);

    constructor(address writer_, address math_) {
        if (writer_.code.length == 0 || math_.code.length == 0) revert InvalidInput();
        writer = writer_; writerCodeHash = writer_.codehash;
        numericalMath = FloatMath(math_); mathCodeHash = math_.codehash;
    }
    function createSeries(bytes32 id, Configuration calldata config) external {
        _writer();
        if (id == bytes32(0) || _series[id].config.stateCount != 0 || config.protocolHash == bytes32(0)
            || config.runHash == bytes32(0) || config.leg == bytes32(0) || config.repeatSeed == bytes32(0)
            || config.stateCount < 2 || config.stateCount > MAX_STATES || config.expectedSamples < config.stateCount
            || config.expectedSamples > MAX_SAMPLES || config.stride == 0
            || !numericalMath.isFinite(config.kT) || numericalMath.compare(config.kT, bytes16(0)) <= 0) revert InvalidInput();
        _validatePolicy(config);
        Series storage s = _series[id]; s.config = config;
        s.digest = keccak256(abi.encode(bytes32("ORVIA-REDUCED-SERIES-v1"),block.chainid,address(this),id,
            writer,writerCodeHash,address(numericalMath),mathCodeHash,config));
        emit SeriesCreated(id,s.digest);
    }
    function _validatePolicy(Configuration calldata c) private view {
        FloatMath m=numericalMath;bytes16 one=m.fromUInt(1);
        if(!m.isFinite(c.mbarTolerance)||!m.isFinite(c.overlapThreshold)||!m.isFinite(c.minimumESS)||!m.isFinite(c.normalizationTolerance)
            ||m.compare(c.mbarTolerance,bytes16(0))<=0||m.compare(c.mbarTolerance,one)>=0
            ||m.compare(c.overlapThreshold,bytes16(0))<=0||m.compare(c.overlapThreshold,one)>=0
            ||m.compare(c.normalizationTolerance,bytes16(0))<=0||m.compare(c.normalizationTolerance,one)>=0
            ||m.compare(c.minimumESS,one)<0||m.compare(c.minimumESS,m.fromUInt(c.expectedSamples))>0)revert InvalidInput();
    }
    function appendSample(bytes32 id, uint8 sampledState, uint64 step, bytes16[] calldata energies) external {
        _writer(); Series storage s = _get(id);
        if (s.isSealed) revert Frozen();
        if (s.count >= s.config.expectedSamples || sampledState >= s.config.stateCount || energies.length != s.config.stateCount
            || step <= s.config.equilibrationEnd || (s.stateCounts[sampledState] != 0
                && (step <= s.lastStep[sampledState] || step - s.lastStep[sampledState] < s.config.stride))) revert InvalidInput();
        FloatMath m = numericalMath;
        if (!m.isFinite(energies[0])) revert InvalidInput();
        for (uint256 k; k < energies.length; ++k) {
            if (!m.isFinite(energies[k])) revert InvalidInput();
            bytes16 reduced = m.div(m.sub(energies[k],energies[0]),s.config.kT);
            if (m.compare(m.abs(reduced),MAX_DIFFERENCE) > 0) revert InvalidInput();
            s.reduced.push(reduced);
        }
        s.referenceEnergy.push(energies[0]); s.sampledStates.push(sampledState); s.steps.push(step);
        s.lastStep[sampledState] = step; ++s.stateCounts[sampledState];
        s.digest = keccak256(abi.encode(s.digest,s.count,sampledState,step,energies));
        emit SampleRecorded(id,s.count,sampledState,step,s.digest); ++s.count;
    }
    function seal(bytes32 id) external {
        _writer(); Series storage s = _get(id);
        if (s.isSealed) revert Frozen();
        if (s.count != s.config.expectedSamples) revert InvalidInput();
        for (uint256 k; k < s.config.stateCount; ++k) if (s.stateCounts[k] == 0) revert InvalidInput();
        s.isSealed = true; emit SeriesSealed(id,s.digest);
    }
    function seriesInfo(bytes32 id) external view returns (Configuration memory config, bytes32 digest, uint32 count, bool isSealed) {
        Series storage s = _get(id); return (s.config,s.digest,s.count,s.isSealed);
    }
    function stateCount(bytes32 id, uint256 k) external view returns (uint32) {
        Series storage s = _get(id); if (k >= s.config.stateCount) revert InvalidInput(); return s.stateCounts[k];
    }
    function potential(bytes32 id,uint256 n,uint256 k) external view returns (bytes16) {
        Series storage s = _get(id); if (n >= s.count || k >= s.config.stateCount) revert InvalidInput();
        return s.reduced[n*s.config.stateCount+k];
    }
    function sampleInfo(bytes32 id,uint256 n) external view returns (uint8 sampledState,uint64 step,bytes16 referenceEnergy) {
        Series storage s = _get(id); if (n >= s.count) revert InvalidInput();
        return (s.sampledStates[n],s.steps[n],s.referenceEnergy[n]);
    }
    function assertSealed(bytes32 id) external view returns (bytes32) {
        _dependencies(); Series storage s = _get(id); if (!s.isSealed) revert InvalidInput(); return s.digest;
    }
    function _writer() private view { if (msg.sender != writer) revert Unauthorized(); _dependencies(); }
    function _dependencies() private view {
        if (writer.codehash != writerCodeHash || address(numericalMath).codehash != mathCodeHash) revert DependencyChanged();
    }
    function _get(bytes32 id) private view returns (Series storage s) {
        s = _series[id]; if (s.config.stateCount == 0) revert UnknownSeries();
    }
}

contracts/analysis/TimeSeriesDiagnostics.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;
import {FloatMath} from "../math/FloatMath.sol";

/// @notice Bounded single-series initial-positive/monotone autocorrelation analysis.
/// @dev The stationary reversible-chain interpretation is a model assumption;
///      these diagnostics cannot establish stationarity or validate all observables.
contract TimeSeriesDiagnostics {
    error Unauthorized();error InvalidInput();error UnknownSeries();error InvalidStage();error DependencyChanged();
    enum Status { Missing, Collecting, Mean, Covariance, Sequence, Completed }
    struct Configuration {
        bytes32 protocolHash;bytes32 runHash;bytes32 replicaHash;bytes32 observableHash;
        uint32 state;uint32 expectedSamples;uint64 firstStep;uint64 stride;uint16 maxLag;uint32 minimumSamples;
    }
    struct Series {
        Configuration config;bytes32 digest;bytes32 resultDigest;Status status;
        uint32 count;uint32 cursor;uint16 lag;uint16 pair;uint16 usedLag;
        bytes16 mean;bytes16 m2;bytes16 covarianceSum;bytes16 pairSum;bytes16 previousPair;bytes16 g;bytes16 effectiveSamples;
        bool constantSeries;bool shortSeries;bool truncated;bool hasVariation;
        bytes16[] values;mapping(uint256=>bytes16) covariance;
    }
    struct Summary {
        bytes32 inputDigest;bytes32 resultDigest;Status status;uint32 samples;uint32 cursor;uint16 lag;uint16 usedLag;
        bytes16 mean;bytes16 populationVariance;bytes16 sampleVariance;bytes16 g;bytes16 effectiveSamples;
        bool constantSeries;bool shortSeries;bool truncated;bool validEstimate;
    }
    address public immutable writer;FloatMath public immutable numericalMath;
    bytes32 public immutable writerCodeHash;bytes32 public immutable mathCodeHash;
    uint256 public constant MAX_SAMPLES=4096;uint256 public constant MAX_LAG=255;
    uint256 public constant MAX_APPEND=64;uint256 public constant MAX_WORK=32;
    bytes16 private constant ONE=0x3fff0000000000000000000000000000;
    bytes16 private constant TWO=0x40000000000000000000000000000000;
    mapping(bytes32=>Series)private _series;
    event SeriesRegistered(bytes32 indexed id,bytes32 digest);
    event SeriesSealed(bytes32 indexed id,bytes32 digest);
    event DiagnosticsCompleted(bytes32 indexed id,bytes32 resultDigest,bool validEstimate);
    constructor(address writer_,address math_){
        if(writer_.code.length==0||math_.code.length==0)revert InvalidInput();
        writer=writer_;numericalMath=FloatMath(math_);writerCodeHash=writer_.codehash;mathCodeHash=math_.codehash;
    }
    function createSeries(bytes32 id,Configuration calldata c)external{
        _writer();
        if(id==bytes32(0)||_series[id].status!=Status.Missing||c.protocolHash==bytes32(0)||c.runHash==bytes32(0)
            ||c.replicaHash==bytes32(0)||c.observableHash==bytes32(0)||c.expectedSamples==0||c.expectedSamples>MAX_SAMPLES
            ||c.stride==0||c.minimumSamples<4||c.minimumSamples>MAX_SAMPLES||c.maxLag>MAX_LAG
            ||(c.expectedSamples==1?c.maxLag!=0:(c.maxLag==0||c.maxLag%2!=1||c.maxLag>=c.expectedSamples))
            ||uint256(c.firstStep)+uint256(c.expectedSamples-1)*c.stride>type(uint64).max)revert InvalidInput();
        Series storage s=_series[id];s.config=c;s.status=Status.Collecting;
        s.shortSeries=c.expectedSamples<c.minimumSamples;
        s.digest=keccak256(abi.encode(bytes32("ORVIA-TIMESERIES-v1"),block.chainid,address(this),id,
            writer,writerCodeHash,address(numericalMath),mathCodeHash,c));
        emit SeriesRegistered(id,s.digest);
    }
    function append(bytes32 id,uint64 firstStep,bytes16[] calldata values)external{
        _writer();Series storage s=_get(id);if(s.status!=Status.Collecting)revert InvalidStage();
        if(values.length==0||values.length>MAX_APPEND||uint256(s.count)+values.length>s.config.expectedSamples
            ||uint256(firstStep)!=uint256(s.config.firstStep)+uint256(s.count)*s.config.stride)revert InvalidInput();
        for(uint256 i;i<values.length;++i){
            if(!numericalMath.isFinite(values[i]))revert InvalidInput();
            bytes16 value=numericalMath.add(values[i],bytes16(0));
            if(s.count!=0&&numericalMath.compare(value,s.values[0])!=0)s.hasVariation=true;
            s.values.push(value);
            s.digest=keccak256(abi.encode(s.digest,s.count,uint256(firstStep)+i*s.config.stride,value));++s.count;
        }
    }
    function seal(bytes32 id)external{
        _writer();Series storage s=_get(id);if(s.status!=Status.Collecting)revert InvalidStage();
        if(s.count!=s.config.expectedSamples)revert InvalidInput();s.status=Status.Mean;emit SeriesSealed(id,s.digest);
    }
    function advance(bytes32 id,uint256 workLimit)external returns(uint256 processed,bool completed){
        _dependencies();if(workLimit==0||workLimit>MAX_WORK)revert InvalidInput();Series storage s=_get(id);
        if(s.status<Status.Mean||s.status==Status.Completed)revert InvalidStage();
        while(processed<workLimit&&s.status!=Status.Completed){
            if(s.status==Status.Mean)_mean(s,id);else if(s.status==Status.Covariance)_covariance(s);else _sequence(s,id);++processed;
        }completed=s.status==Status.Completed;
    }
    function _mean(Series storage s,bytes32 id)private{
        FloatMath m=numericalMath;bytes16 x=s.values[s.cursor];bytes16 delta=m.sub(x,s.mean);++s.cursor;
        bytes16 increment=m.div(delta,m.fromUInt(s.cursor));s.mean=m.add(s.mean,increment);
        s.m2=m.add(s.m2,m.mul(delta,m.sub(x,s.mean)));
        if(s.cursor==s.count){
            if(m.compare(s.m2,bytes16(0))<0)revert InvalidInput();
            s.covariance[0]=m.div(s.m2,m.fromUInt(s.count));s.cursor=0;
            if(m.isZero(s.covariance[0])){if(s.hasVariation)revert InvalidInput();s.constantSeries=true;_complete(s,id);}
            else{s.lag=1;s.status=Status.Covariance;}
        }
    }
    function _covariance(Series storage s)private{
        FloatMath m=numericalMath;
        bytes16 a=m.sub(s.values[s.cursor],s.mean);bytes16 b=m.sub(s.values[s.cursor+s.lag],s.mean);
        s.covarianceSum=m.add(s.covarianceSum,m.mul(a,b));++s.cursor;
        if(s.cursor==s.count-s.lag){
            s.covariance[s.lag]=m.div(s.covarianceSum,m.fromUInt(s.count));s.cursor=0;s.covarianceSum=bytes16(0);
            if(s.lag==s.config.maxLag)s.status=Status.Sequence;else ++s.lag;
        }
    }
    function _sequence(Series storage s,bytes32 id)private{
        FloatMath m=numericalMath;uint256 lag=uint256(s.pair)*2;
        bytes16 pair=m.add(s.covariance[lag],s.covariance[lag+1]);
        if(m.compare(pair,bytes16(0))<=0){_complete(s,id);return;}
        if(s.pair!=0&&m.compare(pair,s.previousPair)>0)pair=s.previousPair;
        s.previousPair=pair;s.pairSum=m.add(s.pairSum,pair);s.usedLag=uint16(lag+1);++s.pair;
        if(s.usedLag==s.config.maxLag){s.truncated=true;_complete(s,id);}
    }
    function _complete(Series storage s,bytes32 id)private{
        if(!s.constantSeries){
            FloatMath m=numericalMath;bytes16 ratio=m.div(s.pairSum,s.covariance[0]);
            s.g=m.sub(m.mul(TWO,ratio),ONE);if(m.compare(s.g,ONE)<0)s.g=ONE;
            s.effectiveSamples=m.div(m.fromUInt(s.count),s.g);
        }
        s.status=Status.Completed;
        s.resultDigest=keccak256(abi.encode(s.digest,s.mean,s.covariance[0],s.g,s.effectiveSamples,s.usedLag,s.constantSeries,s.shortSeries,s.truncated));
        emit DiagnosticsCompleted(id,s.resultDigest,!s.constantSeries&&!s.shortSeries&&!s.truncated);
    }
    function configuration(bytes32 id)external view returns(Configuration memory){return _get(id).config;}
    function valueAt(bytes32 id,uint256 index)external view returns(bytes16){Series storage s=_get(id);if(index>=s.count)revert InvalidInput();return s.values[index];}
    function covarianceAt(bytes32 id,uint256 lag)external view returns(bytes16){Series storage s=_get(id);if(s.status!=Status.Completed||lag>s.config.maxLag)revert InvalidInput();if(s.constantSeries)return bytes16(0);return s.covariance[lag];}
    function summary(bytes32 id)external view returns(Summary memory out){
        Series storage s=_get(id);out.inputDigest=s.digest;out.resultDigest=s.resultDigest;out.status=s.status;out.samples=s.count;out.cursor=s.cursor;
        out.lag=s.lag;out.usedLag=s.usedLag;out.mean=s.mean;out.populationVariance=s.covariance[0];
        if(s.count>1&&s.status==Status.Completed)out.sampleVariance=numericalMath.div(s.m2,numericalMath.fromUInt(s.count-1));
        out.g=s.g;out.effectiveSamples=s.effectiveSamples;out.constantSeries=s.constantSeries;out.shortSeries=s.shortSeries;out.truncated=s.truncated;
        out.validEstimate=s.status==Status.Completed&&!s.constantSeries&&!s.shortSeries&&!s.truncated;
    }
    function assertCompleted(bytes32 id)external view returns(bytes32 digest,bool validEstimate){
        _dependencies();Series storage s=_get(id);if(s.status!=Status.Completed)revert InvalidStage();return(s.resultDigest,!s.constantSeries&&!s.shortSeries&&!s.truncated);
    }
    function _writer()private view{if(msg.sender!=writer)revert Unauthorized();_dependencies();}
    function _dependencies()private view{if(writer.codehash!=writerCodeHash||address(numericalMath).codehash!=mathCodeHash)revert DependencyChanged();}
    function _get(bytes32 id)private view returns(Series storage s){s=_series[id];if(s.status==Status.Missing)revert UnknownSeries();}
}

contracts/analysis/MBARFreeEnergyEstimat.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;
import {FloatMath} from "../math/FloatMath.sol";
import {ReducedPotentialCollector} from "./ReducedPotentialCollector.sol";

interface IMBARScalarMath {
    function numericalMath() external view returns (address);
    function ln(bytes16) external view returns (bytes16);
    function exp(bytes16) external view returns (bytes16);
}

/// @notice General sampled-state MBAR fixed-point equations, resumable by cell.
/// @dev Convergence alone is not an overlap, equilibration or uncertainty claim.
contract MBARFreeEnergyEstimator {
    error InvalidInput(); error UnknownAnalysis(); error Terminal(); error DependencyChanged();
    enum Status { Missing, Denominators, Update, Normalize, FinalDenominators, Converged, MaxIterations }
    ReducedPotentialCollector public immutable collector;
    FloatMath public immutable numericalMath;
    IMBARScalarMath public immutable scalarMath;
    bytes32[3] public dependencyHashes;
    bytes32 public immutable configurationHash;
    uint256 public constant MAX_WORK = 32;
    bytes16 private constant ONE = 0x3fff0000000000000000000000000000;
    bytes16 private constant MAX_FREE_ENERGY = 0x40050000000000000000000000000000; // 64
    struct Analysis {
        bytes32 seriesId; bytes32 sampleDigest; bytes32 commitment;
        uint32 samples; uint8 states; uint32 iterations; uint32 maxIterations;
        uint32 n; uint8 k; Status status; bytes16 tolerance; bytes16 accumulator; bytes16 residual;
        bytes16[16] f; bytes16[16] next; bytes16[16] logCounts;
        mapping(uint256 => bytes16) logDenominator;
    }
    mapping(uint256=>Analysis) private _analyses;
    uint256 public nextAnalysisId=1;
    event AnalysisCreated(uint256 indexed id,bytes32 indexed seriesId,bytes32 commitment);
    event IterationCompleted(uint256 indexed id,uint32 iteration,bytes16 residual,Status status);
    constructor(address collector_,address math_,address scalar_) {
        if (collector_.code.length==0 || math_.code.length==0 || scalar_.code.length==0
            || address(ReducedPotentialCollector(collector_).numericalMath())!=math_
            || IMBARScalarMath(scalar_).numericalMath()!=math_) revert InvalidInput();
        collector=ReducedPotentialCollector(collector_); numericalMath=FloatMath(math_); scalarMath=IMBARScalarMath(scalar_);
        dependencyHashes=[collector_.codehash,math_.codehash,scalar_.codehash];
        configurationHash=keccak256(abi.encode(collector_,math_,scalar_,dependencyHashes));
    }
    function createAnalysis(bytes32 seriesId,bytes16 tolerance,uint32 maxIterations) external returns(uint256 id) {
        _dependencies();
        if (!numericalMath.isFinite(tolerance) || numericalMath.compare(tolerance,bytes16(0))<=0
            || numericalMath.compare(tolerance,ONE)>=0 || maxIterations==0 || maxIterations>10000) revert InvalidInput();
        bytes32 digest=collector.assertSealed(seriesId);
        (ReducedPotentialCollector.Configuration memory config,,uint32 count,)=collector.seriesInfo(seriesId);
        if(tolerance!=config.mbarTolerance)revert InvalidInput();
        id=nextAnalysisId++; Analysis storage a=_analyses[id];
        a.seriesId=seriesId;a.sampleDigest=digest;a.samples=count;a.states=config.stateCount;
        a.maxIterations=maxIterations;a.tolerance=tolerance;a.status=Status.Denominators;
        a.commitment=keccak256(abi.encode(bytes32("ORVIA-MBAR-v1"),block.chainid,address(this),id,
            seriesId,digest,configurationHash,tolerance,maxIterations));
        for(uint256 k;k<a.states;++k) a.logCounts[k]=scalarMath.ln(numericalMath.fromUInt(collector.stateCount(seriesId,k)));
        emit AnalysisCreated(id,seriesId,a.commitment);
    }
    function advanceAnalysis(uint256 id,uint256 workLimit) external returns(uint256 processed,bool terminal) {
        if(workLimit==0 || workLimit>MAX_WORK) revert InvalidInput();
        _dependencies(); Analysis storage a=_get(id);
        if(a.status>=Status.Converged) revert Terminal();
        if(collector.assertSealed(a.seriesId)!=a.sampleDigest) revert DependencyChanged();
        while(processed<workLimit && a.status<Status.Converged) {
            if(a.status==Status.Denominators || a.status==Status.FinalDenominators) _denominator(a);
            else if(a.status==Status.Update) _update(a);
            else _normalize(a,id);
            ++processed;
        }
        terminal=a.status>=Status.Converged;
    }
    function _denominator(Analysis storage a) private {
        FloatMath m=numericalMath;
        bytes16 term=m.sub(m.add(a.logCounts[a.k],a.f[a.k]),collector.potential(a.seriesId,a.n,a.k));
        a.accumulator=a.k==0?term:_logAdd(a.accumulator,term);
        ++a.k;
        if(a.k==a.states) {
            a.logDenominator[a.n]=a.accumulator;a.k=0;++a.n;
            if(a.n==a.samples) {a.n=0;a.status=a.status==Status.FinalDenominators?Status.Converged:Status.Update;}
        }
    }
    function _update(Analysis storage a) private {
        bytes16 term=numericalMath.neg(numericalMath.add(collector.potential(a.seriesId,a.n,a.k),a.logDenominator[a.n]));
        a.accumulator=a.n==0?term:_logAdd(a.accumulator,term);
        ++a.n;
        if(a.n==a.samples) {
            a.next[a.k]=numericalMath.neg(a.accumulator);a.n=0;++a.k;
            if(a.k==a.states){a.k=0;a.residual=bytes16(0);a.status=Status.Normalize;}
        }
    }
    function _normalize(Analysis storage a,uint256 id) private {
        FloatMath m=numericalMath;
        bytes16 next=m.sub(a.next[a.k],a.next[0]);
        if(m.compare(m.abs(next),MAX_FREE_ENERGY)>0) revert InvalidInput();
        bytes16 change=m.abs(m.sub(next,a.f[a.k]));
        if(m.compare(change,a.residual)>0)a.residual=change;
        a.f[a.k]=next;++a.k;
        if(a.k==a.states){
            a.k=0;++a.iterations;
            if(m.compare(a.residual,a.tolerance)<=0)a.status=Status.FinalDenominators;
            else if(a.iterations==a.maxIterations)a.status=Status.MaxIterations;
            else a.status=Status.Denominators;
            emit IterationCompleted(id,a.iterations,a.residual,a.status);
        }
    }
    function _logAdd(bytes16 a,bytes16 b) private view returns(bytes16) {
        FloatMath m=numericalMath;
        if(m.compare(a,b)<0)(a,b)=(b,a);
        bytes16 delta=m.sub(b,a);
        bytes16 correction=scalarMath.exp(delta);
        correction=m.add(ONE,correction);
        correction=scalarMath.ln(correction);
        return m.add(a,correction);
    }
    function runInfo(uint256 id) external view returns(bytes32 seriesId,bytes32 commitment,uint32 samples,uint8 states,
        uint32 iterations,uint32 maxIterations,uint32 sampleCursor,uint8 stateCursor,Status status,bytes16 residual,bytes16 tolerance) {
        Analysis storage a=_get(id);return(a.seriesId,a.commitment,a.samples,a.states,a.iterations,a.maxIterations,a.n,a.k,a.status,a.residual,a.tolerance);
    }
    function fAt(uint256 id,uint256 k) external view returns(bytes16){Analysis storage a=_get(id);if(k>=a.states)revert InvalidInput();return a.f[k];}
    function logDenominatorAt(uint256 id,uint256 n) external view returns(bytes16){Analysis storage a=_get(id);if(n>=a.samples || a.status!=Status.Converged)revert InvalidInput();return a.logDenominator[n];}
    function assertConverged(uint256 id) external view returns(bytes32 seriesId,bytes32 commitment,uint32 samples,uint8 states){
        _dependencies();Analysis storage a=_get(id);if(a.status!=Status.Converged)revert InvalidInput();
        if(collector.assertSealed(a.seriesId)!=a.sampleDigest)revert DependencyChanged();return(a.seriesId,a.commitment,a.samples,a.states);
    }
    function _dependencies() private view {if(address(collector).codehash!=dependencyHashes[0] || address(numericalMath).codehash!=dependencyHashes[1] || address(scalarMath).codehash!=dependencyHashes[2])revert DependencyChanged();}
    function _get(uint256 id) private view returns(Analysis storage a){a=_analyses[id];if(a.status==Status.Missing)revert UnknownAnalysis();}
}

