contracts/core/FullModelConstraintCatalo.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {FloatMath} from "../math/FloatMath.sol";
import {AlchemicalTopologyCatalog} from "./AlchemicalTopologyCatalog.sol";

interface IConstraintInputStreams {
    function assertStream(bytes32 id) external view returns (bytes32 commitment, uint64 words);
    function readWord(bytes32 id, uint64 index) external view returns (bytes32);
    function streamInfo(bytes32 id) external view returns
        (bytes32 role, uint64 words, uint64 appended, uint64 pages, bool isSealed, bytes32 commitment);
}

/// @notice Canonical distance constraints backed by an existing sealed input stream.
/// @dev This binds declared constraints to a validated hybrid topology; it does
///      not decide which chemical bonds should be constrained. No child contracts.
contract FullModelConstraintCatalog {
    error Unauthorized(); error InvalidInput(); error DependencyChanged(); error WrongStage();
    enum Stage { Missing, Validating, Complete }
    struct Constraint { uint32 a; uint32 b; bytes16 distance; }
    struct Info {
        Stage stage; bytes32 topologyId; bytes32 topologyCommitment; bytes32 streamId;
        bytes32 streamCommitment; bytes32 policyHash; bytes32 commitment;
        uint32 atoms; uint64 count; uint64 cursor; uint64 lastKey;
    }
    address public immutable owner;
    AlchemicalTopologyCatalog public immutable topology;
    FloatMath public immutable numericalMath;
    IConstraintInputStreams public immutable inputs;
    bytes32 public immutable topologyCodeHash;
    bytes32 public immutable mathCodeHash;
    bytes32 public immutable inputsCodeHash;
    bytes32 public constant CONSTRAINT_STREAM_ROLE = keccak256("ORVIA.FullModelConstraintTriples.v1");
    uint256 public constant MAX_WORK = 8;
    mapping(bytes32 => Info) private sets;
    event SetCreated(bytes32 indexed id, bytes32 indexed topologyId, bytes32 indexed streamId);
    event SetSealed(bytes32 indexed id, bytes32 commitment);

    constructor(address owner_, address topology_, address math_) {
        if (owner_ == address(0) || topology_.code.length == 0 || math_.code.length == 0
            || address(AlchemicalTopologyCatalog(topology_).numericalMath()) != math_) revert InvalidInput();
        address inputs_ = address(AlchemicalTopologyCatalog(topology_).inputs());
        if (inputs_.code.length == 0) revert InvalidInput();
        owner = owner_; topology = AlchemicalTopologyCatalog(topology_); numericalMath = FloatMath(math_);
        inputs = IConstraintInputStreams(inputs_);
        topologyCodeHash = topology_.codehash; mathCodeHash = math_.codehash; inputsCodeHash = inputs_.codehash;
    }

    function createSet(bytes32 id, bytes32 topologyId, bytes32 streamId, uint64 count, bytes32 policyHash) external {
        if (msg.sender != owner) revert Unauthorized(); _dependencies();
        if (id == bytes32(0) || sets[id].stage != Stage.Missing || policyHash == bytes32(0)) revert InvalidInput();
        bytes32 topologyCommitment = topology.assertTopology(topologyId);
        uint32 atoms = topology.definition(topologyId).atoms;
        if (count == 0 || count > type(uint64).max / 3 || uint256(count) > uint256(atoms) * (atoms - 1) / 2)
            revert InvalidInput();
        bytes32 streamCommitment = _validateStream(streamId, count);
        sets[id] = Info(Stage.Validating, topologyId, topologyCommitment, streamId, streamCommitment,
            policyHash, bytes32(0), atoms, count, 0, 0);
        emit SetCreated(id, topologyId, streamId);
    }

    function advance(bytes32 id, uint256 work) external returns (uint256 processed, bool complete) {
        if (work == 0 || work > MAX_WORK) revert InvalidInput();
        Info storage s = _get(id); _source(s);
        if (s.stage != Stage.Validating) revert WrongStage();
        while (processed < work && s.cursor < s.count) {
            Constraint memory c = _read(s, s.cursor);
            uint64 key = uint64(c.a) * s.atoms + c.b;
            if (s.cursor != 0 && key <= s.lastKey) revert InvalidInput();
            s.lastKey = key; ++s.cursor; ++processed;
        }
        complete = s.cursor == s.count;
        if (complete) {
            s.stage = Stage.Complete;
            bytes32 dependencies = keccak256(abi.encode(address(topology), address(inputs),
                topologyCodeHash, mathCodeHash, inputsCodeHash, CONSTRAINT_STREAM_ROLE));
            s.commitment = keccak256(abi.encode(bytes32("ORVIA-FULL-CONSTRAINTS-v1"), block.chainid,
                address(this), id, s, dependencies));
            emit SetSealed(id, s.commitment);
        }
    }

    function info(bytes32 id) external view returns (Info memory) { return _get(id); }
    function assertSet(bytes32 id) external view returns (bytes32) {
        Info storage s = _get(id); _source(s);
        if (s.stage != Stage.Complete) revert WrongStage(); return s.commitment;
    }
    function constraintAt(bytes32 id, uint64 index) external view returns (Constraint memory) {
        Info storage s = _get(id); _source(s);
        if (s.stage != Stage.Complete || index >= s.count) revert WrongStage(); return _read(s, index);
    }
    function _read(Info storage s, uint64 index) private view returns (Constraint memory c) {
        uint64 offset = index * 3;
        uint256 a = uint256(inputs.readWord(s.streamId, offset));
        uint256 b = uint256(inputs.readWord(s.streamId, offset + 1));
        uint256 distance = uint256(inputs.readWord(s.streamId, offset + 2));
        if (a >= b || b >= s.atoms || distance > type(uint128).max) revert InvalidInput();
        c = Constraint(uint32(a), uint32(b), bytes16(uint128(distance)));
        if (!numericalMath.isFinite(c.distance) || numericalMath.compare(c.distance, bytes16(0)) <= 0) revert InvalidInput();
    }
    function _source(Info storage s) private view {
        _dependencies();
        if (topology.assertTopology(s.topologyId) != s.topologyCommitment) revert DependencyChanged();
        (bytes32 commitment, uint64 words) = inputs.assertStream(s.streamId);
        if (commitment != s.streamCommitment || words != s.count * 3) revert DependencyChanged();
    }
    function _validateStream(bytes32 id, uint64 count) private view returns (bytes32 commitment) {
        uint64 words; (commitment, words) = inputs.assertStream(id);
        (bytes32 role, uint64 total, uint64 appended,, bool isSealed, bytes32 infoCommitment) = inputs.streamInfo(id);
        if (role != CONSTRAINT_STREAM_ROLE || !isSealed || words != count * 3 || total != words || appended != words
            || commitment == bytes32(0) || infoCommitment != commitment) revert InvalidInput();
    }
    function _dependencies() private view {
        if (address(topology).codehash != topologyCodeHash || address(numericalMath).codehash != mathCodeHash
            || address(inputs).codehash != inputsCodeHash) revert DependencyChanged();
    }
    function _get(bytes32 id) private view returns (Info storage s) {
        s = sets[id]; if (s.stage == Stage.Missing) revert InvalidInput();
    }
}

contracts/core/FullModelConstraintSolver.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {FloatMath} from "../math/FloatMath.sol";
import {DistanceConstraintKernel} from "../kernels/DistanceConstraintKernel.sol";
import {FullModelConstraintCatalog} from "./FullModelConstraintCatalog.sol";
import {AlchemicalTopologyCatalog} from "./AlchemicalTopologyCatalog.sol";

interface IConstraintState {
    function writer() external view returns (address);
    function readWord(bytes32 id, uint256 index) external view returns (bytes32);
    function readWords(bytes32 id, uint256 start, uint256 count) external view returns (bytes32[] memory);
    function namespaceInfo(bytes32 id) external view returns (uint32 capacity, bool isSealed);
    function snapshotInfo(bytes32 id) external view returns
        (bytes32 source, uint64 epoch, uint32 capacity, bytes32 writeDigest, bytes32 commitment);
}
interface IConstraintPipeline { function statePage() external view returns (address); }

/// @notice Bounded coupled SHAKE/RATTLE projection of authenticated frozen frames.
/// @dev Raw, consistently unwrapped pair displacements must lie strictly inside
///      each half box. This component does not select images or integrate a step.
///      Outputs are internal mappings, imported only after convergence by the
///      pinned pipeline. It cannot write state storage or create child contracts.
contract FullModelConstraintSolver {
    error Unauthorized(); error InvalidInput(); error InvalidDependency(); error DependencyChanged();
    error WrongStage(); error InvalidGeometry(); error SolutionUnavailable();
    enum Mode { Position, Velocity }
    enum Status { Missing, Correcting, Checking, Converged, Failed }
    struct Params {
        bytes32 setId; Mode mode; address sourcePage; bytes32 anchorSnapshot; bytes32 trialSnapshot;
        bytes32 sourceProtocolHash; bytes16 positionTolerance; bytes16 velocityTolerance; uint32 maxSweeps;
    }
    struct Info {
        Status status; Mode mode; uint32 atoms; uint64 count; uint64 cursor; uint32 sweeps;
        bytes16 maximumResidual; bytes4 failure; bytes32 inputCommitment; bytes32 outputCommitment;
    }
    struct Atom { bool loaded; bytes16[3] anchor; bytes16[3] current; bytes16 mass; }
    struct Problem {
        Params params; Info info; bytes32 sourceCodeHash; bytes32 anchorCommitment; bytes32 trialCommitment;
        bytes32 setCommitment; bytes32 massStream; bytes16[3] box; bytes32 transcript;
        mapping(uint32 => Atom) atoms;
    }
    address public immutable writer;
    FloatMath public immutable numericalMath;
    DistanceConstraintKernel public immutable kernel;
    FullModelConstraintCatalog public immutable catalog;
    AlchemicalTopologyCatalog public immutable topology;
    bytes32 public immutable writerCodeHash;
    bytes32 public immutable mathCodeHash;
    bytes32 public immutable kernelCodeHash;
    bytes32 public immutable catalogCodeHash;
    bytes32 public immutable configurationHash;
    uint256 public constant MAX_WORK = 8;
    uint32 public constant MAX_SWEEPS = 4096;
    bytes16 private constant ONE = 0x3fff0000000000000000000000000000;
    bytes16 private constant TWO = 0x40000000000000000000000000000000;
    mapping(bytes32 => Problem) private problems;
    event Registered(bytes32 indexed id, bytes32 inputCommitment);
    event Advanced(bytes32 indexed id, uint256 processed, Status status, uint64 cursor, uint32 sweeps);
    event Finished(bytes32 indexed id, Status status, bytes32 outputCommitment, bytes4 failure);

    constructor(address writer_, address math_, address kernel_, address catalog_) {
        if (writer_.code.length == 0 || math_.code.length == 0 || kernel_.code.length == 0 || catalog_.code.length == 0
            || address(DistanceConstraintKernel(kernel_).numericalMath()) != math_
            || address(FullModelConstraintCatalog(catalog_).numericalMath()) != math_) revert InvalidDependency();
        writer = writer_; numericalMath = FloatMath(math_); kernel = DistanceConstraintKernel(kernel_);
        catalog = FullModelConstraintCatalog(catalog_); topology = catalog.topology();
        writerCodeHash = writer_.codehash; mathCodeHash = math_.codehash;
        kernelCodeHash = kernel_.codehash; catalogCodeHash = catalog_.codehash;
        configurationHash = keccak256(abi.encode(bytes32("ORVIA-FULL-PROJECTION-v1"), writer_, math_, kernel_, catalog_,
            writerCodeHash, mathCodeHash, kernelCodeHash, catalogCodeHash));
    }

    function registerProblem(bytes32 id, Params calldata params) external {
        if (msg.sender != writer) revert Unauthorized(); _dependencies();
        if (id == bytes32(0) || problems[id].info.status != Status.Missing || params.sourceProtocolHash == bytes32(0)
            || params.maxSweeps == 0 || params.maxSweeps > MAX_SWEEPS) revert InvalidInput();
        _positive(params.positionTolerance); _positive(params.velocityTolerance);
        if (numericalMath.compare(params.positionTolerance, ONE) >= 0) revert InvalidInput();
        if (params.sourcePage.code.length == 0 || IConstraintPipeline(writer).statePage() != params.sourcePage
            || IConstraintState(params.sourcePage).writer() != writer) revert InvalidDependency();
        if (params.mode == Mode.Velocity && params.anchorSnapshot != params.trialSnapshot) revert InvalidInput();
        bytes32 setCommitment = catalog.assertSet(params.setId);
        FullModelConstraintCatalog.Info memory s = catalog.info(params.setId);
        AlchemicalTopologyCatalog.Definition memory d = topology.definition(s.topologyId);
        uint32 capacity = uint32(uint256(s.atoms) * 9 + 1);
        bytes32 anchor = _snapshot(params.sourcePage, params.anchorSnapshot, capacity);
        bytes32 trial = _snapshot(params.sourcePage, params.trialSnapshot, capacity);
        Problem storage p = problems[id]; p.params = params;
        p.sourceCodeHash = params.sourcePage.codehash; p.anchorCommitment = anchor; p.trialCommitment = trial;
        p.setCommitment = setCommitment; p.massStream = d.a.particles; p.box = d.box;
        p.info.status = Status.Correcting; p.info.mode = params.mode; p.info.atoms = s.atoms; p.info.count = s.count;
        p.info.inputCommitment = keccak256(abi.encode(configurationHash, block.chainid, address(this), id,
            params, setCommitment, p.sourceCodeHash, anchor, trial));
        p.transcript = keccak256(abi.encode(bytes32("ORVIA-CONSTRAINT-TRACE-v1"), p.info.inputCommitment));
        emit Registered(id, p.info.inputCommitment);
    }

    /// @notice Any payer may execute ordered work; no caller supplies atom values.
    function advance(bytes32 id, uint256 work) external returns (uint256 processed, Status status) {
        if (work == 0 || work > MAX_WORK) revert InvalidInput();
        Problem storage p = _get(id); _source(p);
        if (p.info.status != Status.Correcting && p.info.status != Status.Checking) revert WrongStage();
        while (processed < work && (p.info.status == Status.Correcting || p.info.status == Status.Checking)) {
            // Storage/dependency reads remain outside the numerical catch. Bank or
            // topology tampering reverts the transaction, never reports convergence failure.
            FullModelConstraintCatalog.Constraint memory c = catalog.constraintAt(p.params.setId, p.info.cursor);
            _load(p, c.a); _load(p, c.b);
            try this.processRecord(id, c) { }
            catch (bytes memory reason) {
                bytes4 selector;
                if (reason.length >= 4) assembly { selector := mload(add(reason, 32)) }
                if (!_domainError(selector)) assembly { revert(add(reason, 32), mload(reason)) }
                p.info.status = Status.Failed; p.info.failure = selector;
                emit Finished(id, Status.Failed, bytes32(0), selector); ++processed; break;
            }
            ++processed; ++p.info.cursor;
            if (p.info.cursor == p.info.count) _finishPass(id, p);
        }
        status = p.info.status;
        emit Advanced(id, processed, status, p.info.cursor, p.info.sweeps);
    }

    /// @dev Self-only numerical unit. A failed unit rolls back its atom updates.
    ///      Empty/unknown revert data (including insufficient gas) is propagated.
    function processRecord(bytes32 id, FullModelConstraintCatalog.Constraint calldata c) external {
        if (msg.sender != address(this)) revert Unauthorized();
        Problem storage p = problems[id]; Atom storage a = p.atoms[c.a]; Atom storage b = p.atoms[c.b];
        _positive(a.mass); _positive(b.mass);
        bytes16[3] memory anchor = _difference(a.anchor, b.anchor);
        bytes16[3] memory current = _difference(a.current, b.current);
        _image(anchor, p.box);
        if (numericalMath.compare(_positionResidual(anchor, c.distance), p.params.positionTolerance) > 0) revert InvalidGeometry();
        if (p.info.mode == Mode.Position) {
            _image(current, p.box);
            // The local SHAKE branch applies even when the distance residual is
            // already small: an exactly reversed bond must not bypass the kernel.
            if (numericalMath.compare(_dot(anchor, current), bytes16(0)) <= 0)
                revert DistanceConstraintKernel.NoLocalSolution();
        }
        bytes16 residual = p.info.mode == Mode.Position ? _positionResidual(current, c.distance)
            : _velocityResidual(anchor, current);
        if (p.info.status == Status.Checking) {
            if (numericalMath.compare(residual, p.info.maximumResidual) > 0) p.info.maximumResidual = residual;
            return;
        }
        if (numericalMath.compare(residual, _tolerance(p)) > 0) {
            bytes16[3] memory ca; bytes16[3] memory cb;
            if (p.info.mode == Mode.Position) (ca, cb,) = kernel.positionCorrection(
                DistanceConstraintKernel.PositionInput(anchor, current, a.mass, b.mass, c.distance));
            else (ca, cb,) = kernel.velocityCorrection(
                DistanceConstraintKernel.VelocityInput(anchor, current, a.mass, b.mass));
            for (uint256 axis; axis < 3; ++axis) {
                a.current[axis] = numericalMath.add(a.current[axis], ca[axis]);
                b.current[axis] = numericalMath.add(b.current[axis], cb[axis]);
            }
            if (p.info.mode == Mode.Position) _image(_difference(a.current, b.current), p.box);
        }
        p.transcript = keccak256(abi.encode(p.transcript, p.info.sweeps, p.info.cursor, a.current, b.current));
    }

    function problemInfo(bytes32 id) external view returns (Info memory) { return _get(id).info; }
    function problemParams(bytes32 id) external view returns (Params memory) { return _get(id).params; }
    function assertSolution(bytes32 id) external view returns (bytes32) {
        Problem storage p = _get(id); _source(p); _converged(p); return p.info.outputCommitment;
    }
    function solutionAt(bytes32 id, uint32 atom) external view returns (bytes16[3] memory) {
        Problem storage p = _get(id); _source(p); _converged(p); return _solution(p, atom);
    }
    function correctionAt(bytes32 id, uint32 atom) external view returns (bytes16[3] memory correction) {
        Problem storage p = _get(id); _source(p); _converged(p);
        bytes16[3] memory solution = _solution(p, atom);
        bytes16[3] memory original = _vector(p, p.params.trialSnapshot, atom, p.info.mode == Mode.Position ? 0 : 3);
        for (uint256 axis; axis < 3; ++axis) correction[axis] = numericalMath.sub(solution[axis], original[axis]);
    }
    function _solution(Problem storage p, uint32 atom) private view returns (bytes16[3] memory) {
        if (atom >= p.info.atoms) revert InvalidInput();
        bytes16[3] memory original = _vector(p, p.params.trialSnapshot, atom, p.info.mode == Mode.Position ? 0 : 3);
        if (p.atoms[atom].loaded) return p.atoms[atom].current;
        return original;
    }
    function _load(Problem storage p, uint32 atom) private {
        // Re-read touched storage even after caching, retaining each router's
        // bank-code checks without an unbounded scan of the complete atom set.
        bytes16[3] memory anchor = _vector(p, p.params.anchorSnapshot, atom, 0);
        bytes16[3] memory current = _vector(p, p.params.trialSnapshot, atom, p.info.mode == Mode.Position ? 0 : 3);
        bytes16 mass = _decode(topology.word(p.massStream, uint64(atom) * 4));
        Atom storage a = p.atoms[atom]; if (a.loaded) return;
        a.anchor = anchor; a.current = current; a.mass = mass; a.loaded = true;
    }
    function _vector(Problem storage p, bytes32 snapshot, uint32 atom, uint256 offset) private view returns (bytes16[3] memory v) {
        bytes32[] memory words = IConstraintState(p.params.sourcePage).readWords(snapshot, uint256(atom) * 9 + offset, 3);
        if (words.length != 3) revert InvalidInput();
        for (uint256 axis; axis < 3; ++axis)
            v[axis] = _decode(words[axis]);
    }
    function _finishPass(bytes32 id, Problem storage p) private {
        p.info.cursor = 0;
        if (p.info.status == Status.Correcting) { p.info.status = Status.Checking; p.info.maximumResidual = bytes16(0); return; }
        ++p.info.sweeps;
        if (numericalMath.compare(p.info.maximumResidual, _tolerance(p)) <= 0) {
            p.info.status = Status.Converged;
            p.info.outputCommitment = keccak256(abi.encode(bytes32("ORVIA-CONSTRAINT-SOLUTION-v1"),
                p.info.inputCommitment, p.transcript, p.info.sweeps, p.info.maximumResidual));
        } else if (p.info.sweeps == p.params.maxSweeps) p.info.status = Status.Failed;
        else { p.info.status = Status.Correcting; return; }
        emit Finished(id, p.info.status, p.info.outputCommitment, p.info.failure);
    }
    function _positionResidual(bytes16[3] memory displacement, bytes16 target) private view returns (bytes16) {
        bytes16 squared = numericalMath.mul(target, target); _positive(squared);
        return numericalMath.div(numericalMath.abs(numericalMath.sub(_dot(displacement, displacement), squared)), squared);
    }
    function _velocityResidual(bytes16[3] memory displacement, bytes16[3] memory velocity) private view returns (bytes16) {
        bytes16 squared = _dot(displacement, displacement); _positive(squared);
        return numericalMath.abs(numericalMath.div(_dot(displacement, velocity), squared));
    }
    function _image(bytes16[3] memory d, bytes16[3] memory box) private view {
        for (uint256 axis; axis < 3; ++axis)
            if (numericalMath.compare(numericalMath.abs(d[axis]), numericalMath.div(box[axis], TWO)) >= 0) revert InvalidGeometry();
    }
    function _difference(bytes16[3] memory a, bytes16[3] memory b) private view returns (bytes16[3] memory d) {
        for (uint256 axis; axis < 3; ++axis) d[axis] = numericalMath.sub(b[axis], a[axis]);
    }
    function _dot(bytes16[3] memory a, bytes16[3] memory b) private view returns (bytes16 result) {
        for (uint256 axis; axis < 3; ++axis) result = numericalMath.add(result, numericalMath.mul(a[axis], b[axis]));
    }
    function _tolerance(Problem storage p) private view returns (bytes16) {
        return p.info.mode == Mode.Position ? p.params.positionTolerance : p.params.velocityTolerance;
    }
    function _snapshot(address source, bytes32 snapshot, uint32 expected) private view returns (bytes32 commitment) {
        (uint32 capacity, bool isSealed) = IConstraintState(source).namespaceInfo(snapshot);
        (bytes32 origin, uint64 epoch, uint32 snapshotCapacity,, bytes32 binding) = IConstraintState(source).snapshotInfo(snapshot);
        if (!isSealed || capacity != expected || snapshotCapacity != expected || origin == bytes32(0)
            || epoch == 0 || binding == bytes32(0)) revert InvalidInput(); return binding;
    }
    function _source(Problem storage p) private view {
        _dependencies();
        if (p.params.sourcePage.codehash != p.sourceCodeHash || IConstraintPipeline(writer).statePage() != p.params.sourcePage
            || IConstraintState(p.params.sourcePage).writer() != writer || catalog.assertSet(p.params.setId) != p.setCommitment)
            revert DependencyChanged();
        uint32 capacity = uint32(uint256(p.info.atoms) * 9 + 1);
        if (_snapshot(p.params.sourcePage, p.params.anchorSnapshot, capacity) != p.anchorCommitment
            || _snapshot(p.params.sourcePage, p.params.trialSnapshot, capacity) != p.trialCommitment) revert DependencyChanged();
    }
    function _dependencies() private view {
        if (writer.codehash != writerCodeHash || address(numericalMath).codehash != mathCodeHash
            || address(kernel).codehash != kernelCodeHash || address(catalog).codehash != catalogCodeHash) revert DependencyChanged();
    }
    function _converged(Problem storage p) private view { if (p.info.status != Status.Converged) revert SolutionUnavailable(); }
    function _get(bytes32 id) private view returns (Problem storage p) {
        p = problems[id]; if (p.info.status == Status.Missing) revert InvalidInput();
    }
    function _positive(bytes16 x) private view {
        if (!numericalMath.isFinite(x) || numericalMath.compare(x, bytes16(0)) <= 0) revert InvalidInput();
    }
    function _decode(bytes32 word_) private pure returns (bytes16 value) {
        if (uint256(word_) > type(uint128).max) revert InvalidInput();
        value = bytes16(uint128(uint256(word_)));
        if (((uint128(value) >> 112) & 0x7fff) == 0x7fff) revert InvalidInput();
        if ((uint128(value) & 0x7fffffffffffffffffffffffffffffff) == 0) value = bytes16(0);
    }
    function _domainError(bytes4 selector) private pure returns (bool) {
        return selector == InvalidGeometry.selector || selector == InvalidInput.selector
            || selector == DistanceConstraintKernel.NoLocalSolution.selector
            || selector == FloatMath.NonFinite.selector || selector == FloatMath.DivisionByZero.selector
            || selector == FloatMath.NegativeSquareRoot.selector;
    }
}

contracts/kernels/DistanceConstraintKern.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {FloatMath} from "../math/FloatMath.sol";

/// @notice One mass-weighted SHAKE position or RATTLE velocity correction.
/// @dev A coordinator must iterate coupled constraints to a registered tolerance
///      and reject nonconvergence before committing a timestep.
contract DistanceConstraintKernel {
    error InvalidDependency();
    error InvalidInput();
    error NoLocalSolution();
    FloatMath public immutable numericalMath;
    bytes32 public constant KERNEL_ID = keccak256("ORVIA.DistanceConstraintKernel.v1");

    struct PositionInput {
        bytes16[3] oldDisplacement;
        bytes16[3] trialDisplacement;
        bytes16 massA;
        bytes16 massB;
        bytes16 target;
    }
    struct VelocityInput {
        bytes16[3] displacement;
        bytes16[3] relativeVelocity;
        bytes16 massA;
        bytes16 massB;
    }

    constructor(address math_) {
        if (math_.code.length == 0) revert InvalidDependency();
        numericalMath = FloatMath(math_);
    }

    /// @notice Corrections are added to A and B; displacements use B-A.
    function positionCorrection(PositionInput calldata p) external view
        returns (bytes16[3] memory correctionA, bytes16[3] memory correctionB, bytes16 relativeResidual)
    {
        FloatMath m = numericalMath;
        _positive(p.massA); _positive(p.massB); _positive(p.target);
        bytes16 oldSquared = _dot(p.oldDisplacement, p.oldDisplacement);
        _positive(oldSquared);
        bytes16 dot = _dot(p.oldDisplacement, p.trialDisplacement);
        // Restrict to the continuous local SHAKE root, not a bond orientation flip.
        if (m.compare(dot, bytes16(0)) <= 0) revert NoLocalSolution();
        bytes16 targetSquared = m.mul(p.target, p.target);
        _positive(targetSquared);
        bytes16 defect = m.sub(_dot(p.trialDisplacement, p.trialDisplacement), targetSquared);
        relativeResidual = m.div(m.abs(defect), targetSquared);
        bytes16 discriminant = m.sub(m.mul(dot, dot), m.mul(oldSquared, defect));
        if (m.compare(discriminant, bytes16(0)) < 0) revert NoLocalSolution();
        // x=defect/(dot+sqrt(dot^2-oldSquared*defect)) avoids subtractive cancellation.
        bytes16 x = m.div(defect, m.add(dot, m.sqrt(discriminant)));
        (correctionA, correctionB) = _corrections(p.oldDisplacement, x, p.massA, p.massB);
    }

    function velocityCorrection(VelocityInput calldata p) external view
        returns (bytes16[3] memory correctionA, bytes16[3] memory correctionB, bytes16 relativeResidual)
    {
        _positive(p.massA); _positive(p.massB);
        FloatMath m = numericalMath;
        bytes16 squared = _dot(p.displacement, p.displacement);
        _positive(squared);
        bytes16 x = m.div(_dot(p.displacement, p.relativeVelocity), squared);
        // Residual has units inverse time; it is distinct from position tolerance.
        relativeResidual = m.abs(x);
        (correctionA, correctionB) = _corrections(p.displacement, x, p.massA, p.massB);
    }

    function _corrections(bytes16[3] memory direction, bytes16 x, bytes16 massA, bytes16 massB)
        private view returns (bytes16[3] memory a, bytes16[3] memory b)
    {
        FloatMath m = numericalMath;
        bytes16 totalMass = m.add(massA, massB);
        bytes16 shareA = m.mul(x, m.div(massB, totalMass));
        bytes16 shareB = m.neg(m.mul(x, m.div(massA, totalMass)));
        for (uint256 axis; axis < 3; ++axis) {
            a[axis] = m.mul(shareA, direction[axis]);
            b[axis] = m.mul(shareB, direction[axis]);
        }
    }

    function _dot(bytes16[3] memory a, bytes16[3] memory b) private view returns (bytes16 sum) {
        for (uint256 axis; axis < 3; ++axis) {
            if (!numericalMath.isFinite(a[axis]) || !numericalMath.isFinite(b[axis])) revert InvalidInput();
            sum = numericalMath.add(sum, numericalMath.mul(a[axis], b[axis]));
        }
    }

    function _positive(bytes16 value) private view {
        if (!numericalMath.isFinite(value) || numericalMath.compare(value, bytes16(0)) <= 0) revert InvalidInput();
    }
}

contracts/core/BankedWorkingState.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @dev One member of a fixed, router-created pool. Namespace and GLOBAL word
///      index remain in the key when different logical pages reuse this bank.
contract BankedStateStorageBank {
    error Unauthorized();
    error InvalidRange();
    error InvalidEpoch();

    address public immutable router;
    bytes32 public immutable routerCodeHash;
    struct Version { uint64 epoch; bytes32 value; }
    mapping(bytes32 => mapping(uint256 => Version[])) private _history;

    constructor(address router_) {
        if (router_ != msg.sender || router_.code.length == 0) revert Unauthorized();
        router = router_; routerCodeHash = router_.codehash;
    }

    modifier onlyRouter() {
        if (msg.sender != router || router.codehash != routerCodeHash) revert Unauthorized();
        _;
    }

    function writeWords(bytes32 namespace, uint256 start, bytes32[] calldata values, uint64 epoch)
        external onlyRouter
    {
        if (epoch == 0) revert InvalidEpoch();
        _range(start, values.length);
        if (values.length == 0) revert InvalidRange();
        for (uint256 i; i < values.length; ++i) {
            Version[] storage versions = _history[namespace][start + i];
            uint256 length = versions.length;
            if (length != 0 && versions[length - 1].epoch > epoch) revert InvalidEpoch();
            if (length != 0 && versions[length - 1].epoch == epoch) versions[length - 1].value = values[i];
            else versions.push(Version(epoch, values[i]));
        }
    }

    function readWords(bytes32 namespace, uint256 start, uint256 count, uint64 epoch)
        external view onlyRouter returns (bytes32[] memory values)
    {
        if (epoch == 0) revert InvalidEpoch();
        _range(start, count);
        values = new bytes32[](count);
        for (uint256 i; i < count; ++i) {
            Version[] storage versions = _history[namespace][start + i];
            uint256 low; uint256 high = versions.length;
            if (high == 0) continue;
            if (versions[high - 1].epoch <= epoch) { values[i] = versions[high - 1].value; continue; }
            // At most one version per strictly increasing uint64 epoch: <=64
            // predecessor-search rounds, independent of namespaces/page count.
            while (low < high) {
                uint256 middle = low + (high - low) / 2;
                if (versions[middle].epoch <= epoch) low = middle + 1;
                else high = middle;
            }
            if (low != 0) values[i] = versions[low - 1].value;
        }
    }

    function _range(uint256 start, uint256 count) private pure {
        if (start >= type(uint32).max || count > 128 || count > 4096 - (start % 4096)
            || count > uint256(type(uint32).max) - start) revert InvalidRange();
    }
}

/// @notice Mutable word namespaces and retained snapshots in a fixed bank pool.
/// @dev Matches the ShardedWorkingState consumer ABI. Provisioning is explicit:
///      reads of unprovisioned, unwritten banks are zero; writes fail closed.
///      No namespace, write, snapshot or seal operation deploys a child contract.
contract BankedWorkingState {
    error Unauthorized();
    error InvalidWriter();
    error InvalidBankCount();
    error InvalidNamespace();
    error NamespaceExists();
    error UnknownNamespace();
    error InvalidCapacity();
    error NamespaceSealed();
    error InvalidBatch();
    error OutOfBounds();
    error InvalidSnapshotSource();
    error NotSnapshot();
    error EpochExhausted();
    error BankUnavailable();
    error BankChanged();

    uint256 public constant MAX_CAPACITY_WORDS = type(uint32).max;
    uint256 public constant MAX_BATCH_WORDS = 128;
    uint256 public constant SHARD_WORDS = 4096;
    uint256 public constant MAX_BANKS = 128;
    uint256 public constant MAX_BANKS_PER_DEPLOY = 4;
    address public immutable writer;
    bytes32 public immutable writerCodeHash;
    uint16 public immutable bankCount;
    uint16 public deployedBankCount;
    bytes32 public bankRuntimeCodeHash;

    struct Bank { address page; bytes32 codeHash; }
    struct Namespace {
        uint32 capacityWords;
        bool isSealed;
        bool isSnapshot;
        uint64 epoch;
        bytes32 source;
        bytes32 writeDigest;
        bytes32 commitment;
    }
    mapping(uint256 => Bank) private _banks;
    mapping(bytes32 => Namespace) private _namespaces;

    event BankDeployed(uint256 indexed index, address indexed page, bytes32 codeHash);
    event NamespaceCreated(bytes32 indexed namespace, uint32 capacityWords);
    event WordsWritten(bytes32 indexed namespace, uint256 start, uint256 count, bytes32 writeDigest);
    event NamespaceFrozen(bytes32 indexed namespace);
    event SnapshotCreated(bytes32 indexed source, bytes32 indexed snapshot, uint64 epoch, bytes32 commitment);

    modifier onlyWriter() {
        if (msg.sender != writer || writer.codehash != writerCodeHash) revert Unauthorized();
        _;
    }

    constructor(address writer_, uint16 bankCount_) {
        if (writer_ == address(0) || writer_.code.length == 0) revert InvalidWriter();
        if (bankCount_ == 0 || bankCount_ > MAX_BANKS) revert InvalidBankCount();
        writer = writer_; writerCodeHash = writer_.codehash; bankCount = bankCount_;
    }

    /// @notice Anyone may pay to provision the next <=4 predetermined banks.
    /// @dev Cannot register arbitrary code, replace a bank or grow the fixed pool.
    function deployBanks(uint256 work) external returns (uint256 processed, bool complete) {
        if (work == 0 || work > MAX_BANKS_PER_DEPLOY) revert InvalidBatch();
        uint256 next = deployedBankCount;
        while (processed < work && next < bankCount) {
            address page = address(new BankedStateStorageBank{salt: bytes32(next)}(address(this)));
            bytes32 codeHash = page.codehash;
            if (next == 0) bankRuntimeCodeHash = codeHash;
            else if (codeHash != bankRuntimeCodeHash) revert BankChanged();
            _banks[next] = Bank(page, codeHash);
            emit BankDeployed(next, page, codeHash);
            ++next; ++processed;
        }
        deployedBankCount = uint16(next);
        complete = next == bankCount;
    }

    function createNamespace(bytes32 namespace, uint32 capacityWords) external onlyWriter {
        if (namespace == bytes32(0)) revert InvalidNamespace();
        if (_namespaces[namespace].capacityWords != 0) revert NamespaceExists();
        if (capacityWords == 0) revert InvalidCapacity();
        Namespace storage n = _namespaces[namespace];
        n.capacityWords = capacityWords; n.epoch = 1;
        n.writeDigest = keccak256(abi.encode(bytes32("ORVIA-BANKED-STATE-v1"), block.chainid,
            address(this), writer, writerCodeHash, bankCount, namespace, capacityWords));
        emit NamespaceCreated(namespace, capacityWords);
    }

    function writeWord(bytes32 namespace, uint256 index, bytes32 value) external onlyWriter {
        bytes32[] memory values = new bytes32[](1); values[0] = value;
        _write(namespace, index, values);
    }
    function writeWords(bytes32 namespace, uint256 start, bytes32[] calldata values) external onlyWriter {
        _write(namespace, start, values);
    }
    function _write(bytes32 namespace, uint256 start, bytes32[] memory values) private {
        Namespace storage n = _get(namespace);
        if (n.isSealed) revert NamespaceSealed();
        if (values.length == 0 || values.length > MAX_BATCH_WORDS) revert InvalidBatch();
        _range(n.capacityWords, start, values.length);
        uint256 done;
        while (done < values.length) {
            uint256 index = start + done;
            uint256 count = values.length - done;
            if (count > SHARD_WORDS - (index % SHARD_WORDS)) count = SHARD_WORDS - (index % SHARD_WORDS);
            Bank storage bank = _banks[(index / SHARD_WORDS) % bankCount];
            if (bank.page == address(0)) revert BankUnavailable();
            _assertBank(bank);
            bytes32[] memory chunk = new bytes32[](count);
            for (uint256 i; i < count; ++i) {
                chunk[i] = values[done + i];
                n.writeDigest = keccak256(abi.encode(n.writeDigest, index + i, chunk[i]));
            }
            BankedStateStorageBank(bank.page).writeWords(namespace, index, chunk, n.epoch);
            done += count;
        }
        emit WordsWritten(namespace, start, values.length, n.writeDigest);
    }

    function readWord(bytes32 namespace, uint256 index) external view returns (bytes32) {
        return _read(namespace, index, 1)[0];
    }
    function readWords(bytes32 namespace, uint256 start, uint256 count) external view returns (bytes32[] memory) {
        return _read(namespace, start, count);
    }
    function _read(bytes32 namespace, uint256 start, uint256 count) private view returns (bytes32[] memory values) {
        Namespace storage viewNamespace = _get(namespace);
        if (count > MAX_BATCH_WORDS) revert InvalidBatch();
        _range(viewNamespace.capacityWords, start, count);
        bytes32 source = viewNamespace.isSnapshot ? viewNamespace.source : namespace;
        uint64 epoch = viewNamespace.isSnapshot ? viewNamespace.epoch : _namespaces[source].epoch;
        values = new bytes32[](count);
        uint256 done;
        while (done < count) {
            uint256 index = start + done;
            uint256 length = count - done;
            if (length > SHARD_WORDS - (index % SHARD_WORDS)) length = SHARD_WORDS - (index % SHARD_WORDS);
            Bank storage bank = _banks[(index / SHARD_WORDS) % bankCount];
            if (bank.page != address(0)) {
                _assertBank(bank);
                bytes32[] memory chunk = BankedStateStorageBank(bank.page).readWords(source, index, length, epoch);
                for (uint256 i; i < length; ++i) values[done + i] = chunk[i];
            }
            done += length;
        }
    }

    /// @dev Only the pinned writer establishes scientific completion and derives
    ///      snapshot names from complete run/step identity. Storage does not infer it.
    function snapshotNamespace(bytes32 source, bytes32 snapshot) external onlyWriter returns (bytes32 commitment) {
        Namespace storage n = _get(source);
        if (n.isSnapshot) revert InvalidSnapshotSource();
        if (snapshot == bytes32(0)) revert InvalidNamespace();
        if (_namespaces[snapshot].capacityWords != 0) revert NamespaceExists();
        if (n.epoch == type(uint64).max) revert EpochExhausted();
        Namespace storage s = _namespaces[snapshot];
        s.capacityWords = n.capacityWords; s.isSealed = true; s.isSnapshot = true;
        s.epoch = n.epoch; s.source = source; s.writeDigest = n.writeDigest;
        commitment = keccak256(abi.encode(bytes32("ORVIA-BANKED-SNAPSHOT-v1"), block.chainid,
            address(this), writer, writerCodeHash, bankCount, source, snapshot, s.epoch, s.capacityWords, s.writeDigest));
        s.commitment = commitment; ++n.epoch;
        emit SnapshotCreated(source, snapshot, s.epoch, commitment);
    }
    function snapshotInfo(bytes32 snapshot) external view returns (
        bytes32 source, uint64 epoch, uint32 capacityWords, bytes32 writeDigest, bytes32 commitment
    ) {
        Namespace storage s = _get(snapshot);
        if (!s.isSnapshot) revert NotSnapshot();
        return (s.source, s.epoch, s.capacityWords, s.writeDigest, s.commitment);
    }
    function namespaceInfo(bytes32 namespace) external view returns (uint32 capacityWords, bool isSealed) {
        Namespace storage n = _get(namespace); return (n.capacityWords, n.isSealed);
    }
    function namespaceCommitment(bytes32 namespace) external view returns (bytes32 writeDigest, uint64 epoch) {
        Namespace storage n = _get(namespace); return (n.writeDigest, n.epoch);
    }
    function bankInfo(uint256 index) external view returns (address page, bytes32 codeHash) {
        if (index >= bankCount) revert OutOfBounds();
        Bank storage bank = _banks[index]; return (bank.page, bank.codeHash);
    }
    /// @notice Compatibility metadata: logical pages share physical bank addresses.
    function shardInfo(bytes32 namespace, uint256 shardIndex) external view returns (address page, bytes32 codeHash) {
        Namespace storage n = _get(namespace);
        if (shardIndex >= (uint256(n.capacityWords) + SHARD_WORDS - 1) / SHARD_WORDS) revert OutOfBounds();
        Bank storage bank = _banks[shardIndex % bankCount]; return (bank.page, bank.codeHash);
    }
    function sealNamespace(bytes32 namespace) external onlyWriter {
        Namespace storage n = _get(namespace);
        if (n.isSealed) revert NamespaceSealed();
        n.isSealed = true; emit NamespaceFrozen(namespace);
    }
    function _assertBank(Bank storage bank) private view {
        if (bank.page.code.length == 0 || bank.page.codehash != bank.codeHash
            || bank.codeHash != bankRuntimeCodeHash) revert BankChanged();
    }
    function _get(bytes32 namespace) private view returns (Namespace storage n) {
        n = _namespaces[namespace]; if (n.capacityWords == 0) revert UnknownNamespace();
    }
    function _range(uint32 capacity, uint256 start, uint256 count) private pure {
        if (start > capacity || count > uint256(capacity) - start) revert OutOfBounds();
    }
}

contracts/core/BankedInputCatalog.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @dev One of the catalog's 96 permanent banks. Global indices are namespaced
///      by stream ID; neither another stream nor a later routing cycle aliases them.
contract InputWordBank {
    error Unauthorized();
    error InvalidConfiguration();
    error InvalidRange();

    address public immutable router;
    bytes32 public immutable routerCodeHash;
    uint8 public immutable bankIndex;
    mapping(bytes32 => mapping(uint64 => bytes32)) private _words;

    constructor(address router_, uint8 bankIndex_) {
        if (router_ != msg.sender || router_.code.length == 0 || bankIndex_ >= 96)
            revert InvalidConfiguration();
        router = router_;
        routerCodeHash = router_.codehash;
        bankIndex = bankIndex_;
    }

    function writeWords(bytes32 stream, uint64 start, bytes32[] calldata values) external {
        if (msg.sender != router || msg.sender.codehash != routerCodeHash) revert Unauthorized();
        _range(start, values.length);
        if (stream == bytes32(0)) revert InvalidRange();
        for (uint256 i; i < values.length; ++i) _words[stream][uint64(uint256(start) + i)] = values[i];
    }

    /// @dev Raw bank reads do not establish stream sealing or coverage. Consumers
    ///      must use the catalog's authenticated, sealed-stream read interface.
    function readWord(bytes32 stream, uint64 index) external view returns (bytes32) {
        _range(index, 1);
        return _words[stream][index];
    }

    function readWords(bytes32 stream, uint64 start, uint32 count) external view returns (bytes32[] memory values) {
        _range(start, count);
        values = new bytes32[](count);
        for (uint256 i; i < count; ++i) values[i] = _words[stream][uint64(uint256(start) + i)];
    }

    function _range(uint64 start, uint256 count) private view {
        if (count == 0 || count > 128 || uint256(start) + count - 1 > type(uint64).max
            || (uint256(start) / 4096) % 96 != bankIndex
            || count > 4096 - uint256(start) % 4096) revert InvalidRange();
    }
}

/// @notice Append-only input streams sharing exactly 96 permanent storage banks.
/// @dev Bank allocation is independent of model size and stream count. Storage
///      slots and gas still grow with words uploaded; 96 banks is not a size cap.
contract BankedInputCatalog {
    error Unauthorized();
    error InvalidConfiguration();
    error InvalidBankBatch();
    error BanksIncomplete();
    error BankChanged();
    error StreamExists();
    error UnknownStream();
    error StreamSealed();
    error IncompleteStream();
    error InvalidBatch();
    error InvalidRead();

    uint256 public constant BANK_COUNT = 96;
    uint256 public constant MAX_BANKS_PER_CREATION = 4;
    uint256 public constant PAGE_WORDS = 4096;
    uint256 public constant MAX_BATCH_WORDS = 128;
    address public immutable owner;
    uint8 public bankCount;
    bytes32 public banksCommitment;

    struct Bank { address instance; bytes32 codeHash; }
    struct Stream {
        bytes32 role;
        uint64 totalWords;
        uint64 appendedWords;
        bool isSealed;
        bool exists;
        bytes32 rollingDigest;
        bytes32 commitment;
    }
    Bank[96] private _banks;
    mapping(bytes32 => Stream) private _streams;

    event BankCreated(uint8 indexed bankIndex, address indexed instance, bytes32 codeHash);
    event BanksReady(bytes32 commitment);
    event StreamBegun(bytes32 indexed stream, bytes32 indexed role, uint64 totalWords);
    event WordsAppended(bytes32 indexed stream, uint64 start, uint32 count, bytes32 rollingDigest);
    event StreamFrozen(bytes32 indexed stream, bytes32 commitment, uint64 totalWords);

    modifier onlyOwner() { if (msg.sender != owner) revert Unauthorized(); _; }

    constructor(address owner_) {
        if (owner_ == address(0)) revert InvalidConfiguration();
        owner = owner_;
        banksCommitment = keccak256(abi.encode(bytes32("ORVIA-INPUT-BANKS-v1"),
            block.chainid, address(this), BANK_COUNT, PAGE_WORDS));
    }

    /// @notice Allocate the next 1–4 banks. No other function creates contracts.
    function createBanks(uint8 count) external onlyOwner {
        if (count == 0 || count > MAX_BANKS_PER_CREATION || uint256(bankCount) + count > BANK_COUNT)
            revert InvalidBankBatch();
        for (uint256 i; i < count; ++i) {
            uint8 index = bankCount;
            address instance = address(new InputWordBank{salt: bytes32(uint256(index))}(address(this), index));
            bytes32 codeHash = instance.codehash;
            _banks[index] = Bank(instance, codeHash);
            banksCommitment = keccak256(abi.encode(banksCommitment, index, instance, codeHash));
            ++bankCount;
            emit BankCreated(index, instance, codeHash);
        }
        if (bankCount == BANK_COUNT) emit BanksReady(banksCommitment);
    }

    function bankInfo(uint8 index) external view returns (address instance, bytes32 codeHash) {
        if (index >= BANK_COUNT) revert InvalidRead();
        Bank storage bank = _banks[index];
        return (bank.instance, bank.codeHash);
    }

    function bankForWord(uint64 index) public pure returns (uint8) {
        return uint8((uint256(index) / PAGE_WORDS) % BANK_COUNT);
    }

    function beginStream(bytes32 id, bytes32 role, uint64 totalWords) external onlyOwner {
        if (bankCount != BANK_COUNT) revert BanksIncomplete();
        if (id == bytes32(0) || role == bytes32(0)) revert InvalidConfiguration();
        if (_streams[id].exists) revert StreamExists();
        Stream storage stream = _streams[id];
        stream.role = role;
        stream.totalWords = totalWords;
        stream.exists = true;
        stream.rollingDigest = keccak256(abi.encode(bytes32("ORVIA-BANKED-INPUT-v1"),
            block.chainid, address(this), id, role, totalWords, banksCommitment));
        emit StreamBegun(id, role, totalWords);
    }

    /// @notice Append the next canonical words, without caller-selected offsets.
    function appendWords(bytes32 id, bytes32[] calldata values) external onlyOwner {
        Stream storage stream = _get(id);
        if (stream.isSealed) revert StreamSealed();
        uint256 count = values.length;
        if (count == 0 || count > MAX_BATCH_WORDS || count > stream.totalWords - stream.appendedWords)
            revert InvalidBatch();
        uint64 start = stream.appendedWords;
        bytes32 digest = stream.rollingDigest;
        uint256 done;
        while (done < count) {
            uint64 index = uint64(uint256(start) + done);
            uint256 length = count - done;
            uint256 remainder = PAGE_WORDS - uint256(index) % PAGE_WORDS;
            if (length > remainder) length = remainder;
            Bank storage bank = _bank(bankForWord(index));
            InputWordBank(bank.instance).writeWords(id, index, values[done:done + length]);
            for (uint256 i; i < length; ++i)
                digest = keccak256(abi.encode(digest, uint64(uint256(index) + i), values[done + i]));
            done += length;
        }
        stream.appendedWords += uint64(count);
        stream.rollingDigest = digest;
        emit WordsAppended(id, start, uint32(count), digest);
    }

    function sealStream(bytes32 id) external onlyOwner returns (bytes32 commitment) {
        Stream storage stream = _get(id);
        if (stream.isSealed) revert StreamSealed();
        if (stream.appendedWords != stream.totalWords) revert IncompleteStream();
        commitment = keccak256(abi.encode(bytes32("ORVIA-SEALED-BANKS-v1"), block.chainid,
            address(this), id, stream.role, stream.totalWords, stream.rollingDigest, banksCommitment));
        stream.commitment = commitment;
        stream.isSealed = true;
        emit StreamFrozen(id, commitment, stream.totalWords);
    }

    function assertStream(bytes32 id) external view returns (bytes32 commitment, uint64 wordCount) {
        Stream storage stream = _sealed(id);
        return (stream.commitment, stream.totalWords);
    }

    function readWord(bytes32 id, uint64 index) external view returns (bytes32) {
        Stream storage stream = _sealed(id);
        if (index >= stream.totalWords) revert InvalidRead();
        return InputWordBank(_bank(bankForWord(index)).instance).readWord(id, index);
    }

    function readWords(bytes32 id, uint64 start, uint32 count) external view returns (bytes32[] memory values) {
        Stream storage stream = _sealed(id);
        if (count > MAX_BATCH_WORDS || start > stream.totalWords || count > stream.totalWords - start)
            revert InvalidRead();
        values = new bytes32[](count);
        uint256 done;
        while (done < count) {
            uint64 index = uint64(uint256(start) + done);
            uint256 length = count - done;
            uint256 remainder = PAGE_WORDS - uint256(index) % PAGE_WORDS;
            if (length > remainder) length = remainder;
            bytes32[] memory words = InputWordBank(_bank(bankForWord(index)).instance)
                .readWords(id, index, uint32(length));
            for (uint256 i; i < length; ++i) values[done + i] = words[i];
            done += length;
        }
    }

    /// @dev ABI-compatible with PartitionedInputCatalog. pageCount is the logical
    ///      4096-word block count, never a count of additional deployed contracts.
    function streamInfo(bytes32 id) external view returns (
        bytes32 role, uint64 totalWords, uint64 appendedWords, uint64 pageCount, bool isSealed, bytes32 commitment
    ) {
        Stream storage stream = _get(id);
        return (stream.role, stream.totalWords, stream.appendedWords,
            uint64((uint256(stream.appendedWords) + PAGE_WORDS - 1) / PAGE_WORDS), stream.isSealed, stream.commitment);
    }

    function _bank(uint8 index) private view returns (Bank storage bank) {
        bank = _banks[index];
        if (bank.instance.code.length == 0 || bank.instance.codehash != bank.codeHash) revert BankChanged();
    }
    function _get(bytes32 id) private view returns (Stream storage stream) {
        stream = _streams[id];
        if (!stream.exists) revert UnknownStream();
    }
    function _sealed(bytes32 id) private view returns (Stream storage stream) {
        stream = _get(id);
        if (!stream.isSealed) revert IncompleteStream();
    }
}

contracts/analysis/UncertaintyAndResults.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;
import {FloatMath} from "../math/FloatMath.sol";
import {ReducedPotentialCollector} from "./ReducedPotentialCollector.sol";
import {MBARFreeEnergyEstimator} from "./MBARFreeEnergyEstimator.sol";
import {SamplingDiagnostics} from "./SamplingDiagnostics.sol";
import {IMolecularCampaignSource} from "../interfaces/IMolecularCampaignSource.sol";

/// @notice Mean and SEM of a complete preregistered set of paired leg estimates.
/// @dev Repeat-level SEM is not MBAR covariance, a confidence interval, proof of
///      equilibration, or a remedy for shared systematic bias among repeats.
contract UncertaintyAndResults {
    error Unauthorized();error InvalidInput();error UnknownResult();error Terminal();error DependencyChanged();
    address public immutable owner;
    SamplingDiagnostics public immutable diagnostics;MBARFreeEnergyEstimator public immutable estimator;
    ReducedPotentialCollector public immutable collector;FloatMath public immutable numericalMath;
    bytes32[4] public dependencyHashes;bytes32 public immutable configurationHash;
    bytes32 public constant COMPLEX_LEG=keccak256("ORVIA.COMPLEX.v1");
    bytes32 public constant SOLVENT_LEG=keccak256("ORVIA.SOLVENT.v1");
    uint256 public constant MAX_REPEATS=32;uint256 public constant MAX_WORK=8;
    struct Plan {
        bytes32 campaignHash;bytes32 protocolHash;bytes32 policyHash;bytes32 commitment;bytes16 kT;uint8 states;
        bytes32[] complexSeries;bytes32[] solventSeries;mapping(bytes32=>bool) seeds;
        address molecularSource;bytes32 molecularSourceHash;bytes32 samplingPolicyHash;
        bytes32 complexModel;bytes32 solventModel;
        bytes32[] complexCampaigns;bytes32[] solventCampaigns;
        bytes32[] complexCommitments;bytes32[] solventCommitments;
    }
    struct Result {
        bytes32 planId;bytes32 commitment;uint8 cursor;bool completed;bytes16 mean;bytes16 m2;bytes16 sem;
        uint256[] complexDiagnostics;uint256[] solventDiagnostics;
    }
    struct LegResult {ReducedPotentialCollector.Configuration config;bytes32 seriesId;bytes32 commitment;bytes16 g;uint256 analysisId;}
    mapping(bytes32=>bytes32)public campaignPlan;
    mapping(bytes32=>Plan)private _plans;mapping(uint256=>Result)private _results;uint256 public nextResultId=1;
    event PlanRegistered(bytes32 indexed planId,bytes32 indexed campaignHash,bytes32 commitment);
    event ResultCreated(uint256 indexed id,bytes32 indexed planId,bytes32 commitment);
    event ResultCompleted(uint256 indexed id,bytes16 deltaDeltaG,bytes16 repeatSEM,uint8 repeats);
    constructor(address diagnostics_,address owner_){
        if(diagnostics_.code.length==0||owner_==address(0))revert InvalidInput();owner=owner_;diagnostics=SamplingDiagnostics(diagnostics_);
        estimator=diagnostics.estimator();collector=diagnostics.collector();numericalMath=diagnostics.numericalMath();
        dependencyHashes=[diagnostics_.codehash,address(estimator).codehash,address(collector).codehash,address(numericalMath).codehash];
        configurationHash=keccak256(abi.encode(owner_,diagnostics_,address(estimator),address(collector),address(numericalMath),dependencyHashes));
    }
    function registerPlan(bytes32 planId,bytes32 campaignHash,bytes32[] calldata complexSeries,bytes32[] calldata solventSeries)external{
        if(msg.sender!=owner)revert Unauthorized();_dependencies();
        if(planId==bytes32(0)||campaignHash==bytes32(0)||campaignPlan[campaignHash]!=bytes32(0)||_plans[planId].campaignHash!=bytes32(0)
            ||complexSeries.length<3||complexSeries.length>MAX_REPEATS||complexSeries.length!=solventSeries.length)revert InvalidInput();
        campaignPlan[campaignHash]=planId;
        Plan storage p=_plans[planId];p.campaignHash=campaignHash;p.complexSeries=complexSeries;p.solventSeries=solventSeries;
        p.commitment=keccak256(abi.encode(bytes32("ORVIA-REPEAT-PLAN-v1"),block.chainid,address(this),planId,
            configurationHash,campaignHash,complexSeries,solventSeries));
        for(uint256 i;i<complexSeries.length;++i)_registerPair(p,complexSeries[i],solventSeries[i],i);
        emit PlanRegistered(planId,campaignHash,p.commitment);
    }
    function _registerPair(Plan storage p,bytes32 complexId,bytes32 solventId,uint256 index)private{
        (ReducedPotentialCollector.Configuration memory c,bytes32 cd,uint32 cn,bool cs)=collector.seriesInfo(complexId);
        (ReducedPotentialCollector.Configuration memory s,bytes32 sd,uint32 sn,bool ss)=collector.seriesInfo(solventId);
        if(cn!=0||sn!=0||cs||ss||c.leg!=COMPLEX_LEG||s.leg!=SOLVENT_LEG||c.protocolHash!=s.protocolHash
            ||c.repeatSeed!=s.repeatSeed||c.kT!=s.kT||c.stateCount!=s.stateCount||p.seeds[c.repeatSeed])revert InvalidInput();
        bytes32 policy=_policy(c);if(policy!=_policy(s))revert InvalidInput();
        if(index==0){p.protocolHash=c.protocolHash;p.policyHash=policy;p.kT=c.kT;p.states=c.stateCount;}
        else if(p.protocolHash!=c.protocolHash||p.policyHash!=policy||p.kT!=c.kT||p.states!=c.stateCount)revert InvalidInput();
        p.seeds[c.repeatSeed]=true;p.commitment=keccak256(abi.encode(p.commitment,index,cd,sd,c.repeatSeed));
    }
    /// @notice Preregister molecular repeats before any window starts. Selected
    ///         series are resolved later using the frozen on-chain thinning rule.
    function registerMolecularPlan(bytes32 planId,bytes32 campaignHash,address source,
        bytes32[] calldata complexCampaigns,bytes32[] calldata solventCampaigns)external{
        if(msg.sender!=owner)revert Unauthorized();_dependencies();
        if(planId==bytes32(0)||campaignHash==bytes32(0)||campaignPlan[campaignHash]!=bytes32(0)||_plans[planId].campaignHash!=bytes32(0)
            ||complexCampaigns.length<3||complexCampaigns.length>MAX_REPEATS||complexCampaigns.length!=solventCampaigns.length
            ||source.code.length==0||collector.writer()!=source||collector.writerCodeHash()!=source.codehash)revert InvalidInput();
        IMolecularCampaignSource pipeline=IMolecularCampaignSource(source);
        if(pipeline.owner()!=owner||pipeline.collector()!=address(collector)||pipeline.estimator()!=address(estimator))revert InvalidInput();
        campaignPlan[campaignHash]=planId;Plan storage p=_plans[planId];p.campaignHash=campaignHash;
        p.molecularSource=source;p.molecularSourceHash=source.codehash;
        p.complexCampaigns=complexCampaigns;p.solventCampaigns=solventCampaigns;
        p.commitment=keccak256(abi.encode(bytes32("ORVIA-MOLECULAR-REPEATS-v1"),block.chainid,address(this),planId,
            configurationHash,campaignHash,source,p.molecularSourceHash,complexCampaigns,solventCampaigns));
        for(uint256 i;i<complexCampaigns.length;++i)_registerMolecularPair(p,i);
        emit PlanRegistered(planId,campaignHash,p.commitment);
    }
    function _registerMolecularPair(Plan storage p,uint256 index)private{
        IMolecularCampaignSource pipeline=IMolecularCampaignSource(p.molecularSource);
        IMolecularCampaignSource.Registration memory c=pipeline.campaignRegistration(p.complexCampaigns[index]);
        IMolecularCampaignSource.Registration memory s=pipeline.campaignRegistration(p.solventCampaigns[index]);
        if(c.commitment==bytes32(0)||s.commitment==bytes32(0)||c.selectedSeries==s.selectedSeries
            ||c.config.leg!=COMPLEX_LEG||s.config.leg!=SOLVENT_LEG||c.config.protocolHash!=s.config.protocolHash
            ||c.config.repeatSeed!=s.config.repeatSeed||c.config.kT!=s.config.kT||c.config.stateCount!=s.config.stateCount
            ||p.seeds[c.config.repeatSeed]||c.samplingPolicyHash!=s.samplingPolicyHash)revert InvalidInput();
        bytes32 policy=_policy(c.config);if(policy!=_policy(s.config))revert InvalidInput();
        if(index==0){
            p.protocolHash=c.config.protocolHash;p.policyHash=policy;p.kT=c.config.kT;p.states=c.config.stateCount;
            p.samplingPolicyHash=c.samplingPolicyHash;p.complexModel=c.modelHash;p.solventModel=s.modelHash;
        }else if(p.protocolHash!=c.config.protocolHash||p.policyHash!=policy||p.kT!=c.config.kT||p.states!=c.config.stateCount
            ||p.samplingPolicyHash!=c.samplingPolicyHash||p.complexModel!=c.modelHash||p.solventModel!=s.modelHash)revert InvalidInput();
        p.seeds[c.config.repeatSeed]=true;p.complexSeries.push(c.selectedSeries);p.solventSeries.push(s.selectedSeries);
        p.complexCommitments.push(c.commitment);p.solventCommitments.push(s.commitment);
        p.commitment=keccak256(abi.encode(p.commitment,index,c,s));
    }
    function createResult(bytes32 planId,uint256[] calldata complexDiagnostics,uint256[] calldata solventDiagnostics)external returns(uint256 id){
        _dependencies();Plan storage p=_plan(planId);
        if(complexDiagnostics.length!=p.complexSeries.length||solventDiagnostics.length!=p.solventSeries.length)revert InvalidInput();
        id=nextResultId++;Result storage r=_results[id];r.planId=planId;
        r.complexDiagnostics=complexDiagnostics;r.solventDiagnostics=solventDiagnostics;
        r.commitment=keccak256(abi.encode(bytes32("ORVIA-REPEAT-RESULT-v1"),block.chainid,address(this),id,
            configurationHash,planId,p.commitment,complexDiagnostics,solventDiagnostics));
        emit ResultCreated(id,planId,r.commitment);
    }
    function advanceResult(uint256 id,uint256 workLimit)external returns(uint256 processed,bool completed){
        _dependencies();if(workLimit==0||workLimit>MAX_WORK)revert InvalidInput();Result storage r=_get(id);if(r.completed)revert Terminal();
        while(processed<workLimit&&!r.completed){_repeat(r);++processed;}
        completed=r.completed;if(completed)emit ResultCompleted(id,r.mean,r.sem,r.cursor);
    }
    function _repeat(Result storage r)private{
        Plan storage p=_plan(r.planId);
        LegResult memory c=_leg(r.complexDiagnostics[r.cursor],COMPLEX_LEG);
        LegResult memory s=_leg(r.solventDiagnostics[r.cursor],SOLVENT_LEG);
        if(c.seriesId!=p.complexSeries[r.cursor]||s.seriesId!=p.solventSeries[r.cursor])revert InvalidInput();
        if(p.molecularSource!=address(0)){
            if(p.molecularSource.codehash!=p.molecularSourceHash)revert DependencyChanged();
            _assertMolecularLeg(p,p.complexCampaigns[r.cursor],p.complexCommitments[r.cursor],c);
            _assertMolecularLeg(p,p.solventCampaigns[r.cursor],p.solventCommitments[r.cursor],s);
        }
        r.commitment=keccak256(abi.encode(r.commitment,r.cursor,c.commitment,s.commitment));
        _accumulate(r,numericalMath.sub(c.g,s.g));
    }
    function _assertMolecularLeg(Plan storage p,bytes32 campaign,bytes32 expected,LegResult memory leg)private view{
        (bytes32 commitment,bytes32 series,uint256 analysis)=IMolecularCampaignSource(p.molecularSource).campaignAnalysis(campaign);
        if(commitment!=expected||series!=leg.seriesId||analysis!=leg.analysisId||leg.config.runHash!=expected)revert DependencyChanged();
    }
    function _policy(ReducedPotentialCollector.Configuration memory c)private pure returns(bytes32){
        return keccak256(abi.encode(c.mbarTolerance,c.overlapThreshold,c.minimumESS,c.normalizationTolerance));
    }
    function _accumulate(Result storage r,bytes16 value)private{
        FloatMath m=numericalMath;++r.cursor;bytes16 delta=m.sub(value,r.mean);
        bytes16 meanIncrement=m.div(delta,m.fromUInt(r.cursor));r.mean=m.add(r.mean,meanIncrement);
        r.m2=m.add(r.m2,m.mul(delta,m.sub(value,r.mean)));
        if(r.cursor==r.complexDiagnostics.length){
            if(m.compare(r.m2,bytes16(0))<0)revert InvalidInput();
            bytes16 denominator=m.fromUInt(uint256(r.cursor)*(r.cursor-1));
            r.sem=m.sqrt(m.div(r.m2,denominator));r.completed=true;
        }
    }
    function _leg(uint256 diagnosticId,bytes32 expectedLeg)private view returns(LegResult memory out){
        (uint256 analysisId,bytes32 diagnosticCommitment)=diagnostics.assertAccepted(diagnosticId);
        out.analysisId=analysisId;
        (bytes32 seriesId,bytes32 analysisCommitment,,uint8 states)=estimator.assertConverged(analysisId);
        (out.config,,,)=collector.seriesInfo(seriesId);if(out.config.leg!=expectedLeg)revert InvalidInput();out.seriesId=seriesId;
        bytes16 difference=numericalMath.sub(estimator.fAt(analysisId,states-1),estimator.fAt(analysisId,0));
        out.g=numericalMath.mul(out.config.kT,difference);
        out.commitment=keccak256(abi.encode(diagnosticId,diagnosticCommitment,analysisId,analysisCommitment));
    }
    function planInfo(bytes32 planId)external view returns(bytes32 campaignHash,bytes32 protocolHash,bytes32 commitment,bytes32[] memory complexSeries,bytes32[] memory solventSeries){
        Plan storage p=_plan(planId);return(p.campaignHash,p.protocolHash,p.commitment,p.complexSeries,p.solventSeries);
    }
    function molecularPlanInfo(bytes32 planId)external view returns(address source,bytes32 sourceHash,bytes32[] memory complexCampaigns,bytes32[] memory solventCampaigns){
        Plan storage p=_plan(planId);return(p.molecularSource,p.molecularSourceHash,p.complexCampaigns,p.solventCampaigns);
    }
    function resultInfo(uint256 id)external view returns(bytes32 planId,bytes32 protocolHash,bytes32 commitment,uint8 repeatsCompleted,uint256 repeatsExpected,bool completed,bytes16 deltaDeltaG,bytes16 repeatSEM){
        Result storage r=_get(id);return(r.planId,_plans[r.planId].protocolHash,r.commitment,r.cursor,r.complexDiagnostics.length,r.completed,r.mean,r.sem);
    }
    function _dependencies()private view{if(address(diagnostics).codehash!=dependencyHashes[0]||address(estimator).codehash!=dependencyHashes[1]||address(collector).codehash!=dependencyHashes[2]||address(numericalMath).codehash!=dependencyHashes[3])revert DependencyChanged();}
    function _plan(bytes32 planId)private view returns(Plan storage p){p=_plans[planId];if(p.campaignHash==bytes32(0))revert InvalidInput();}
    function _get(uint256 id)private view returns(Result storage r){r=_results[id];if(r.planId==bytes32(0))revert UnknownResult();}
}

contracts/analysis/SamplingDiagnostics.s.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;
import {FloatMath} from "../math/FloatMath.sol";
import {ReducedPotentialCollector} from "./ReducedPotentialCollector.sol";
import {MBARFreeEnergyEstimator,IMBARScalarMath} from "./MBARFreeEnergyEstimator.sol";

/// @notice Resumable MBAR weight ESS and overlap diagnostics.
/// @dev Weight ESS does not correct temporal correlation or prove equilibration.
contract SamplingDiagnostics {
    error InvalidInput();error UnknownDiagnostic();error Terminal();error DependencyChanged();
    enum Status { Missing, Weights, Overlap, Summary, Completed }
    MBARFreeEnergyEstimator public immutable estimator;
    ReducedPotentialCollector public immutable collector;
    FloatMath public immutable numericalMath;
    IMBARScalarMath public immutable scalarMath;
    bytes32[4] public dependencyHashes;
    bytes32 public immutable configurationHash;
    bytes16 private constant ONE=0x3fff0000000000000000000000000000;
    uint256 public constant MAX_WORK=32;
    struct Diagnostic {
        uint256 analysisId;bytes32 seriesId;bytes32 analysisCommitment;bytes32 commitment;
        uint32 samples;uint8 states;uint32 n;uint8 i;uint8 j;Status status;
        bytes16 edgeThreshold;bytes16 minimumESS;bytes16 normalizationTolerance;
        bool normalized;bool sufficientESS;bool connected;
        bytes16 accumulator;bytes16[16] weightSum;bytes16[16] weightSquared;bytes16[16] effectiveSamples;
        uint16[16] adjacency;
        mapping(uint256=>bytes16) weights;mapping(uint256=>bytes16) overlaps;
    }
    mapping(uint256=>Diagnostic) private _diagnostics;uint256 public nextDiagnosticId=1;
    event DiagnosticCreated(uint256 indexed id,uint256 indexed analysisId,bytes32 commitment);
    event DiagnosticCompleted(uint256 indexed id,bool normalized,bool sufficientESS,bool connected);
    constructor(address estimator_) {
        if(estimator_.code.length==0)revert InvalidInput();
        estimator=MBARFreeEnergyEstimator(estimator_);collector=estimator.collector();numericalMath=estimator.numericalMath();scalarMath=estimator.scalarMath();
        dependencyHashes=[estimator_.codehash,address(collector).codehash,address(numericalMath).codehash,address(scalarMath).codehash];
        configurationHash=keccak256(abi.encode(estimator_,address(collector),address(numericalMath),address(scalarMath),dependencyHashes));
    }
    function createDiagnostic(uint256 analysisId,bytes16 edgeThreshold,bytes16 minimumESS,bytes16 normalizationTolerance)external returns(uint256 id){
        _dependencies();FloatMath m=numericalMath;
        if(!m.isFinite(edgeThreshold)||!m.isFinite(minimumESS)||!m.isFinite(normalizationTolerance)
            ||m.compare(edgeThreshold,bytes16(0))<=0||m.compare(edgeThreshold,ONE)>=0
            ||m.compare(minimumESS,ONE)<0||m.compare(normalizationTolerance,bytes16(0))<=0||m.compare(normalizationTolerance,ONE)>=0)revert InvalidInput();
        (bytes32 seriesId,bytes32 commitment,uint32 samples,uint8 states)=estimator.assertConverged(analysisId);
        if(m.compare(minimumESS,m.fromUInt(samples))>0)revert InvalidInput();
        _assertPolicy(seriesId,edgeThreshold,minimumESS,normalizationTolerance);
        id=nextDiagnosticId++;Diagnostic storage d=_diagnostics[id];
        d.analysisId=analysisId;d.seriesId=seriesId;d.analysisCommitment=commitment;d.samples=samples;d.states=states;
        d.edgeThreshold=edgeThreshold;d.minimumESS=minimumESS;d.normalizationTolerance=normalizationTolerance;
        d.normalized=true;d.sufficientESS=true;d.status=Status.Weights;
        d.commitment=_commitment(d,id);
        emit DiagnosticCreated(id,analysisId,d.commitment);
    }
    function _assertPolicy(bytes32 seriesId,bytes16 edge,bytes16 ess,bytes16 normalization)private view{
        (ReducedPotentialCollector.Configuration memory c,,,)=collector.seriesInfo(seriesId);
        if(edge!=c.overlapThreshold||ess!=c.minimumESS||normalization!=c.normalizationTolerance)revert InvalidInput();
    }
    function _commitment(Diagnostic storage d,uint256 id)private view returns(bytes32){
        bytes32 thresholds=keccak256(abi.encode(d.edgeThreshold,d.minimumESS,d.normalizationTolerance));
        return keccak256(abi.encode(bytes32("ORVIA-MBAR-DIAG-v1"),block.chainid,address(this),id,
            configurationHash,d.analysisId,d.analysisCommitment,thresholds));
    }
    function advanceDiagnostic(uint256 id,uint256 workLimit)external returns(uint256 processed,bool complete){
        if(workLimit==0||workLimit>MAX_WORK)revert InvalidInput();_dependencies();Diagnostic storage d=_get(id);
        if(d.status==Status.Completed)revert Terminal();
        (,bytes32 commitment,,)=estimator.assertConverged(d.analysisId);if(commitment!=d.analysisCommitment)revert DependencyChanged();
        while(processed<workLimit&&d.status!=Status.Completed){
            if(d.status==Status.Weights)_weight(d);else if(d.status==Status.Overlap)_overlap(d);else _summary(d,id);++processed;
        }complete=d.status==Status.Completed;
    }
    function _weight(Diagnostic storage d)private{
        FloatMath m=numericalMath;
        bytes16 exponent=m.sub(estimator.fAt(d.analysisId,d.i),collector.potential(d.seriesId,d.n,d.i));
        exponent=m.sub(exponent,estimator.logDenominatorAt(d.analysisId,d.n));
        bytes16 weight=scalarMath.exp(exponent);d.weights[uint256(d.n)*d.states+d.i]=weight;
        d.weightSum[d.i]=m.add(d.weightSum[d.i],weight);d.weightSquared[d.i]=m.add(d.weightSquared[d.i],m.mul(weight,weight));
        ++d.i;if(d.i==d.states){d.i=0;++d.n;if(d.n==d.samples){d.n=0;d.status=Status.Overlap;}}
    }
    function _overlap(Diagnostic storage d)private{
        FloatMath m=numericalMath;uint256 offset=uint256(d.n)*d.states;
        bytes16 product=m.mul(d.weights[offset+d.i],d.weights[offset+d.j]);
        d.accumulator=d.n==0?product:m.add(d.accumulator,product);++d.n;
        if(d.n==d.samples){
            bytes16 value=m.mul(m.fromUInt(collector.stateCount(d.seriesId,d.j)),d.accumulator);
            d.overlaps[uint256(d.i)*d.states+d.j]=value;d.n=0;++d.j;
            if(d.j==d.states){d.j=0;++d.i;if(d.i==d.states){d.i=0;d.status=Status.Summary;}}
        }
    }
    function _summary(Diagnostic storage d,uint256 id)private{
        FloatMath m=numericalMath;uint256 i=d.i;
        if(m.compare(m.abs(m.sub(d.weightSum[i],ONE)),d.normalizationTolerance)>0)d.normalized=false;
        bytes16 ess=m.div(m.mul(d.weightSum[i],d.weightSum[i]),d.weightSquared[i]);d.effectiveSamples[i]=ess;
        if(m.compare(ess,d.minimumESS)<0)d.sufficientESS=false;
        uint16 edges=uint16(uint256(1)<<i);
        for(uint256 j;j<d.states;++j){
            if(m.compare(d.overlaps[i*d.states+j],d.edgeThreshold)>=0
                &&m.compare(d.overlaps[j*d.states+i],d.edgeThreshold)>=0)edges|=uint16(uint256(1)<<j);
        }d.adjacency[i]=edges;++d.i;
        if(d.i==d.states){
            uint16 reached=1;
            for(uint256 pass;pass<d.states;++pass){uint16 next=reached;for(uint256 j;j<d.states;++j)if(reached&(uint16(uint256(1)<<j))!=0)next|=d.adjacency[j];if(next==reached)break;reached=next;}
            d.connected=uint256(reached)==(uint256(1)<<d.states)-1;d.status=Status.Completed;
            emit DiagnosticCompleted(id,d.normalized,d.sufficientESS,d.connected);
        }
    }
    function runInfo(uint256 id)external view returns(uint256 analysisId,bytes32 commitment,Status status,uint32 sampleCursor,uint8 rowCursor,uint8 columnCursor,bool normalized,bool sufficientESS,bool connected){
        Diagnostic storage d=_get(id);return(d.analysisId,d.commitment,d.status,d.n,d.i,d.j,d.normalized,d.sufficientESS,d.connected);
    }
    function stateDiagnostics(uint256 id,uint256 k)external view returns(bytes16 weightSum,bytes16 effectiveSamples){Diagnostic storage d=_get(id);if(k>=d.states||d.status!=Status.Completed)revert InvalidInput();return(d.weightSum[k],d.effectiveSamples[k]);}
    function overlap(uint256 id,uint256 i,uint256 j)external view returns(bytes16){Diagnostic storage d=_get(id);if(i>=d.states||j>=d.states||d.status!=Status.Completed)revert InvalidInput();return d.overlaps[i*d.states+j];}
    function assertAccepted(uint256 id)external view returns(uint256 analysisId,bytes32 commitment){
        _dependencies();Diagnostic storage d=_get(id);if(d.status!=Status.Completed||!d.normalized||!d.sufficientESS||!d.connected)revert InvalidInput();
        (,bytes32 actual,,)=estimator.assertConverged(d.analysisId);if(actual!=d.analysisCommitment)revert DependencyChanged();return(d.analysisId,d.commitment);
    }
    function _dependencies()private view{if(address(estimator).codehash!=dependencyHashes[0]||address(collector).codehash!=dependencyHashes[1]||address(numericalMath).codehash!=dependencyHashes[2]||address(scalarMath).codehash!=dependencyHashes[3])revert DependencyChanged();}
    function _get(uint256 id)private view returns(Diagnostic storage d){d=_diagnostics[id];if(d.status==Status.Missing)revert UnknownDiagnostic();}
}

contracts/kernels/C4PairKernel.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {FloatMath} from "../math/FloatMath.sol";

/// @notice Raw unswitched pair term U = -C4/r^4 for supplied nonnegative C4.
/// @dev d = b-a; F_A = +4*C4*d/r^6 and F_B = -F_A. The caller supplies a
///      unit-consistent pair coefficient and displacement. No mixing, cutoff,
///      switch, tail correction, exclusion or alchemical policy is selected.
contract C4PairKernel {
    error InvalidMathContract();
    error DependencyChanged();
    error NonFiniteInput();
    error NegativeC4();
    error CoefficientOutsideDomain();
    error DisplacementOutsideDomain();
    error ZeroSeparation();
    error SeparationOutsideDomain();

    FloatMath public immutable numericalMath;
    bytes32 public immutable numericalMathCodeHash;
    bytes32 public constant KERNEL_ID = keccak256("ORVIA.C4PairKernel.v1.RawUnswitched.BoundedBinary128");
    // Engineering bounds, not a physical cutoff or force-field parameter choice.
    // Positive C4 and nonzero |d_i| lie in [2^-256,2^256]. Computed r^2 also
    // lies in [2^-256,2^256], keeping active products/quotients normal and finite.
    bytes16 public constant MIN_POSITIVE_INPUT = 0x3eff0000000000000000000000000000;
    bytes16 public constant MAX_POSITIVE_INPUT = 0x40ff0000000000000000000000000000;
    bytes16 private constant FOUR = 0x40010000000000000000000000000000;

    constructor(address numericalMath_) {
        if (numericalMath_.code.length == 0) revert InvalidMathContract();
        numericalMath = FloatMath(numericalMath_);
        numericalMathCodeHash = numericalMath_.codehash;
    }

    function evaluate(bytes16[3] calldata displacement, bytes16 c4)
        external view returns (bytes16 energy, bytes16[3] memory forceOnA)
    {
        FloatMath math = numericalMath;
        if (address(math).codehash != numericalMathCodeHash) revert DependencyChanged();
        if (!math.isFinite(c4)) revert NonFiniteInput();
        if (math.isNegative(c4)) revert NegativeC4();
        bool zeroCoefficient = math.isZero(c4);
        if (!zeroCoefficient && (math.compare(c4, MIN_POSITIVE_INPUT) < 0
            || math.compare(c4, MAX_POSITIVE_INPUT) > 0)) revert CoefficientOutsideDomain();
        bytes16 rSquared;
        for (uint256 axis; axis < 3; ++axis) {
            bytes16 component = displacement[axis];
            if (!math.isFinite(component)) revert NonFiniteInput();
            bytes16 magnitude = math.abs(component);
            if (!math.isZero(magnitude) && (math.compare(magnitude, MIN_POSITIVE_INPUT) < 0
                || math.compare(magnitude, MAX_POSITIVE_INPUT) > 0)) revert DisplacementOutsideDomain();
            rSquared = math.add(rSquared, math.mul(component, component));
        }
        if (math.isZero(rSquared)) revert ZeroSeparation();
        if (math.compare(rSquared, MIN_POSITIVE_INPUT) < 0
            || math.compare(rSquared, MAX_POSITIVE_INPUT) > 0) revert SeparationOutsideDomain();
        // Zero strength still requires valid, nonsingular geometry.
        if (zeroCoefficient) return (energy, forceOnA);
        bytes16 magnitudeEnergy = math.div(math.div(c4, rSquared), rSquared);
        energy = math.neg(magnitudeEnergy);
        bytes16 forceScale = math.div(math.mul(FOUR, magnitudeEnergy), rSquared);
        for (uint256 axis; axis < 3; ++axis) forceOnA[axis] = math.mul(forceScale, displacement[axis]);
    }
}
